i64 f(i64 b, i64 n) {
  if (n < b) return n;
  return n % b + f(b, n / b);
}

void solve(istream& in, ostream& out) {
  auto n = next<i64>(in);
  auto s = next<i64>(in);
  FORA(b, 2, 1000001) {
    if (f(b, n) == s) {
      out << b << "\n";
      return;
    }
  }
  if (n < s) {
    out << -1 << "\n";
    return;
  }

  auto x = n - s;
  i64 res = (i64)1e18;
  for (i64 d = 1; d * d <= x; ++d) {
    if (x % d == 0) {

      auto b = x / d + 1;
      if (f(b, n) == s) {
        res = min(res, b);
      }

      b = d + 1;
      if (f(b, n) == s) {
        res = min(res, b);
      }
    }
  }
  if (res >= 1e18) {
    out << -1 << "\n";
  } else {
    out << res << "\n";
  }
  // n = pb + q
  // p + q = s
  // n - s = p(b - 1)
}

