ll solve(ll n, ll s) {
    if (n < s) return -1LL;
    if (n == s) return n+1LL;
    // if (s == 1) return n;

    ll sq = sqrt(n);
    for (ll b=2; b<=sq; ++b) {
        if (f(b,n) == s) return b;
    }

    // q + r = s
    // qb + r = n
    // 2桁なので q<√n
    ll bmin = n+1LL;
    for (ll q=1; q<=sq; ++q) {
        ll r = s - q;
        if ((n - r) % q == 0) {
            ll b = (n-r) / q;
            if (f(b,n) == s) {
                bmin = min(bmin, b);
            }
        }
    }

    return (bmin == n+1LL) ? -1 : bmin;
}

