int f(int b, int n) {
  if (n < b) return n;
  return f(b, n / b) + (n % b);
}

signed main() {
  int n, s;
  cin >> n >> s;
  if (n < s) {
    cout << -1 << endl;
    return 0;
  }
  if (n == s) {
    cout << n + 1 << endl;
    return 0;
  }
  for (int i = 2; i <= sqrt(n); i++) {
    if (f(i, n) == s) {
      cout << i << endl;
      return 0;
    }
  }
  for (int i = 1; i <= sqrt(n); i++) {
    if ((n - s) % i) continue;
    int b = (n - s) / i + 1;
    if (f(b, n) == s) {
      cout << b << endl;
      return 0;
    }
  }
  cout << -1 << endl;
  return 0;
}

