    ll v = calc(b, n);
    if(v == s) {
      printf("%lld\n", b);
      return 0;
    }
  }

  ll res = n*2;
  for(ll d = 1; d*d < n; ++d) {
    ll bg = n / d;
    ll ed = n / (d+1);
    ll m = n % bg + d;
    if (s-m >= 0 && (s-m)%d == 0) {
      ll x = bg - (s-m) / d;
      if(ed < x && x <= bg && x < res) {
        res = x;
      }
    }
  }
  if(s == n && n+1 < res) {
    res = n + 1;
  }
  if (res == n*2) {
    res = -1;
  }
  printf("%lld\n", res);

  return 0;
}

