ll calc_digits(ll x, ll mod)
{
    ll ret = 1LL;
    ll xx = x;
    while (xx >= mod) {
        xx /= mod;
        ret++;
    }
    debug_printf("---- calc_digits x=%lld mod=%lld --> ret=%lld\n",
                 x, mod, ret);
    return ret;
}

ll calc_digits3_maxmod(ll n)
{
    ll mod_floor = 2LL;
    ll mod_ceil = n + 1LL;
    ll mod = (mod_floor + mod_ceil) / 2LL;
    ll mod_ret = -1LL;

    for ( ; mod_floor <= mod_ceil; mod = (mod_floor + mod_ceil) / 2LL) {
        debug_printf("   mod=%lld\n", mod);
        ll digits = calc_digits(n, mod);
        if (digits < 3LL) {
            mod_ceil = mod - 1LL;
        }
        else {
            mod_floor = mod + 1LL;
            mod_ret = max(mod_ret, mod);
        }
    }

    debug_printf("---- digits_maxmod = %lld\n", mod_ret);
    return mod_ret;
}

void solve_digits3(ll n, ll sum, ll digits3_maxmod)
{
    srep (mod, 2LL, digits3_maxmod + 1LL) {
        ll dsum = 0LL;
        ll nn = n;
        while (nn) {
            dsum += (nn % mod);
            nn /= mod;
        }
        debug_printf("---- mod=%lld n=%lld --> dsum=%lld\n", mod, n, dsum);
        if (sum == dsum) {
            cout << mod;
            exit(0);
        }
    }
}

void solve_digits2(ll n, ll sum, ll digits2_minmod)
{
    rrep (digits1, digits2_minmod) {
        if (digits1 <= 0LL) break;
        if (sum < digits1) continue;
        ll digits0 = sum - digits1;
        if (n < digits0) continue;
        if ((n - digits0) % digits1 != 0) continue;
        ll mod = (n - digits0) / digits1;
        if (digits0 >= mod) continue;
        if (digits1 >= mod) continue;

        debug_printf("n=%lld sum=%lld digits2_minmod=%lld --> "
                     "digits1=%lld digits0=%lld mod=%lld\n",
                     n, sum, digits2_minmod, digits1, digits0, mod);

        cout << mod;
        exit(0);
    }
}

void solve_digits1(ll n, ll sum)
{
    if (n == sum) {
        cout << n + 1LL;
        exit(0);
    }
}

int _main()
{
    ll n; llin(n);
    ll sum; llin(sum);

    ll digits3_maxmod = calc_digits3_maxmod(n);
    if (digits3_maxmod >= 2LL) solve_digits3(n, sum, digits3_maxmod);

    ll digits2_minmod = (digits3_maxmod >= 2LL) ? digits3_maxmod + 1LL : 2LL;
    solve_digits2(n, sum, digits2_minmod);

    solve_digits1(n, sum);

    cout << -1;

    return 0;
}

