LL sum(LL n, LL b) {
  LL res = 0;
  while(n) {
    res += n % b;
    n /= b;
  }
  return res;
}

int main() {
  LL n,s;
  scanf("%lld%lld",&n,&s);
  LL ans = -1;
  LL b;
  for(b = 2; b * b <= n; b++) {
    if(sum(n,b) == s) {
      ans = b;
      break;
    }
  }
  if(ans != -1) {
    cout << ans << "\n";
    return 0;
  }
  b = n / b;
  while(b) {
    LL y = n / b;
    LL x = (n / (b + 1)) + 1;
    if(x > y) {
      b--;
      continue;
    }
    LL d1 = n % y;
    LL d2 = n % x;
    LL req = s - b;
    if(req >= d1 && req <= d2) {
      ans = x + (d2 - req);
      break;
    }
    b--;
  }
  if(ans == -1 && s == n) {
    ans = s + 1;
  }
  printf("%lld\n",ans);
  return 0;
}

