            int b = d + 1ll;
            if (f(b, n) == s) {
                ans = min(ans, b);
            }
            b = (n - s) / d + 1ll;
            if (f(b, n) == s) {
                ans = min(ans, b);
            }
        }
    }

    cout << (ans == inf ? -1 : ans) << endl;
}

