  if(n<b) return n;
  return f(b,n/b) + n%b;
}
void solve() {
  ll n,s;scanf("%lld %lld ",&n,&s);
  if(s==n) {
    printf("%lld\n", n+1);
    return;
  } else if(s==1) {
    printf("%lld\n", n);
    return;
  }
  ll b = 2;
  for(b = 2;b*b<=n;++b) {
    if(f(b,n)==s) {
      printf("%lld\n", b);
      return;
    }
  }
  const ll st = b;
  if(st<=n-1) {
    ll lim = n/st;
    for(ll k = lim;k>=1;--k) {
      ll l,r,mid;
      ll x,y;
      l = st,r = n-1;
      while(l<r) {
        mid = (l+r)/2;
        if(n/mid<k) {
          l = mid+1;
        } else {
          r = mid;
        }
      }
      if(n/l!=k) {
        continue;
      }
      x = l;
      r = n-1;
      while(l<r) {
        mid = (l+r+1)/2;
        if(n/mid==k) {
          l = mid;
        } else {
          r = mid-1;
        }
      }
      y = l;
      ll rem = n-s-k;
      if(rem<0 || rem%k!=0) {
        continue;
      }
      rem = rem/k;
      if(x<=rem && rem<=y) {
        printf("%lld\n", rem);
        return;
      }
    }
  }
  printf("-1\n");
}

