LL sumOfDigits(LL n, LL b) {
  if (n < b) {
    return n;
  }
  return sumOfDigits(n / b, b) + (LL)(n % b);
}

int main() {
  // ios_base::sync_with_stdio(false);
  // cin.tie(NULL);

  LL n, s;
  scanf("%lld%lld", &n, &s);

  if (s > n) {
    printf("-1\n");
    return 0;
  }

  if (n == s) {
    printf("%lld\n", n + 1);
    return 0;
  }

  FORS(i, 2, (int)sqrt(n)) {
    if (sumOfDigits(n, (LL)i) == s) {
      printf("%d\n", i);
      return 0;
    }
  }

  FORD(i, (int)sqrt(n-s), 1) {
    if ((n-s) % i == 0) {
      LL ans = ((n-s)/(LL)i + 1LL);
      if ((ans > (int)sqrt(n)) && (sumOfDigits(n, ans) == s)) {
        printf("%lld\n", ans);
        return 0;
      }
    }
  }

  printf("-1\n");
}

