ll n, m;

ll f(ll x, ll d) {
  if (x > d) return d;
  return (d % x) + f(x, d / x);
}

int main(){
  ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
//  freopen("abc.inp", "r", stdin); freopen("abc.out", "w", stdout);
  cin >> n >> m;
  ll ans = oo;
  if (m > n) return cout << -1, 0;
  if (n == m) ans = min(ans, n + 1);

  for (ll i = 2; i * i <= n; ++i) {
    if (f(i, n) == m) ans = min(ans, i);
  }
  ll k = n - m;

  for (ll p = 1; p * p <= k; ++p) {
    if (p > m) break;
    ll ret = k / p + 1;
    ll q = n - (p * ret);
    if (p + q == m) ans = min(ans, ret);
  }

  cout << (ans == oo ? -1 : ans);
  return 0;
}

