/*
f(b, n) = s

n := sum{a_k*b^k | 0<=k}
s := sum{a_k | 0<=k}

(1) 2 <= b <= Sqrt(n) (範囲10^6程度)
	-> 全   探   索
(2) Sqrt(n) < b < n
	-> n < b^2
	   ∴ n := pb+q と書ける！ (0 <= p, q < b)
	   このとき s = p + q
	   さらに、
	     n = pb+q
		   > p^2 + q
		   > p^2
	   ∴ 0 < p < Sqrt(n) (範囲10^6程度)
			-> 全   探   索   可   能
	   p=p'のとき、
	     q = n%p'
	   となる

∴
(1)のとき、
ans = min{b | f(b, n) = s (b∊[2, Sqrt(n)]) }

(2)のとき、
ans = min{b | n=pb+q (p∊(0, Sqrt(n)), q = n%p)}
*/

ll f(ll b, ll n) {
	ll res = 0;
	while (n != 0) {
		res += n%b;
		n /= b;
	}
	return res;
}

signed main() {
	INIT;
	VAR(ll, n, s);
	ll ans = INFLL;
	if (n == s) {
		ans = n + 1;
	}
	else {
		FORLL(b, 2, std::sqrt(n) + 1) {
			if (f(b, n) == s) ans = std::min(ans, b);
		}
		FORLL(p, 1, std::sqrt(n)) {
			ll q = s - p;
			ll b = (n - q) / p;
			if (f(b, n) == s) ans = std::min(ans, b);
		}
	}
	OUT(((ans != INFLL) ? ans : -1))BR;
	return 0;
}

