static const ll INF = 1000000000000000000LL;

bool solve(ll b, ll N, ll S){
  ll sum = 0;
  while(N>0){
    sum += N%b;
    N/=b;
  }
  return S == sum;
}


int main(){
  ll N, S;
  cin >> N >> S;

  if(S > N){
    cout << -1 << endl;
    return 0;
  }
  if(S == N){
    cout << N+1 << endl;
    return 0;
  }

  // 3桁以上の範囲
  REP(b,2,sqrt(N)+5){
    if(solve(b, N, S)){
      cout << b << endl;
      return 0;
    }
  }

  // 2桁
  ll ret = INF;
  REP(p,1,sqrt(N)+5){
    ll b = (N-(S-p))/p;
    if(solve(b, N, S)){
      ret = min(ret, b);
    }    
  }

  if(ret == INF) cout << -1 << endl;
  else cout << ret << endl;


  return 0;
}

