std::vector<intmax_t> divisor(intmax_t n) {
  std::vector<intmax_t> res;
  for (intmax_t i = 1; i*i <= n; ++i) {
    if (n % i == 0) {
      res.push_back(i);
      if (i != n/i)
        res.push_back(n/i);
    }
  }
  std::sort(res.begin(), res.end());
  return res;
}

intmax_t digitsum(intmax_t n, intmax_t base=10) {
  intmax_t res = 0;
  for (; n; n /= base) res += n % base;
  return res;
}

