ll func(ll b,ll N){
    if(N<b){
        return N;
    }
    else{
        return func(b,N/b)+N%b;
    }
    return -1;
}

int main(){
    ll n,s;
    cin >> n>> s;
    if(n<s){
        cout << -1 << endl;
        return 0;
    }
    else if(s==1&&n==1){
        cout << -1 << endl;
        return 0;
    }
    else if(s==1){
        cout << n << endl;
        return 0;
    }
    else if(n==s){
        cout << n+1 << endl;
        return 0;
    }
    else{
        for(ll i=2;i<=sqrt(n);i++){
            if(s==func(i,n)){
                cout << i << endl;
                return 0;
            }
        }
        ll b;
        for(ll i=0;i<sqrt(n);i++){
            b=(n-s)/(i+1);
            if(s==func(b,n)){
                cout << b << endl;
                return 0;
            }
        }
    }
    cout << -1 << endl;
    return 0;
}

