ll f(ll b, ll n) {
	if(b > n) {
		return n;
	} else {
		return f(b, n / b) + n % b;
	}
}

int main() {
	ll n, s;
	cin >> n >> s;

	ll i = 2;
	for(; i * i <= n; ++i) {
		if(f(i, n) == s) {
			cout << i << endl;
			return 0;
		}
	}

	ll a = n - s;

	const ll inf = 1LL << 60;
	ll ans = inf;

	for(; i >= 1; --i) {
		if(a % i != 0) {
			continue;
		}

		ll b = a / i + 1;

		if(a == (n / b) * (b - 1)) {
			ans = min(ans, b);
		}
	}

