    template<class T> istream& operator>>(istream& is, vector<T>& vs) {
        for (auto it = vs.begin(); it != vs.end(); it++) is >> *it;
        return is;
    }

    ll N, S;
    void input() {
        cin >> N >> S;
    }

    bool check(ll b) {
        ll sum = 0;
        ll n = N;
        while (n > 0) {
            sum += n % b;
            n /= b;
        }
        return sum == S;
    }

    void solve() {

        if (N < S) {
            cout << -1 << endl;
            return;
        }

        if (N == S) {
            cout << N + 1 << endl;
            return;
        }

        if (S == 1) {
            cout << N << endl;
            return;
        }

        ll Z = N - S;
        vector<ll> cand;
        for (ll x = 1; x * x <= N; x++) {
            if (Z % x != 0) continue;
            if (check(x + 1)) {
                cout << x + 1 << endl;
                return;
            }
            if (check(Z / x + 1)) {
                cand.push_back(Z / x + 1);
            }
        }
        sort(cand.begin(), cand.end());
        if (cand.empty()) {
            cout << -1 << endl;
        } else {
            cout << cand.back() << endl;
        }

    }
}

