    }
    for(int i=2;i<=sqrt(N);i++) {
        tmp = N;
        ans = 0;
        while(tmp>0) {
            ll dt = tmp%i;
            if(dt<0) dt += i;
            ans += dt;
            tmp /= i;
        }
        if(ans==S) {
            cout << i << endl;
            return 0;
        }
    }
    const auto &res = prime_factorize(N-S);
