bool check(long long b, long long n, long long s) {
    long long res = 0;
    while (true) {
        if (n < b) {
            res += n;
            break;
        } else {
            res += n % b;
            n = n / b;
        }
    }
    if (res == s)
        return 1;
    else
        return 0;
}

