using namespace std;

typedef long long LL;


LL cal(LL num,LL BASE)
{
    LL sum = 0;
    while(num)
    {
        sum += num % BASE;
        num /= BASE;
    }

    return sum;
}

LL n,S;
vector<LL> V;

LL solve(LL num)
{
    for(int i = 2;i <= 1000000;++i)
        if(cal(n,i) == S) return i;


    if(num <= 0) return -1;

    LL m = sqrt(num+0.5);
    V.clear();

    for(int i = 1;i <= m;++i)
        if(num % i == 0)
        {
            LL a = i,b = num/i;

            a++,b++;
            V.push_back(a);
            V.push_back(b);
        }

    sort(V.begin(),V.end());
    int sz = V.size();
    for(int i = 0;i < sz;++i)
    {
        LL v = V[i];
        if(v < 2) continue;
        if(cal(n,v) == S) return v;
    }

    return -1;

}

