/*
・約数列挙
  > O(√n)
[使用例] vl div = divisor(105);
[備考] 整列されていない
*/

vl divisor(ll n) {
  vl ret;
  for(ll i = 1; i * i <= n; i++) {
    if (n % i == 0) {
      ret.PB(i);
      if (i * i != n) ret.PB(n/i);
    }
  }
  SORT(ret);
  return ret;
}

signed main() {

  SS(ll,N,S);

  if (N == S) return print(N + 1);

  // b-1 は n-s の約数
  vl dv = divisor(N - S);
  EACH(bb, dv) {
    // bb = b - 1
    ll b = bb + 1;
    ll num = N;
    ll sum = 0;
    while (num > 0) {
      sum += num % b;
      num /= b;
    }
    if (sum == S) return print(b);
  }

  print(-1);

}

