ll f(ll b, ll n) {
  if (n < b) {
    return n;
  }
  return f(b, n / b) + (n % b);
}

ll solve(ll n, ll s) {
  ll b = 2;
  while (n / b >= b) {
    if (f(b, n) == s) {
      return b;
    }
    ++b;
  }
  for (ll k = n / b; k >= 1; k--) {
    ll rem = s - k;
    if (rem < 0) {
      continue;
    }
    ll sb = max(b, (n + k) / (k + 1));
    if (n / sb != k) {
      continue;
    }
    ll sm = n % sb;
    if (rem > sm || (sm - rem) % k != 0) {
      continue;
    }
    return sb + (sm - rem) / k;
  }
  if (s == n) {
    return n + 1;
  }
  return -1;
}

