ll calc_f(ll b, ll n){
  if(n<b) return n;
  return calc_f(b, n/b) + n%b;
}

int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  ll n, s;
  cin >> n >> s;

  ll N = (ll)(sqrt((double)n)+1.0);

  FOR(b, 2, N+1){
    if(s == calc_f(b, n)){
      //cout << "p:" << s << " " << b << " " << n << "\n";
      cout << b << "\n";
      return 0;
    }
  }

  for(ll b=max(n-1, (ll)2); b<n+2; ++b){
    if(s == calc_f(b, n)){
      //cout << "p:" << s << " " << b << " " << n << "\n";
      cout << b << "\n";
      return 0;
    }
  }

  ll ans = -1;
  // N*b+k=n && N+k=s ~ 0*b+k=n && 0+k==s
  FOR(N_tmp, 1, N+1){
    ll k = s-N_tmp;
    if(n-k<=0) continue;
    if((n-k)%N_tmp==0){
      ll b = (n-k)/N_tmp;
      if(s == calc_f(b, n)){
        ans = b;
        //cout << "h:" <<  s << " " << ans << " " << n << "\n";
      }
    }
  }

  cout << ans << "\n";

