ll digSum(ll b, ll n) {
    if(n < b) return n;
    else return digSum(b, n/b) + (n % b);
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);

    ll n, s;
    cin >> n >> s;
    if(s == n) cout << n+1 << endl;
    else if(s > n) cout << -1 << endl;
    else {
        ll ans = INF;
        for(ll i = 2; i*i <= n; i ++) {
            if(digSum(i, n) == s) {
                cout << i << endl;
                return 0;
            }
        }
        ll toFac = n - s;
        for(ll i = 1; i*i <= toFac; i ++) {
            if(toFac % i) continue;
            ll canBe = toFac/i;
            if(((canBe + 1) > sqrt(n)) && (digSum(canBe+1, n) == s)) {
                ans = min(ans, canBe);
            } 
        }
        cout << ((ans != INF) ? ans : -1) << endl;
    }
}

