void solve() {
    if (n == s) {
        cout << n + 1 << endl;
        return ;
    }

    ll ans = INF * INF;

    for (ll b = 2; b * b <= n; ++b)
        if (f(b, n) == s)
            ans = min(ans, b);

    if (n - s > 0) {
        ll t = n - s;

