ll solve(ll n, ll s) {
    if (n < s) return -1LL;
    // if (s == 1) return n;
    if (n == s) return n+1LL;

    int maxk = 0;
    for (ll x=n; x; x>>=1LL) {
        ++maxk;
    }

    ll best = n+1LL;
    for (int k=maxk; k>=3; --k) {
        ll lo = ceill(powl(n, 1.0/k) - 1.0e-9); // lo < x <= hi
        ll hi = floorl(powl(n, 1.0/(k-1)) + 1.0e-9);
        if (lo > hi) continue;
        // fprintf(stderr, "k=%d, [%lld..%lld]\n", k,lo,hi);

        for (ll b=lo; b<=hi; ++b) {
            ll t = f(b,n);
            // fprintf(stderr, " f(b=%lld, n=%lld) = %lld : %lld\n", b,n,t,s);
            if (t == s) best = min(best, b);
        }
    }
    // if (best != n+1LL) return best;

    ll sq = sqrt(n);
    for (ll q=1; q<=sq; ++q) {
        ll r = s - q;
        if ((n - r) % q == 0) {
            ll b = (n-r) / q;
            if (f(b,n) == s) {
                best = min(best, b);
            }
        }
    }
    return (best == n+1LL) ? -1 : best;
}

