  // bx+y=n -> (b-1)x=(n-s) -> x=(n-s)/(b-1) (b^2>n,0<=x<b,0<=y<b)
  //  x+y=s
  ll m = n - s;
  if (m == 0) {
    printf("%lld\n", n + 1);
    return 0;
  }

  ll minb = LINF;
  for (ll c0 = 1; c0 * c0 <= m; c0++)
    if (m % c0 == 0) {
      ll c1 = m / c0;

      // b=c1+1,x=c0,y=n-bx=n-(c1+1)c0
      ll b = c1 + 1, x = c0, y = n - b * c0;
      if (x >= 0 && x < b && y >= 0 && y < b && minb > b) minb = b;

      // b=c0+1,x=c1,y=n-bx=n-(c0+1)c1
      b = c0 + 1, x = c1, y = n - b * c1;
      if (x >= 0 && x < b && y >= 0 && y < b && minb > b) minb = b;
    }

  printf("%lld\n", (minb >= LINF) ? -1LL : minb);
  return 0;
}

