ll solve(ll n, ll s) {
    if (n < s) return -1LL;
    // if (s == 1) return n;
    if (n == s) return n+1LL;

    int maxk = 0;
    for (ll x=n; x; x>>=1LL) {
        ++maxk;
    }

    ll best = n+1LL;
    for (int k=maxk; k>=3; --k) {
        ll lo = ceill(powl(n, 1.0/k) - 1.0e-9); // lo < x <= hi
        ll hi = floorl(powl(n, 1.0/(k-1)) + 1.0e-9);
        if (lo > hi) continue;
        // fprintf(stderr, "k=%d, [%lld..%lld]\n", k,lo,hi);

        for (ll b=lo; b<=hi; ++b) {
            ll t = f(b,n);
            // fprintf(stderr, " f(b=%lld, n=%lld) = %lld : %lld\n", b,n,t,s);
            if (t == s) best = min(best, b);
        }
    }
    // k=2
    // α + β = s
    // αb + β = n
    // α(b-1) = n - s
    ll d = n-s;
    ll q = sqrt(d);
    set<ll> el;
    for (ll b_=1; b_<=q; ++b_) { // b_ = b-1; b=1+b_
        if (d % b_) continue;
        el.insert(b_);
        el.insert(d / b_);
    }
    for (ll b_ : el) {
        ll b = 1 + b_;
        ll alpha = d / b_, beta = s - alpha;
        if (alpha < b && beta < b) {
            best = min(best, b);
        }
    }

    return (best == n+1LL) ? -1 : best;
}

int main() {
    ll n, s;
    cin >> n;
    cin >> s;
    cout << solve(n, s) << endl;
    return 0;
}

