const ll INF = 1LL << 60;

ll calc(ll b,ll n){

    if(n < b){
        return n;
    }else{
        return calc(b,n/b) + n % b;
    }
}

int main(){

    ll n,s;
    cin >> n >> s;

    if(n < s){
        cout << "-1" << endl;
        return 0;
    }
    if(n == s){
        cout << s+1 << endl;
        return 0;
    }
    ll mini = INF;

    for(ll i = 2;i*i <= n;i++){
        if(calc(i,n) == s){
            mini = min(mini,i);
        }
    }

    if(mini != INF){
        cout << mini << endl;
        return 0;
    }
    //ここからは2 <= b <= sqrt(n)までに解がなかった場合

    for(ll p = 1;p*p < n;p++){

        ll b = (n-s)/p+1;
        if((n-s) > p && calc(b,n) == s){
            mini = min(mini,b);
        }
    }

    if(mini != INF){
        cout << mini << endl;
    }else{
        cout << "-1" << endl;
    }



    return 0;
}

