unsigned long long int n, s, b;

unsigned long long int f(unsigned long long int b, unsigned long long int n) {
    if (n < b) {
        return n;
    } else {
        return f(b, floor(n / b)) + (n % b);
    }
}

unsigned long long int solve() {
    unsigned long long int sqn = floor(sqrt(n));
    unsigned long long int p = 1;
    b = 2;

    while (b <= sqn) {
        if (f(b, n) == s) break;
        b++;
    }
    if (b > sqn) {
        b = (n - s) / p + 1;
        while (p < sqn) {
            if (f(b, n) == s) break;
            p++;
            b = (n - s) / p + 1;
        }
    }
    if (p >= sqn) b = -1;
    return b;
}

int main() {
    scanf("%lld %lld", &n, &s);

    unsigned long long int ans;

    if (n == s) {
        ans = n+1;
    } else {
        ans = solve();
    }

    printf("%lld\n", ans);

    return 0;
}

