    while(true){
        if(i*i > n){
            break;
        }else{
            if(func(n,i) == s){
                cout << i << endl;
                return 0;
            }
        }
        i++;
    }

    while(i <= n){
        LL m = n/i;
        LL tmp = func(n,i);
        LL dist = tmp/m;
        LL min = func(n,dist+i);
        LL tdist = dist;
        LL t = func(n,dist+i+1);
        if(t < min){
            min = t;
            dist++;
        }
        if(tdist+i-1 > i){
            t = func(n,tdist+i-1);
            if(t < min){
                min = t;
                dist = tdist - 1;
            }
        }

        LL ret = bin_search(i,i+dist,n,s);

        if(func(n,ret) == s){
            cout << ret << endl;
            return 0;
        }
        i += dist+1;
    }

    cout << -1 << endl;

    return 0;
}

