            puts("-1");
            continue;
        }
        LL t=sqrt(n)+1;
        bool flag=false;
        // b<=sqrt(n)
        for (LL i=2;i<=t;i++)
            if (f(i,n)) {
                printf("%lld\n", i);
                flag=true;
                break;
            }
        if (flag) continue;

        // b>sqrt(n) b进制下只有两位
        // n=pb+q  s=p+q
        // n-s=p(b-1) => b=(n-s)/p+1
        LL ans=1e12;
        for (LL p=1;p*p<=n-s;p++) {
            if ((n-s)%p==0) {
                LL b=(n-s)/p+1;
                if (f(b,n)) {
                    flag=true;
                    ans=min(ans,b);
                }
            }
        }
        if (!flag) puts("-1");
        else printf("%lld\n", ans);
    }
    return 0;
}

