  return ans+n;
}


ll search(ll N,ll S){
  if(N == S) return N+1;
  ll ans = INF;

  for(int i=2; i<sqrt(N)+1; i++)if (function_f(i, N) == S) ans = min(ans, (ll)i);

  for(int i=1; i<sqrt(N); i++) {
    ll B = (N - S) / i + 1;
    if (function_f(B, N) == S) ans = min(ans, B);
  }

  return (ans == INF ? -1 : ans);

}


