ll n, s;
ll ans = 1e18;
const int N = 317000;

void check(ll b) {
  ll v = n, sum = 0;
  while (v) {
    sum += v % b; v /= b;
  }
  if (sum == s) {
    ans = min(ans, b);
  }
}

void relax(ll a) {
  ll b = s - a;
  ll B = (n - s) / a + 1;
  if (a < B && b < B && 0 <= b && 2 <= B && a * B + b == n) {
    ans = min(ans, B);
  }
}

void twoDigits() {
  if (n - s <= 0) return;
  ll v = n - s;
  for (ll mul = 1; mul * mul <= v; mul++) {
     if (v % mul == 0) {
       relax(mul);
       relax(v / mul);
     }
  }
}

void solve() {
  cin >> n >> s;
  if (s == 1) {
    ans = n;
  }
  if (n == s) {
    ans = min(ans, n + 1);
  }
  for (int b = 2; b < N; b++) {
    check(b);
  }
  twoDigits();
  cout << (ans == 1e18 ? -1 : ans);
}

