i64 f(i64 b,i64 n){
    if(n<b) return n;
    return n%b+f(b,n/b);
}

void solve(){
    i64 n,s;
    cin >> n >> s;

    i64 x=1000000;

    if(n<x){
        rep(b,2,n+2){
            if(f(b,n)==s){
                cout << b << endl;
                return;
            }
        }
        cout << -1 << endl;
        return;
    }

    rep(b,2,x){
        if(f(b,n)==s){
            cout << b << endl;
            return;
        }
    }

    i64 k=n-s;
    set<i64> bs;
    for(i64 i=1; i*i<=k; ++i){
        if(k%i!=0) continue;
        if(i+1>=x) bs.insert(i+1);
        if(k/i+1>=x) bs.insert(k/i+1);
    }

    for(i64 b:bs){
        if(n%b+n/b==s){
            cout << b << endl;
            return;
        }
    }

    cout << -1 << endl;
}

