  cin >> N >> S;

  // b smaller than sqrt(N)
  for (int b = 2; b < Sqt; b++) {
    long long num = N, sum = 0;
    while (num > 0) {
      sum += num % b;
      num /= b;
    }
    if (sum == S) {
      cout << b << '\n';
      return 0;
    }
  }

  // b between sqrtNn) and N 
  long long ans = 5e16;
  for (int a = 0; a < Sqt && S - a > 0; a++) { // a = N % b
    long long b = (N - a) / (S - a);
    if (b >= 2 && N / b + N % b == S && N / b / b == 0) {
      ans = min(ans, b);
    }
  }

  if (ans == 5e16 && S == N) ans = N + 1;
  if (ans == 5e16) ans = -1;
  cout << ans << '\n';
  return 0;
