        if(abs(n - s) % i == 0){
            if(check(i + 1, n) == s)
                mn = min(mn, i + 1);
            long long sum = abs(n - s) / i;
            if(check(sum + 1, n) == s)
                mn = min(mn, sum + 1);
        }
    }
    if(mn == LLONG_MAX){
        cout << "-1\n";
        return 0;
    }
