std::int64_t digit_sum(std::int64_t b, std::int64_t n)
{
	return n < b ? n : digit_sum(b, n / b) + (n%b);
}

void Main()
{
	std::int64_t n, s;
	std::cin >> n >> s;
	if (n == 1)
	{
		if (s == 1)
		{
			std::cout << 2 << std::endl;
		}
		else
		{
			std::cout << -1 << std::endl;
		}
		return;
	}
	for (std::int64_t b = 2; b*b <= n; ++b)
	{
		if (digit_sum(b, n) == s)
		{
			std::cout << b << std::endl;
			return;
		}
	}
	auto end = (std::sqrt(n)*s - n) / (std::sqrt(n) - 1);
	std::int64_t min = -1;
	for (std::int64_t x = n * (s - 1) / (n - 1); x > end; --x)
	{
		auto b = (n - x) / (s - x);
		if ((n - x) % (x - s) != 0)
		{
			continue;
		}
		if (digit_sum(b, n) == s)
		{
			if (min == -1)
			{
				min = b;
			}
			else
			{
				min = std::min(min, b);
			}
		}
	}
	if (min != -1)
	{
		std::cout << min << std::endl;
	}
	else if (n == s)
	{
		std::cout << s + 1 << std::endl;
	}
	else
	{
		std::cout << -1 << std::endl;
	}
}

