    cout << (N + 1) << '\n';
    return 0;
  }

  ll ans = 1e12;
  ll d, N2, b;
  for (ll i = 1; i <= sqrt(N - S); i++) {
    if ((N - S) % i == 0) {
      b = i + 1, d = 0, N2 = N;
      while (N2 != 0) {
        d += (N2 % b);
        N2 /= b;
      }
      if (d == S) ans = min(ans, b);

      b = (N - S) / i + 1, d = 0, N2 = N;
      while (N2 != 0) {
        d += (N2 % b);
        N2 /= b;
      }
      if (d == S) ans = min(ans, b);
    }
  }

  if (ans == 1e12) ans = -1;
  cout << ans << '\n';
  return 0;
}

