			bag += box%i;
			box /= i;
		}
		if (bag == K) {
			cout << i << endl;
			return 0;
		}
	}
	for (long long int i = sqrt(N); i >= 1; i--) {
		if (i*i == N)continue;
		if ((N + i - K) % i == 0){
			long long int box = (N + i - K) / i;
			if (box >= sqrt(N)) {
				if (N%box + N / box == K) {
					cout << box << endl;
					return 0;
				}
			}
		}
	}
	cout << "-1\n";
	return 0;
}

