ll A,S;

ll solve_small(ll base){
	ll cur=A,sum=0LL;
	while(cur){
		sum+=cur%base;
		cur/=base;
	}
	return sum;
}

ll solve_big(int L){
	ll l=L,r=A+1;
	while(r-l>1){
		ll mid=(l+r)/2;
		if(A/mid+A%mid<S)r=mid;
		else l=mid;
	}
	if(A/l+A%l==S)return l;
	if(A/r+A%r==S)return r;
	if(S==A)return A+1;
	return -1;
}

