		cout << n + 1 << endl;
		return 0;
	}

	for (ll i = 2; i * i <= n; i++) {
		ll temp = 0;
		ll num = n;
		while (num) {
			temp += num % i;
			num /= i;
		}
		if (temp == s) {
			cout << i << '\n';
			return 0;
		}
	}

	ll ans = INF;
	for (ll i = 1; i * i < n; i++) {
		if ((n - s) % i != 0)continue;
		ll b = (n - s) / i + 1;
		ll temp = 0;
		ll num = n;
		while (num) {
			temp += num % b;
			num /= b;
		}
		if (temp == s) chmin(ans, b);
	}
	if (ans == INF)cout << -1 << endl;
	else cout << ans << endl;


	return 0;
}

