	LL n = in, s = in;

	if (n == s) {
		out.exit(n + 1);
	}

	function<LL(LL, LL)> f = [&](LL B, LL N) {
		return N < B ? N : f(B, N / B) + N % B;
	};

	LL sqrt_n = sqrt(n) + 1;
	for (LL b = 2; b < sqrt_n; ++b) {
		if (f(b, n) == s) {
			out.exit(b);
		}
	}

	for (LL x = 1; x < sqrt_n; ++x) {
		if ((n - s) % x != 0)continue;
		LL b = (n - s) / x + 1;
		if (f(b, n) == s) {
			out.exit(b);
		}
	}

	out(-1);
}

