lint fanc(lint b, lint n){
    lint res = 0;
    while(n > 0){
        res += n % b;
        n /= b;
    }
    return res;
}

lint solve(void){
    lint n, s;
    cin >> n >> s;
    lint res = LLINF;
    for(lint b = 2 ; b * b <= n ; ++b){
        if(fanc(b, n) == s){
            res = min(res, b);
        }
    }
    for(lint q = 1 ; q * q <= n ; ++q){
        if((n - s) % q != 0){
            continue;
        }
        lint b = (n - s) / q + 1LL;
        if(b < 2LL){
            continue;
        }
        if(fanc(b, n) == s){
            res = min(res, b);
        }
    }
    if(n == s){
        res = min(res, n + 1);
    }
    if(res < LLINF){
        return res;
    }
    return -1;
}

