bool check(long long int n, long long int s, const long long int &b){
  s -= n;
  s /= b-1;
  while(n > 0){
    n /= b;
    s += n;
    if(s > 0) return false;
  }
  return s == 0;
}

int main(){
  long long int n, s;
  scanf("%lld %lld", &n, &s);
  if(s > n){
    printf("%d\n",-1);
    return 0;
  }else if(s == n){
    printf("%lld\n",n+1);
    return 0;
  }
  long long int d = n - s, ans = -1, m = sqrt(d);
  for(long long int i = 1; i <= m; ++i){
    if(d != d/i*i) continue;
    if(check(n,s,i+1)){
      printf("%lld\n",i+1);
      return 0;
    }
    if(check(n,s,d/i+1)){
      ans = d/i+1;
    }
  }
  printf("%lld\n",ans);
  return 0;
}

#include <iostream>
