int f(ll b,ll n){
  if(n < b ) return n;
  else return (n%b) + f(b,n/b);
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll n, b, s;
  cin >> n >> s; 


  rep(i, sqrt(n)){
    if(i == 0 || i==1) continue;
    b =  i;
    if(f(b, n) == s){
      cout << b << endl;
      return 0;
    }
  }

  vector<ll> posq1;
  // q p;
  // q + p = s;
  // q * b + p = n
  // b = (n-s) / (q-1)
  // よって、bは(n-s) の約数

  // q==0の可能性もあるのでそれを先に例外処理する。
  // その場合p(s) = n , b > p
  if(s == n) {
    cout << s + 1 << endl;
    return 0;
  }


  ll ans = n+n;
  // q == 1の可能性もある
  // その場合 p = s-1
  // b = (n-p) / q = (n-s+1)
  // その場合、b > pが必須
  if(((n-s+1) > (s-1))&& ((s-1) >= 0)){
    ans = n-s+1;
  }


  rep(i, sqrt(n-s)+1){
    if(i == 0 || i == 1) continue;
    if((n-s) % i == 0){
      posq1.pb(i);
      posq1.pb((n-s)/i);
    }
  }



  rep(i, posq1.size()){
    b = (n-s) / posq1[i];
    if(b < 2) continue;
    if(f(b, n) == s)
      ans = min(ans, b);
  }

  if(ans != (n+n)) cout << ans << endl;
  else cout << "-1" << endl;


  //cout << fixed << setprecision(16) << ans << endl;
  return 0;
}

