        if (ss == s) {
            return b;
        }
    }
    if (n >= s) {
        for (int q = b; q >= 1; -- q) {
            LL xb = (n - s) / q + 1;
            if (xb >= 2 && n / xb + n % xb == s) {
                return xb;
            }
        }
    }
    if (n == s) {
        return n + 1;
    }
    return -1;
}

