    cout << -1 << '\n';
    return 0;
  }
  if (N == S) {
    cout << (N + 1) << '\n';
    return 0;
  }

  ll ans = 1e12;
  ll d, N2, b;
  for (ll i = 2; i <= sqrt(N - S); i++) {
    if ((N - S) % (i - 1) == 0) {
      b = i, d = 0, N2 = N;
      while (N2 != 0) {
        d += (N2 % b);
        N2 /= b;
      }
      if (d == S) ans = min(ans, b);

      b = (N - S) / (i - 1) + 1, d = 0, N2 = N;
      while (N2 != 0) {
        d += (N2 % b);
        N2 /= b;
      }
      if (d == S) ans = min(ans, b);
    }
  }
  if (ans == 1e12) ans = -1;
  cout << ans << '\n';
  return 0;
}

