ll N, S;

bool check(ll b) {
    ll digsum = 0LL;
    ll n = N;
    while (n > 0) {
        digsum += n%b;
        n /= b;
    }
    return digsum == S;
}

void solve(void){
    cin >> N >> S;
    if (N == S) {
        cout << N+1LL << endl;
        return;
    }
    if (S == 1) {
        cout << N << endl;
        return;
    }
    for (ll i = 2LL; i*i <= N; i++) {
        if (check(i)) {
            cout << i << endl;
            return;
        }
    }
    for (ll p = 1LL; p*p <= N; p++) {
        if ((N-S)%p) continue;
        ll b = (N-S)/p - 1;
