    for (ll i = 2; i <= sqrt(n); ++i) {
        ll d = digsum(n, i);
        if (d == s)
            chmin(ret, i);
    }

    for (ll i = 1; i <= sqrt(n); ++i) {
        if ((n - (s - i)) % i == 0) {
            ll b = (n - (s - i)) / i;
            if (digsum(n, b) == s)
                chmin(ret, b);
        }
    }
    cout << ret << "\n";
    return 0;
}

