ll N;
ll S;
const ll INF = 1LL << 60;


ll solve() {
    for(ll b = 2; b * b <= N; b++){
        // 普通に計算
        ll n = N;
        ll s = 0;
        while(n != 0){
            s += n % b;
            n /= b;
        }
        if(s == S){
            return b;
        }
    }

    ll opt_b = INF;
    // sqrt(N) より大きい b について計算
    // N / b < sqrt(N) となるので、N / bを決め打ちで計算する
    for(ll n_per_b = 1; n_per_b * n_per_b < N; n_per_b++){
        if(N + n_per_b - S > 0 && (N + n_per_b - S) % n_per_b == 0){
            // if(n_per_b == 1){
            //     cout << "ok" << endl;
            // }
            ll cand_b = (N + n_per_b - S) / n_per_b;
            if(cand_b >= -n_per_b + S){
                // if(cand_b == 215177580){
                //     cout << n_per_b << endl;
                // }
                // if(cand_b == 319){
                //     cout << n_per_b << endl;
                // }
                if(N%cand_b + N/cand_b == S)
                    opt_b = min(opt_b, cand_b);
            }
        }
    }

    if(N == S) opt_b = min(opt_b, N + 1);

    if(opt_b == INF)
        return -1;
    else
        return opt_b;
}

int main(){

    cin >> N >> S;
    cout << solve() << endl;

}

