         long b = (n - y) / x;
         if( b >= 2 and 0 <= x and x < b and 0 <= y and y < b and x + y == s ) {
            res = std::min(res, b);
         }
      }
      if( res == inf ) res = -1;
      printf("%ld\n", res);
   }
};

