const ll B = 1e6;
const ll INF = 1e12;

ll sumofDigit(ll n , ll b){
	ll sum = 0;
	while(n){
		sum += n%b;
		n /= b;
	}
	return sum;
}

int main(){
	fio; cout<<fixed<<setprecision(25);	
	ll n , s;
	cin >> n >> s;

	ll ans = -1;
	for(ll b = 2;b < B ; ++b){
		if(sumofDigit(n , b) == s){
			ans = b;
			break;
		}
	}
	if(ans == -1){	
		ll act = INF;
		for(ll b = 1 ; b < B ; ++b){
			// n/d is equal to b
			ll lo = 1 , high = n , ans = high;
			while(lo <= high){
				ll mid = (lo+high)/2;
				if(n/mid >= b){
					ans = mid;
					lo = mid+1;
				}
				else{
					high = mid-1;
				}
			}
			lo =1 , high = n ;
			ll ans1 = 1;
			while(lo <= high){
				ll mid = (lo+high)/2;
				if(n/mid <= b){
					ans1 = mid;
					high = mid-1;
				}
				else{
					lo = mid+1;
				}
			}
			if(n/ans != b || n/ans1 != b) continue;
			ll wnt = s-b;
			if(wnt >= n%ans && wnt <= n%ans1){
				// trace(b , ans , ans1);
				act = min(act , (n-wnt)/b);
			}
		}	
		if(act != INF){
			cout << act << endl;
		}
		else{
			cout << -1 << endl;
		}
	}
	else{
		cout << ans << endl;
	}







	return 0;
}

