ull calculateF(ull b, ull n){
    if(n<b) return n;
    return calculateF(b, n/b) + (n%b);
}

ll digitSum(ull n, ull s){
    if(n == s) return n;
    if(n < s) return -1;
    ull sqn = sqrt(n);
    for (ull b=2;b<sqn;b++){
        if(calculateF(b, n) == s) return b;
    }
    for (int p=sqn;p>0;p--){
        if((n-s)%p == 0 && calculateF((n-s)/p + 1, n)==s) return (n-s)/p + 1;
    }
    return -1;
}

