int32_t main() {
    ios::sync_with_stdio(0);
    cin.tie(0);
    ll n, s;
    cin >> n >> s;
    auto check = [&] (int b) {
        ll cur = 0;
        ll x = n;
        while (x) {
            cur += x % b;
            x /= b;
        }
        return cur;
    };
    ll val = 1;
    for (ll b = 2; b * b <= n; b++) { 
        if (check(b) == s) {
            cout << b << '\n';
            return 0;
        }
        val = b;
    }
    ll f = n - s;
    if (f < 0) {
        cout << -1 << '\n';
        return 0;
    }
    ll ans = 1e18;
    if (f == 0) {
        cout << n + 1 << '\n';
        return 0;
    }
    auto relax = [&] (ll x) {
        if (x <= val) {
            return;
        }
        ll p = f / x;
        ll b = x + 1;
        ll q = s - p;
        if (p >= b || q >= b || p < 0 || q < 0) {
            return;
        }
        if (p * b + q != s) {
            return;
        }
        ans = min(ans, b);
    };
    for (ll i = 1; i * i <= f; i++) {
        if (f % i == 0) {
            relax(i);
            relax(f / i);
        }
    }
    if (ans == 1e18) {
        cout << -1 << '\n';
        return 0;
    }
    cout << ans << '\n';
    return 0;
}

