inline bool check(LL n,LL b) {
    LL sum=0;
    while (n>=b) {
        sum+=(n%b);
        n/=b;
    }
    if (n<b) sum+=n;
    return sum==s;
}

int main() {
    scanf("%lld%lld",&n,&s);
    if (s>n) { puts("-1");return 0; }
    if (s==n) { printf("%lld\n", n+1);return 0; }
    LL t=sqrt(n)+1;
    for (LL i=2;i<=t;i++) {
        if (check(n,i)) {
            printf("%lld\n", i);
            return 0;
        }
    }
    LL ans=1e12;
    for (LL p=1;p*p<=n-s;p++) {
        if ((n-s)%p==0) {
            LL b=(n-s)/p+1;
            if (check(n,b)) ans=min(ans,b);
        }
    }
    printf("%lld\n",ans==1e12?-1:ans);
    return 0;
}

