template<typename T>
vector<T> divisor(T n){
	vector<T> div;
	div.push_back(1);
	if(n == 1)return div;
	div.push_back(n);
	for(T i=2; i*i<=n; ++i){
		if(n%i == 0){
			div.push_back(i);
			if(i*i != n){
				div.push_back(n/i);
			}
		}
	}
	sort(div.begin(), div.end());
	return div;
}
