ll f(ll b,ll n){
	if(n<b)return n;
	return f(b,(n/b)) + (n%b);
}

void solve() {
	ll N,S;
	cin>>N>>S;
	if(N==S){
		p(N+1);return;
	}
	if(N<S){
		p(-1);return;
	}

	ll sqrtN=sqrt(N)+1;
	for(ll i=2;i<=sqrtN;i++){
		ll d=f(i,N);
		if(d==S){
			p(i);return;
		}
	}

	vector<ll> v=divisor(N-S);
	for(ll x:v){
		ll b=x+1;
		ll d=f(b,N);
		if(d==S){
			p(b);return;
		}
	}

	p(-1);
}

