using namespace std;

typedef long long ll;

ll f(ll b, ll n) {
    if (n < b) return n;
    return f(b, n / b) + n % b;
}

ll solve(ll n, ll s) {
    if (n < s) return -1;
    if (n == s) return n + 1;
    for (ll b = 2; b * b <= n; b++) {
        if (f(b, n) == s) return b;
    }
    for (ll p = 1; p * p <= n; p++) {
        ll b = (n - s) / p + 1;
        if (f(b, n) == s) return b;
    }
    return -1;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll n, s;
    cin >> n >> s;
    cout << solve(n, s) << "\n";
    return 0;
}

