int f(int n,int k){
  int ret = 0;
  int now = n,ke = k;
  while(now!=0){
    ret += now%ke;
    now /= ke;
  }
  return ret;
}

signed main() {
  init();

  int n,K;cin >> n >> K;
  if(K > n) {cout << -1 << endl;return 0;}

  //repreq(i,n,2){cerr << i << " : " << f(n,i) << endl;}

  repeq(i,2,100005){
    if(f(n,i)==K) {cout << i << endl;return 0;}
  }

  if(n <= 100000){
    cout << -1 << endl;
    return 0;
  }

  Vi b;
  repeq(i,1,n){
    b.pb(n/i);
    if(n/i < 5000) break;
  }
  cout << b << endl;

  int ans = INF;

  rep(i,0,b.size()){
    int L,R;
    L = f(n,b[i]);
    R = L+(b[i]-b[i+1]-1)*(i+1);
    //cerr << L <<' '<< R << endl;
    if(K > R || K < L || K%(i+1)!=L%(i+1)) continue;
    int sa = K-L;
    sa /= (i+1);
    ans = min(ans,b[i]-sa);
    if(b[i] < 90000) break;
  }

  if(ans == INF) ans = -1;
  cout << ans << endl;
  return 0;
}

