long long n, s;

long long sum(long long n, long long b) {
    long long res = 0;
    while (n > 0) {
        res += (n % b);
        n /= b;
    }
    return res;
}


vector<long long> divisor(long long n) {
    vector<long long> res;
    for (long long i = 1LL; i*i <= n; ++i) {
        if (n%i == 0LL) {
            res.push_back(i);
            long long temp = n/i;
            if (i != temp) res.push_back(temp);
        }
    }
    sort(res.begin(), res.end());
    return res;
}


long long solve() {
    if (n == s) return n+1;
    if (n < s) return -1;

    long long b = 0;
    for (b = 2; b <= 400000; ++b) {
        long long ts = sum(n, b);
        if (ts == s) return b;
    }

    vector<long long> div = divisor(n-s);
    sort(div.begin(), div.end());
    for (int i = 0; i < div.size(); ++i) {
        b = div[i] + 1;
        long long ts = sum(n, b);
        if (ts == s) return b;
    }

    return -1;
}

