int64 DigitSum(int64 x, int64 b) {
  int64 s = 0;
  while (x > 0) {
    s += x % b;
    x /= b;
  }
  return s;
}

int64 Solve() {
  int64 n;
  int64 t;
  cin >> n >> t;

  if (n < t) return -1;

  // In the following, t <= n.

  // 1 digit
  if (n == t) {
    return n + 1;
  }

  // >=3 digits
  int64 u = -1;
  for (int64 b = 2; b <= n; b++) {
    if (n < b * b) {
      u = b;
      break;
    }
    int64 s = DigitSum(n, b);
    // cout << "b : " << b << " s: " << s << endl;
    if (s == t) return b;
  }

  // 2 digits
  for (int64 x = u; x >= 1; x--) {
    int64 b = n / x;
    int64 y = n % x;
    if (b <= x) continue;
    if (x + y == t) return b;
  }
  return -1;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  cout << Solve() << endl;
}

