void get_prime(ll x){
	for(ll i=2LL;i*i<=x;i++){
		if(x%i)continue;
		prime.push_back(mk(i,0));
		while(x%i==0){
			prime[prime.size()-1].se++;
			x/=i;
		}
	} 
	if(x>1)prime.push_back(mk(x,1));
} 

void go(ll cur,int pos){
	if(pos==prime.size()){
		p.push_back(cur);
		return;
	}
	go(cur,pos+1);
	rep(i,prime[pos].se){
		cur*=prime[pos].fi;
		go(cur,pos+1);
	}
}

ll solve_big(ll lim){
	if(A==S)return A+1;
	ll cur=A-S;
	if(cur<0)return -1;
	get_prime(cur);
	go(1LL,0);
	sort(p.begin(),p.end());
	rep(i,p.size()){
		ll now=p[i]+1LL;
		if(now<lim)continue;
		if(A/now+A%now==S)return now; 
	} 
	return -1;
}

