using namespace std;

ll f(ll b, ll n) {
  if (n < b) {
    return n;
  } else {
    return n % b + f(b, n / b);
  }
}

int main() {
  ll n, s;
  scan(n, s);
  if (s > n) {
    print(-1);
    return 0;
  }
  if (s == n) {
    print(n+1);
    return 0;
  }
  int m = sqrt(n);
  FOR (i, 2, m+2) {
    if (f(i, n) == s) {
      print(i);
      return 0;
    }
  }
  // n - s == n / b * (b-1)
  ll ans = n+1;
  FOR (i, 1, m+1) {
    ll j = s - i;
    if (j < 0) { continue; }
    if ((n - j) % i != 0) { continue; }
    ll b = (n - j) / i;
    if (i >= b || j >= b) { continue; }
    ans = min(ans, b);
  }
  if (ans == n+1) {
    ans = -1;
  }
  print(ans);

  return 0;
}

