lint f(lint b,lint n){
	if(n<b)return n;
	return f(b,n/b) + n%b;
}

int main(){
	ios::sync_with_stdio(false);

	lint n,s;
	cin >> n >> s;

	if(s >= n){
		cout << -1 << endl;
		return 0;
	}

	lint i;
	for(i=2;i*i<=n;i++){
		if(f(i,n)==s){
			cout << i << endl;
			return 0;
		}
	}

	if(i*i==n)i--;
	for(i=min(i,s);i>=1;i--){
		//n = b*i + s-i
		lint b = (n-s+i)/i;
		if((n-s+i)%i==0 && b > s-i){
			cout << b << endl;
			return 0;
		}
	}
	cout << -1 << endl;
	return 0;	
}

