const ll INF = 8e18;
const int B = 5e6;

ll n, s, ans = INF;

inline ll f(ll b, ll x) {
    if (x < b) {
        return x;
    }
    return x % b + f(b, x / b);
}

void calc() {
    for (int b = 2; b < B; ++b) {
        ll fb = f(b, n);
        if (fb == s) {
            ans = b;
            return;
        }
    }

    if (n == s) {
        ans = n + 1;
        return;
    }

    if (s > n) {
        return;
    }

    ll ns = n - s;
    for (ll x = 1; x * x <= ns; ++x) {
        if (ns % x == 0) {
            ll b1 = ns / x;
            ll y = s - x;

            if (y >= 0 && y <= b1) {
                ans = min(ans, b1 + 1);
            }
        }
    }
}

void solve() {
    cin >> n >> s;
    calc();
    if (ans == INF) {
        cout << "-1\n";
    } else {
        cout << ans << "\n";
    }
}

