ll solve(ll n, ll b) {
  ll r = 0;
  while(n) {
    r += n%b;
    n /= b;
  }
  return r;
}

int main() {
  ll n, s;
  scanf("%lld %lld", &n, &s);
  for(int b = 2; b <= 1000000; b++) {
    if(solve(n, b) == s) {
      printf("%d\n", b);
      return 0;
    }
  }
  // a * base + b
  // b = n % a
  ll ret = -1;
  for(ll a = 1; a <= 1000000 && a <= s; a++) {
    ll b = s-a;
    ll base = (n-b)/a;
    if(base == 1) continue;
    if(b >= base) continue;
    if(a >= base) continue;
    if(ret == -1) {
      ret = base;
    }
    else {
      ret = min(ret, base);
    }
  }
  printf("%lld\n", ret);
}

