void part_digit(long long b, long long n, vector<long long> &v){
  if (n < b) {
    v.push_back(n);
    return;
  } else {
    v.push_back(n % b);
    part_digit(b, n/b, v);
    return;
  }
  return;
}
long long sum_digit(long long b, long long n, long long tot){
  if (n < b) {
    tot += n;
    return(tot);
  } else {
    tot += n%b;
    return(sum_digit(b, n/b, tot));
  }
  return(tot);
}

