	long long ans = 1LL << 60;
	for( int d = 2; (long long) d * d <= n; d++ ) {
		long long k = n;

		long long sum = 0;
		while( k > 0 ) {
			sum += k % d;
			k /= d;
		}

		if( sum == s ) {
			ans = min(ans, d);
		}

		long long r = n % d;
		long long b = n / d;

		if( (d < b) && (d + r == s) ) {
			ans = min(ans, b);
		} 
	}

	if( s == 1 ) {
		ans = min(ans, n);
	} else if( s == n ) {
		ans = min(ans, n + 1);
	}

	if( ans < (1LL << 60) ) {
		printf("%lld\n", ans);
	} else {
		printf("-1\n");
	}

	return 0;
}

