    if (n < s) Ptest(-1);
    if (n == s + 1 && s > 2) Ptest(-1);
    if (n == s + 1 && s == 2) Ptest(2);
    if (n == s + 1 && s == 1) Ptest(2);
    if (s == 1) ans = min(ans, n);
    if (s == 2) ans = min(ans, n - 1);
