        if (cal(i, n) == s) Ptest(i);
    }
    if (cal(n - s, n) == s){
        ans = min(ans, n - s);
    }
    ForE(i, 2, sqrt(n - s)){
        if ((n - s) % i == 0){
            if (i > sqrt(n) && cal(i, n) == s){
                ans = min(ans, i);
            }
            if ((n - s) / i > sqrt(n) && cal((n - s) / i, n) == s){
                ans = min(ans, (n - s) / i);
            }
        }
    }
    cout << (ans == inf ? -1 : ans);
}

