ll f(ll b, ll n){
  if(b<2) return -1;
  if(n<b) return n;
  else return f(b, n/b) + n%b;
}

ll binary_search(ll b_start, ll b_end, ll n, ll s){
  if(b_start<2) b_start=2;
  if(b_end<2) return -1;
  if(b_start>b_end) return -1;
  if(b_start==b_end) return b_start;
  if(b_end-b_start==1){
    if(f(b_start, n)==s) return b_start;
    else return b_end;
  }
  ll b_middle = (b_start+b_end)/2;
  if(f(b_middle, n)>=s) return binary_search(b_middle, b_end, n, s);
  else return binary_search(b_start, b_middle, n, s);
}

int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  ll n;
  ll s;
  cin >> n >> s;

  ll ans = n+10;

  ll n_middle = (ll)sqrt((long double)n)+1;

  if(f(n+1, n)==s) ans = n+1;
  for(ll k_start=2; k_start<n_middle+2; ++k_start){
    ll b_start = (n/k_start);
    ll b_end = (n/(k_start-1));
    if(f(b_start, n)==s && b_start>1) ans = min(ans, b_start);
    if(b_start==b_end) continue;
    if(f(b_end, n)==s && b_end>1) ans = min(ans, b_end);
    ll cand = binary_search(b_start, b_end, n, s);
    if(f(cand, n)==s && cand>1) ans = min(ans, cand);
  }
  for(ll b=2; b<=max(max(n/n_middle, n_middle), (ll)2); ++b){
    if(f(b, n)==s){
      ans = min(ans, b);
      break;
    }
  }

  if(ans==n+10) ans = -1;
  cout << ans << "\n";

  return 0;
}

