signed main() {
    //my-code
    ll n; cin >> n;
    ll s; cin >> s;

    if (s > n) {
        cout << -1 << endl;
        exit(0);
    }

    if (s==n) {
        cout << n + 1 << endl;
        exit(0);
    }

    ll rn = (int) sqrt(n);

    // small cases
    REPS(i, 2, rn + 1){
        if (f(i, n) == s) {
            cout << i << endl;
            exit(0);
        }
    }

    // 2 digits
    REPS(i, 1, rn){ // 2nd digit
        if ((n-s)%i == 0) {
            ll b = (n - s)/i + 1;
            if (b > 1 && b > rn && f(b, n) == s) {
                cout << b << endl;
                exit(0);
            }
        }
    }

    // not found
    cout << -1 << endl;

    return 0;
}

