    ll ans = 1ll << 60ll;
    for (ll i = 2; i * i <= n; i++) {
        if (dig(i, n) == s) {
            ans = min(ans, i);
        }
    }

    for (ll i = 1; i * i <= n; i++) {
        ll j = s - i;

        if (j <= 0) break;

        ll b = (n - j) / i;

