long long n , s , n_s , t , rem , divs[53];
int tmp , cnt;

bool judge(int b) {//判断b进制下的各位和是否等于s
    rem = n;
    t = 0;
    while(rem > 0) {
        t += rem % b;
        rem /= b;
    }
    return t == s;
}

void solve() {
    cnt = 0;
    tmp = sqrt(0.0 + n) + 1;
    n_s = n - s;
    for(int i = 2 ; i <= tmp ;++i) {//枚举到sqrt(n)
        if(judge(i)) {
            printf("%d\n" , i);
            return ;
        }
        if(n_s % i == 0) {//找到所有的大于sqrt(b)且是n-s的因子的数
            divs[cnt++] = n_s / i;
        }
    }
    sort(divs , divs + cnt);
    for(int i = 0 ; i < cnt ; ++i) {
        if(judge(divs[i])) {
            printf("%lld\n" , divs[i]);
            return ;
        }
    }
    printf("%lld\n" , s == 1 ? n : -1);
}

int main() {
    while(2 == scanf("%lld%lld", &n, &s)) {
        solve();
    }
    return 0;
}

