		for (ll i = 2; i <= n; i++) {
			if (f(i, n) == s) {
				cout << i << endl;
				return 0;
			}
		}
		cout << -1 << endl;
		return 0;
	}


	// n > s
	ll pos = 0;
	for (ll i = 2; i*i <= 4000*n; i++) {
		if (f(i, n) == s) {
			cout << i << endl;
			return 0;
		}
		if(i*i<=n)pos = i;
	}


	for (ll i = pos; i >= 2; i--) {
		ll st = f(pos+1, n), d = i-1;
		if (s <= st && (st - s) % d == 0 && s >= d) {
			cout << pos + (st - s + d - 1) / d + 1 << endl;
