	ll tmp;
	vector<ll> candidates;
	for (ll d = 2; d*d <= n; ++d) {
		tmp = n;
		ll sum = 0;
		while (tmp > 0) {
			sum += tmp % d;
			tmp /= d;
		}
		if (sum == s) {
			candidates.push_back(d);
		}
