ll sum(ll n, ll b) {
    ll ans = 0;
    while (n > 0) {
        ans += n % b;
        n /= b;
    }
    return ans;
}

void solve(ll n, ll s) {
    ll b = 1e18;
    if (n == s) {
        b = n + 1;
    }

    for (int i = 2; i <= 1000000; i++) {
        if (sum(n, i) == s) {
            b = min(b, 1ll * i);
        }
    }

    for (int i = 1; i <= 1000000; i++) {
        if ((i + n - s) % i == 0) {
            if( (i + n - s) / i > 1) {
                if (sum(n, (i + n - s) / i) == s) {
                    b = min(b, (i + n - s) / i);
                }
            }
        }
    }


    if (b == 1e18) {
        cout << -1 << endl;
    } else {
        cout << b << endl;
    }
}


