int run(std::vector<int>const& large, std::vector<int>const& rest, int target, int index = 0)
{
	if (target < 0)
		return 0;
	if (target == 0)
		return 1;
	if (rest[large.size() - index] == target)
	{
		return 1;
	}
	else if (rest[large.size() - index] < target)
	{
		return 0;
	}
	return run(large, rest, target, index + 1) + run(large, rest, target - large[index], index + 1);
}
int check(std::vector<int>const& small, std::vector<int> const& large, std::vector<int>const& large_seq, int index = 0, int sum = 0)
{
	if (index == small.size())
		return run(large, large_seq, sum);
	return check(small, large, large_seq, index + 1, sum) + check(small, large, large_seq, index + 1, sum + large[index]);
}
