int64 DigitSum(int64 x, int64 b) {
  int64 s = 0;
  while (x > 0) {
    s += x % b;
    x /= b;
  }
  return s;
}

// Returns a tuple of (l, u) s.t.
// - l is the minimum value s.t. is_upper_fn(l) is false.
// - r is the minimum value s.t. is_upper_fn(r) is true.
//
// Required:
// - is_upper_fn is a function s.t.
//   - There exists a constant c s.t. is_upper_fn(x) is true for x >= c and
//     is_upper_fn(x) is false for x < c.
// - is_upper_fn(min_value) is false.
// - is_upper_fn(max_value) is true.
//
// Verified: ABC144E
tuple<int64, int64> BinarySearch(function<bool(int64)> is_upper_fn, int64 l, int64 u) {
  while (u - l >= 2) {
    int64 m = (l + u) / 2;
    if (is_upper_fn(m)) u = m; else l = m;
  }
  return make_tuple(l, u);
}

int64 Solve() {
  int64 n;
  int64 t;
  cin >> n >> t;

  if (n < t) return -1;

  // In the following, t <= n.

  // 1 digit
  if (n == t) {
    return n + 1;
  }

  // >=3 digits
  int64 l = -1;
  for (int64 b = 2; b <= n; b++) {
    if (n < b * b) {
      l = b + 1;
      break;
    }
    int64 s = DigitSum(n, b);
    if (s == t) return b;
  }

  int64 u = n;
  auto is_upper_fn = [&](int64 k) -> bool {
    int64 s = DigitSum(n, k);
    return s <= t;
  };

  // is_upper_fn(n) is always true.

  if (is_upper_fn(l)) {
    if (DigitSum(n, l) == t) return l;
    else return -1;
  }

  tie(l, u) = BinarySearch(is_upper_fn, l, u);
  if (DigitSum(n, u) == t) {
    return u;
  } else {
    return -1;
  }
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  cout << Solve() << endl;
}

