ll doubles(ll start, const ll n, const ll s)
{
    start = n/start;
    assert(start < n);
    for(ll i = start; i>1; i--)
    {
        ll r = n/i;
        ll l = n/(i-1);
        ll target = s - i;
        while(r-l>1)
        {
            ll mid = (l+r)/2;
            if(n%mid>=target) r = mid;
            else l = mid;
        }
        if(n%l==target) return l;
        if(n%r==target) return r;
    }
    if(s==1)return n;
    if(n==s)return n+1;
    return -1;
}

