class solver{
    istream& is;
    ostream& os;

public:

    ll f(ll b, ll n){
        if(b < 0) return -1;
        if(n < b) return n;
        return f(b, n/b) + n % b;
    }

    solver(istream& I, ostream& O) :is(I), os(O) {}
    void run(){
        ll n, s;
        is >> n >> s;
        if(!is) return;
        if(n == s) {
            os << n + 1 << endl;
            return;
        }

        for (int b = 2; b < sqrt(n)+2; ++b) {
            if(f(b, n) == s){
                os << b << endl;
                return;
            }
        } // end b
        ll ns = n - s;
        for (int p = sqrt(n)+1; p >= 1; --p) {
            if(ns % p == 0) {
                ll b =  ns / p + 1;
                if(f(b, n) == s){
                    os << b << endl;
                    return;
                }
            }
        } // end p
        os << -1 << endl;

    }
};

