    template<class T> ostream& operator<<(ostream& os, const vector<T>& vs) {
        if (vs.empty()) return os << "[]";
        os << "[" << vs[0];
        for (int i = 1; i < vs.size(); i++) os << " " << vs[i];
        return os << "]";
    }
    template<class T> istream& operator>>(istream& is, vector<T>& vs) {
        for (auto it = vs.begin(); it != vs.end(); it++) is >> *it;
        return is;
    }

    ll N, S;
    void input() {
        cin >> N >> S;
    }

    bool check(ll b) {
        ll sum = 0;
        ll n = N;
        while (n > 0) {
            sum += n % b;
            n /= b;
        }
        return sum == S;
    }

    void solve() {

        if (N < S) {
            cout << -1 << endl;
            return;
        }

        if (N == S) {
            cout << N + 1 << endl;
            return;
        }

        if (S == 1) {
            cout << N << endl;
            return;
        }

        ll Z = N - S;
        for (ll x = 1; x * x <= N; x++) {
            if (Z % x != 0) continue;
            if (check(x + 1)) {
                cout << x + 1 << endl;
                return;
            }
        }
        if (check(Z + 1)) {
            cout << Z + 1 << endl;
            return;
        }
        cout << -1 << endl;

    }
}

