long long function(long long b, long long n) {
	long long ans = 0;
	while (n > 0) {
		ans += n % b;
		n /= b;
	}
	return ans;
}

int main() {
	long long n, s;
	cin >> n >> s;
	if (n == s) {
		cout << n + 1 << endl;
		return 0;
	}
	long long root_n = 0;
	for (long long b = 2; b*b <= n; b++) {
		root_n = b;
		if (function(b, n) == s) {
			cout << b << endl;
			return 0;
		}
	}
	if (n<=3) {
		for (int b = 2; b <= 4; b++) {
			if (function(b, n) == s) {
				cout << b << endl;
				return 0;
			}
		}
		cout << -1 << endl;
		return 0;
	}
	for (long long x = (n - s) / (root_n - 1) -1 +((n-s)%(root_n-1)==0) ; x >= 1; x--) {
		if ((n - s) % x != 0) {
			continue;
		}
		long long b = (n - s) / x + 1;
		if (b > root_n && b > x && s - x < b && 0 <= s-x) {
			cout << b << endl;
			return 0;
		}
	}
	cout << -1 << endl;
}

