void Solve() {
  li(n,s);
  ll a,b,r=INF,c,d;
  if(n<s){
    cout << -1;
    return;
  }
  if(n==s){
    cout << n+1;
    return;
  }
  if(s==1){
    cout << n;
    return;
  }
  if(isP(n-s)){
    cout << -1;
    return;
  }
  FOR(i,2,(ll)sqrt(n-s)){
    if ((n-s)%i==0) {
      a=i+1;
      b=(n-s)/i+1;
      c=0;
      d=n;
      while(d){
        c+=d%a;
        d=(d-d%a)/a;
      }
      if(c==s){
        r=min(r,a);
      }
      c=0;
      d=n;
      while(d){
        c+=d%b;
        d=(d-d%b)/b;
      }
      if(c==s){
        r=min(r,b);
      }
    }
  }
  if (r==INF) {
    cout << -1;
  } else {
    cout << r;
  }
  return;
}

