ll solve(ll n, ll s) {
  if (n < s) {
    return -1;
  }
  if (n == s) {
    return n + 1;
  }

  for (ll b = 2; b * b <= n; b++) {
    if (f(b, n) == s) {
      return b;
    }
  }

  ll ans = LLONG_MAX;
  for (ll p = 1; p * p < n; p++) {
    ll b = (n - s) / p + 1;
    if (b <= 1) {
      continue;
    }
    if (f(b, n) == s) {
      ans = min(ans, b);
    }
  }
  if (ans != LLONG_MAX) {
    return ans;
  }
  return -1;
}

