    LL s;
    cin >> s;

    function<LL(LL,LL)> func = [&](LL a,LL b)->LL{
        if(a < b){
            return a;
        }else{
            return a%b + func(a/b,b);
        }
    };

    LL i = 2;

    if(n == s){
        printf("%lli\n",n+1);
        return 0;
    }

    while(true){
        if(i*i > n){
            break;
        }else{
            if(func(n,i) == s){
                printf("%lli\n",i);
                return 0;
            }
        }
        i++;
    }

    while(i <= n){
        LL m = n/i;
        LL tmp = func(n,i);
        LL dist = tmp/m;
        LL min = func(n,dist+i);
        LL tdist = dist;
        LL t = func(n,dist+i+1);
        if(t < min){
            min = t;
            dist++;
        }
        if(tdist+i-1 >= i){
            t = func(n,tdist+i-1);
            if(t < min){
                min = t;
                dist = tdist - 1;
            }
        }

        LL ret = bin_search(i,i+dist,n,s);

        if(func(n,ret) == s){
            printf("%lli\n",ret);
            return 0;
        }
        i += dist+1;
    }

    printf("-1\n");

    return 0;
}

