		}
	}
	n -= s;
	ll ans = 0x3f3f3f3f3f3f3f3f;
	for(ll i = 1; i * i <= n; ++i) {
		if(!(n % i)) {
			ll b = n / i + 1;
			ll a0 = s - i;
			ll a1 = i;
			if(b >= 2 && a0 >= 0 && a0 <= b && a1 < b) ans = min(ans, b);
		}
	}
