int main() {
    cin >> N >> S;

    //for (int b = 2; b < 5000; ++b) {
    //    cout << b << " ";
    //    write(f(b, N));
    //}

    ll s_max = f(N / 2 + 1, N);
    if (S > s_max) {
        write(-1);
        return 0;
    }
    ll b_sqrt = sqrt(N);
    for (ll b = 2; b < b_sqrt; ++b) {
        if (f(b, N) == S) {
            write(b);
            return 0;
        }
    }
    for (ll i = N / b_sqrt + 5; i > 1; --i) {
        ll b1 = N / i;
        ll s1 = f(b1, N);
        if (s1 < S) continue;
        else if (s1 == S) {
