		printf("%lld\n", n);
		return 0;
	}

	const i64 sqrtN = [n] {
		i64 ok = 0, ng = 1e6;
		while(ng - ok > 1) {
			i64 mid = (ok + ng) >> 1;

			if(mid * mid <= n) ok = mid;
			else ng = mid;
		}
		return ok + 1;
	}();

	auto f = [](auto&& f, i64 b, i64 n) {
