ll calc(ll b,ll n){
  ll ret=0;
  while(n>=b){
    ret += n%b;
    n/=b;
  }
  return ret+n;
}
int main(){
  ll n,s;cin>>n>>s;
  if(n==s){
    cout<<n+1<<endl;
    return 0;
  }
  for(ll i=2;i<=sqrt(n);i++){
    if(s == calc(i,n)){
      cout<<i<<endl;
      return 0;
    }
  }
  ll ans=llINF;
  for(ll i=1;i<sqrt(n);i++){
    if((n-s)%i!=0)continue;
    ll b=(n-s)/i+1;
    if(s == calc(b,n)){
      ans=min(ans,b);
    }
  }
  if(ans==llINF)
  cout<<-1<<endl;
  else
    cout<<ans<<endl;
  return 0;
}

