constexpr ll INF = 1e18;

ll f(ll b, ll n) {
    if (n < b) {
        return n;
    } else {
        return f(b, n / b) + n % b;
    }
}

int main(void) {
    ll n, s;
    cin >> n;
    cin >> s;

    if (n == s) {
        cout << n + 1 << endl;
        return 0;
    }

    if (n < s) {
        cout << -1 << endl;
        return 0;
    }

    for (ll b = 2; b * b <= n; b++) {
        ll ans = f(b, n);
        if (f(b, n) == s) {
            cout << b << endl;
            return 0;
        }
    }

    ll ans = INF;
    for (ll c = 1; c * c <= n; c++) {
        ll b = (n - s) / c + 1;
        cout << b << endl;
        if (f(b, n) == s) {
            ans = min(ans, b);
        }
    }

    cout << (ans == INF ? -1 : ans) << endl;
    return 0;
}

