ll f(ll b, ll n){
  if(b > n) return n;
  else return f(b, n / b) + n % b;
}

void solve(){
  // main algorithm
  if(N == M) ans = N + 1;
  int root = (int)sqrt(N);
  for (int b = 2; b <= root + 1; ++b)
  {
    if(f(b, N) == M) {
      debug("%d\n", b);
      ans = b;
      return;
    }
  }
  for (int p = root + 1; p >= 1; --p)
  {
    ll q = M - p;
    if((N - q) % p) continue;
    int bb = (N - q) / p;
    if (bb > root && bb >= 2 && bb > q && p < bb && f(bb, N) == M)
    {
      ans = bb;
      debug("%d, %lld, %d\n", p, q, bb);
      return;
    }
  }
  if(ans == INFLL) ans = -1;
}
