	int m = sqrt(n); m++;
	long long res = -1;
	for(int i = 2; i <= m; i++) {
		long long tmp = n, sum = 0;
		while(tmp) {
			sum += tmp % i;
			tmp /= i;
		}
		if(sum == s) {
			res = i;
			break;
		}
	}
	if(res < 0) {
		long long tmp = n - s;
		if(tmp > 0) {
			for(int i = 2; i * i <= tmp; i++) {
				if(tmp % i == 0) {
					long long x = tmp / i + 1, a = i;
					long long b = s - a;
					if(x > a && x > b && a * x + b == tmp) {
						if(res < 0 || res > x) res = x;
					}
				}
			}
		}
	}
	printf("%lld\n", res);
	return 0;
}

