    ios_base::sync_with_stdio(false);
    lint n, s;
    cin >> n >> s;
    lint ans = -1;
    if(n == s){
        ans = n + 1;
    }
    else if(s > (n + 1) / 2){
        ans = -1;
    }
    else {
        lint sqrt_n = sqrt(n);
        // debug(sqrt_n);
        for (lint b = 2; b <= sqrt_n; ++b){
            if(digit_sum(n, b) == s){
                ans = b;
                break;
            }
        }
        if(ans == -1){
            lint d;
            for (lint b = sqrt_n; b >= 2; --b){
                d = n % b;
                if((s - b - d) >= 0 && (s - b - d) % b == 0){
                    lint k = (s - b - d) / b;
                    ans = b - k;
                    break;
                }
                else {
                    continue;
                }
            }
            if(ans == -1){
                ans = n + 1 - s;
            }
        }
    }
    cout << ans << "\n";
    return 0;
}

