      b = inf;
      REP(a, 1, nnn) {
        if ((n - s) % a == 0 and f((n - s) / a + 1, n) == s) b = min(b, (n - s) / a + 1);
      }

      if (b == inf) b = -1;

    }

  }

  ccout << b << endl;

}

