const ll INF = 1e+18;

vector<ll> divisors(ll n){
	vector<ll> ret;
	ret.push_back(1);
	for(ll i = 2 ; n > 1 ; i ++){
		if(i*i > n)i = n;
		if(n%i == 0){
			int cnt = 0;
			while(n%i == 0){
				n /= i;
				cnt ++;
			}
			int sz = ret.size();
			for(int j = 0 ; j < sz ; j ++){
				ll x = ret[j];
				for(int k = 0 ; k < cnt ; k ++){
					x *= i;
					ret.push_back(x);
				}
			}
		}
	}
	return ret;
}

ll f(ll n,ll b){
	if(b == 1)return -1;
	if(n == 0)return 0;
	return n%b+f(n/b,b);
}

