		return 0;
	}
	if(n == s){
		cout << n+1 << endl;
		return 0;
	}

	//puts("DEBUG");

	ll ret = INF;
	for(ll i = 1 ; i <= (ll)(sqrt((ld)n)+1e-6) ; i ++){
		if(f(n,i)==s)ret = min( ret , i );
	}

	//puts("DEBUG");

	vector<ll> d = divisors(n-s);
	for(ll i = 0 ; i < d.size() ; i ++){
		if(f(n,d[i]+1)==s)ret = min( ret , d[i]+1 );
	}
	if(ret == INF)puts("-1");
	else cout << ret << endl;
}

