    sq = sqrt(n - s);
    ll mn = INF, dif = n - s;
    for (int p = 1; p <= sq; p++) {
        if (dif % p == 0) {
        ll b = p;

        if (b >= 1 && mn > b + 1 && f(b + 1, n) == s) mn = b;
        if (dif / b >= 1 && mn > dif / b + 1 && f(dif / b + 1, n) == s) mn = dif / b;    
        }
    }
    if (mn == INF) {
        cout << "-1";
    } else {
        cout << mn;
    }
    return 0;
}

