long long digit_sum(long long n, long long base = 10) {
    long long res = 0;
    while (n > 0) res += n % base, n /= base;
    return res;
}

int main() {
    long long n, s; cin >> n >> s;
    if (n < s) return cout << -1 << endl, 0;
    if (n == s) return cout << n + 1 << endl, 0;
    set<long long> res;
    for (long long b = 2; b * b <= n; b++) {
        if (digit_sum(n, b) == s) res.emplace(b);
    }
    for (long long p = 1; p * p < n; p++) {
        if ((n - s) % p == 0) {
            long long b = (n - s) / p + 1;
            if (0 <= s - p && s - p < b) res.emplace(b);
        }
    }
    if (res.empty()) {
        cout << -1 << endl;
    } else {
        cout << *res.begin() << endl;
    }
    return 0;
}

