long long solve(long long n, long long s){
    for(long long b=2;b*b<=n;b++){
        if(f(b, n) == s) return b;
    }
    long long res = -1;
    for(long long d=1;d*d<n;d++){
        long long src = n/(d+1) + 1;
        long long dst = n/d;
        if(n-s+d < 0) continue;
        if((n-s+d)%d != 0) continue;
        int c = (n-s+d)/d;
        if(c < src || dst < c) continue;
        if(res == -1 || c < res) res = c;
    }
    if(res != -1) return res;
    if(s == 1) return n;
    if(s == n) return n+1;
    return -1;
}

int main(){
    long long n, s;
    while(cin >> n >> s){
        cout << solve(n, s) << endl;
    }
}

