int main() {
	long long n, s;
	scanf("%lld%lld", &n, &s);
	if(n == s) {
		printf("%lld\n", n + 1);
		return 0;
	}
	if(s == 1) {
		printf("%lld\n", n);
		return 0;
	}
	int m = sqrt(n); m++;
	long long res = -1;
	for(int i = 2; i <= m; i++) {
		long long tmp = n, sum = 0;
		while(tmp) {
			sum += tmp % i;
			tmp /= i;
		}
		if(sum == s) {
			res = i;
			break;
		}
	}
	if(res < 0) {
		long long tmp = n - s;
		if(tmp > 0) {
			for(int i = 2; 1LL * i * i <= tmp; i++) {
				if(tmp % i == 0) {
					long long x = tmp / i + 1, a = i;
					long long b = s - a;
					if(a * x + b == tmp) {
						if(res < 0 || res > x) res = x;
					}
				}
			}
		}
	}
	printf("%lld\n", res);
	return 0;
}

