using namespace std;
using lint = long long;

const int BLOCK = 1e6;

lint n, s;

lint trial(lint x, lint cur = n) { // sum of digits of cur is base x
  if (cur < x) {
    return cur;
  }
  return trial(x, cur / x) + (cur % x);
}

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);

  cin >> n >> s;

  for (lint i = 2; i < BLOCK; i++) {
    if (trial(i) == s) {
      cout << i << "\n";
      return 0;
    }
  }

  // base-b is now at most 2 digit
  // pb + q = n
  // p + q = s
  // n - s = b(p - 1)
  // thus b | n - s
  // iterate on divisors of n - s

  if (n - s < 0) {
    cout << -1 << "\n";
    return 0;
  }

  vector<lint> cand;
  for (lint b = 1; b * b <= n - s; b++) {
    if ((n - s) % b == 0) {
      lint f1 = b;
      lint f2 = (n - s) / b;
      cand.emplace_back(f1);
      cand.emplace_back(f2);
    }
  }

  sort(begin(cand), end(cand));

  for (auto &b : cand) {
    if (b < 2) continue;
    if (trial(b) == s) {
      cout << b << "\n";
      return 0;
    } 
  }

  if (trial(n) == s) {
    cout << n << "\n";
    return 0;
  }

  cout << -1 << "\n";
  return 0;
}

