const ll INF = 1LL << 60;
ll n, s;

ll digitSum(ll x, ll b) {
  ll res = 0;
  while (x) {
    res += x % b;
    x /= b;
  }
  return res;
}

int main() {
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  cin >> n >> s;
  if (n == s) {
    cout << s+1 << endl;
