  for (ll b = 2; b*b <= n; b++) {
    if (digitSum(n, b) == s) {
      cout << b << endl;
      return 0;
    }
  }
  ll ans = INF;
  for (ll i = 1; i*i < n; i++) {
    ll tmp = n - s + i;
    if (tmp < 0) continue;
    if (tmp % i != 0) continue;
    ll b = tmp / i;
    if (b < 2) continue;
    if (digitSum(n, b) == s) {
      ans = min(ans, b);
    }
  }
  cout << (ans == INF ? -1 : ans) << endl;

  return 0;
}

