        if (p >= b || q >= b || p < 0 || q < 0) {
            return;
        }
        if (p * b + q != n) {
            return;
        }
        ans = min(ans, b);
    };
    for (ll i = 1; i * i <= f; i++) {
        if (f % i == 0) {
            relax(i);
            relax(f / i);
        }
    }
