        cout << n+1 << endl;
        return 0;
    }
    if(s > n){
        cout << -1 << endl;
        return 0;
    }
    for(ll i = 2; i * i <= n; i++){
        if(f(i, n) == s){
            cout << i << endl;
            return 0;
        }
    }

    ll ans = -1;
    for(ll i = 1; i * i < n; i++){
        if((n-s)%i != 0) continue;
        ll b = (n-s)/i + 1;
        if(f(b,n) == s){
            ans = b;
        }
    }
    cout << ans << endl;
}

