vector<ll> divisor(ll n){//O(n^(1/2))
	vector<ll> ret,spare;
	for(ll i=1;i*i<=n;++i){
		if(!(n%i)){
			ret.pb(i);
			if(i*i!=n) spare.pb(n/i);
		}
	}
	for(int i=spare.size()-1;i>=0;--i){
		ret.pb(spare[i]);
	}
	return ret;
}

