		p(-1);return;
	}

	ll sqrtN=sqrt(N)+1;
	for(ll i=2;i<=sqrtN;i++){
		ll d=f(i,N);
		if(d==S){
			p(i);return;
		}
	}

	vector<ll> v=divisor(N-S);
	for(ll x:v){
		ll b=x+1;
		ll p=(N-S)/x;
		ll q=S-p;
		if(b>sqrtN && p>=0 && q>=0){
			cout<<b<<endl;return;
		}
	}

	p(-1);
}

