LL f(LL b, LL n){
	if(b == 1) return n;
	LL res = 0;
	while(n != 0){
		res += n%b;
		n /= b;
	}
	return res;
}

int main()
{
	ios_init();
	LL n,s;
	while(cin >> n >> s){
		if(s == 1){
			cout << n << endl;
			continue;
		}
		LL ans = INF;
		for(LL i = 1; i <= sqrt(n); ++i) {
			LL ret = f(i,n);
			if(ret == s){
				ans = min(ans,i);
				break;
			}
		}
		if(ans == INF){
			stack<LL> sta;
			for(LL i = 1; i*i <= n; ++i) {
				sta.push((n)/i+1);
			}
			while(SZ(sta) > 1){
				LL l,r;
				l = sta.top();
				sta.pop();
				r = sta.top();
				LL ret = f(l,n);
				LL u = n/l;
				// DEBUG(l);
