ll solve(ll n, ll s) {
  if(n == s) return n + 1LL;
  for(ll b = 2LL; b * b <= n; ++b) {
    if(f(b, n) == s) return b;
  }
  ll res = INF;
  for(ll p = 1LL; p * p <= n; ++p) {
    if(n % p != s % p) continue;
    ll b = (n - s) / p + 1LL;
    if(b < 2LL) continue;
    if(f(b, n) == s) res = min(res, b);
  }
  if(res < INF) return res;
  return -1LL;
}

