using namespace std;

using ll = long long;

ll n, s;

ll calc(ll n, ll mid){
	ll sum = 0;
	ll tmp = n;
	while(tmp){
		sum += tmp % mid;
		tmp /= mid;
	}
	return sum;
}

int main(){
	cin >> n >> s;
	if(n < s){
		cout << -1 << '\n';
		return 0;
	}
	else if(s == 1){
		cout << n << '\n';
		return 0;
	}
	ll tmp = n - s;
	ll ans = 1e12;

	for(ll i = 2; i * i <= tmp; i ++){
		if(tmp % (i - 1)) continue;
		ll ret = calc(n, i);
		if(ret == s){
			ans = min(ans, i);
		}
		ll d = tmp / (i - 1);
		ret = calc(n, d + 1);
		if(ret == s){
			ans = min(ans, d + 1);
		}
	}
	if(ans == 1e12) cout << -1 << '\n';
	else cout << ans << '\n';
}

