int main() {
    LL n,s;
    scanf("%lld%lld",&n,&s);
    if(n==s)
        printf("%lld\n",s+1);
    else if(n<s)
        printf("-1\n");
    else {
        LL mid=sqrt(n)+1;
        bool flag=false;

        //b>sqrt(n)
        LL res;
        for(LL i=2; i<=mid; i++) { //枚举b
            res=0;
            LL temp=n;
            while(temp) {
                res+=temp%i;
                temp/=i;
            }
            if(res==s) {
                printf("%lld\n",i);
                flag=true;
                break;
            }
        }

        //b<=sqrt(n)
        if(!flag) {
            LL factor=n-s;
            LL res;
            for(LL i=mid; i>=1; i--) {//枚举x1
                if(factor%i==0) {
                    res=factor/i+1;
                    LL j=s-i;//x2
                    if(i<res&&res>=2&&j<res&&i>=0) { //判断b的合法性
                        printf("%lld\n",res);
                        flag=true;
                        break;
                    }
                }
            }
        }

        //其他情况
        if(!flag)
            printf("-1\n");
    }

    return 0;
}

