int main(){
    int64_t n, s;
    cin >> n >> s;

    if(n < s){
        cout << -1 << endl;
        return 0;
    }
    if(n == s){
        cout << n + 1 << endl;
        return 0;
    }
    for(int64_t i = 2; i * i <= n; ++i){
        int64_t sum = 0;
        int64_t m = n;
        while(m > 0){
            sum += m % i;
            m /= i;
        }
        if(sum == s){
            cout << i << endl;
            return 0;
        }
    }
    for(int64_t i = 1; i * i <= n; ++i){
        int64_t b = (n - s) / i + 1;
        if(b < 1) continue;
        int64_t sum = 0;
        int64_t m = n;
        while(m > 0){
            sum += m % b;
            m /= b;
        }
        if(sum == s){
            cout << b << endl;
            return 0;
        }
    }
    cout << -1 << endl;
}

