ll n,s;

ll f(ll b, ll n){
	return n < b ? n : f(b, n/b) + n%b;
}

ll solve(){
	cin >> n >> s;

	if(n==s) return n + 1;

	for(ll i=2;i*i<=n;i++){
		if(f(i, n) == s)return i;
	}

	if(n-s<0) return -1;

	for(ll p=1;p*p<n;p++){
		if((n-s)%p==0){
			ll b = (n-s)/p + 1;
			if(b>=2 && f(b, n) == s)return b;
		}
	}

	return -1;
}

int main() {

	cout << solve();
	cout << endl;
}

