using namespace std;
typedef long long ll;

bool ok(ll x, ll n, ll s) {
  ll sum = 0;
  while (n) {
    sum += n % x;
    n /= x;
  }
  return sum == s;
}

int main(void) {
  ll n, s;
  cin >> n >> s;

  ll ans = -1;
  if (s == n) {
    ans = n + 1;
  } else {
    for (ll b = 2; b * b <= n; b++) {
      if (ok(b, n, s)) {
        ans = b;
        break;
      }
    }
    if (ans < 0) {
      for (ll p = 1; p * p < n; p++) {
        ll b = (n - s) / p + 1;
        if (ok(b, n, s)) {
          ans = b;
          break;
        }
      }
    }
  }

  cout << ans << endl;

  return 0;
}

