ll f(ll b, ll n) {
    ll s = 0;
    while (n > 0) {
        s += n % b;
        n /= b;
    }
    return s;
}

ll N, S;

void solve() {
    if (N == 1 && S == 1) {
        write(2); return;
    }
    else if (S == N) {
        write(N + 1); return;
    }
    else if (N == 1) {
        write(-1); return;
    }

    ll s_max = f(N / 2 + 1, N);
    if (S > s_max) {
        write(-1); return;
    }

    ll b_sqrt = sqrt(N);
    for (ll b = 2; b < b_sqrt; ++b) {
        if (f(b, N) == S) {
            write(b); return;
        }
    }

    for (ll i = N / b_sqrt; i > 1; --i) {
        ll b1 = N / i;
        ll s1 = f(b1, N);
        if (s1 < S) continue;
        else if (s1 == S) {
            write(b1); return;
        }
        ll b2 = N / (i - 1);
        ll s2 = f(b2, N);
        if (s2 > S) continue;
        else if (s2 == S) {
            write(b2); return;
        }

        while (b2 - b1 > 1) {
            ll mid = (b2 + b1) / 2;
            if (f(mid, N) >= S) {
                b1 = mid;
            }
            else {
                b2 = mid;
            }
        }
        if (f(b1, N) == S) {
            write(b1); return;
        }
    }
    write(-1);
}

int main() {
    cin >> N >> S;

    //for (int b = 2; b < 5000; ++b) {
    //    cout << b << " " << N / b << " " << f(b, N) << "\n";
    //}
    solve();
}

