long long func(long long b, long long n) {
  if (b > n) return n;

  return func(b, n / b) + (n % b);
}

int main() {
  long long n;
  long long s;

  cin >> n;
  cin >> s;

  bool found = false;
  double root_n = sqrt(n);
  long long b;
  for (b = 2; b <= root_n; b++) {
    if (s == func(b, n)) {
      found = true;
      break;
    }
  }

  if (found) {
    cout << b << endl;
    return 0;
  }

  for (long long p = root_n; p >= 1; p--) {
    b = (n - s) / p + 1;
    if (b >= 2 && s == func(b, n)) {
      found = true;
      break;
    }
  }

  if (found) {
    cout << b << endl;
  } else {
    cout << -1 << endl;
  }

  return 0;
}

