		ll lo = ma;
		bool find = false;
		ll mid;
		ll count = 0;
		while (lo < tm && count <= 50)
		{
			mid = (tm + lo) / 2LL;
			ll va = f(mid, n);
			if (va > s) {
				lo = mid;
			}
			else if (va < s) {
				tm = mid;
			}
			else {
				find = true;
				break;
			}
			count++;
		}
		if (find) {
			res = mid;
		}
	}
