ll f(ll b, ll n) {
	if (n < b) return n;
	return f(b, n / b) + n % b;
}

int main() {
	ll n, s;
	cin >> n >> s;

	if (n == 1 and s == 1) {
		cout << 2 << endl;
		return 0;
	}

	// b \in [2, \sqrt{n}]
	for (ll b = 2; b * b <= n; b++) {
		if (f(b, n) == s) {
			cout << b << endl;
			return 0;
		}
	}

	// b \in (\sqrt{n}, n + 1]
	ll ans = -1;
	for (ll x = 1; x * x <= n - s; x++) {
		if ((n - s) % x != 0) continue;

		ll b = (n - s) / x + 1,
		   y = s - x;

		if (1 <= x and x < b and 0 <= y and y < b) {
			ans = b;
		}
	}

	cout << ans << endl;

	return 0;
}

