  return (f(b, n / b) + n % b);
}

int64 Search(int64 N, int64 S)
{
  if(N > S) return(-1);
  if(N == S) return (N + 1);
  for(int64 i = 2; i * i <= N; i++) {
    if(f(i, N) == S) return (i);
  }
  for(int64 i = sqrt(N); i > 0; i--) {
    if((N - S) % i == 0 && f((N - S) / i + 1, N) == S) return ((N - S) / i + 1);
  }
  return (-1);
}

