	range (b, 2, sqrt(n) + 1) {
		int tmp = fun(b, n);
		if (s == tmp) ans = min(ans, b);
	}
	range (p, 1, sqrt(n)) {
		int b = (n - s) / p + 1;
		if (fun(b, n) == s) ans = min(ans, b);
	}
	cout << (ans == INF ? -1 : ans) << endl;
	return 0;
}

