	if (b <= 1) return -1;
	if (b > n) return n;
	return f(b, n / b) + (n % b);
}

void solv() {
	ll n,s;
	cin >> n;
	cin >> s;
	if (n == s) {
		cout << n + 1 << endl;
		return;
	}

	if (n == 1 && s > 1) {
		cout << -1 << endl;
		return;
	}
	ll pp = sqrt(n);
	ll bef = 0;
	for (ll i = 2; i <= 1000000; i++)
	{
		ll v = f(i, n);
		if (v == s) {
			cout << i << endl;
			return;
		}
		//if (bef < v)
		//	cout << i << " " << v << endl;
		//bef = v;
		//if (s == f(i, n)) {
		//	cout << i << endl;;
		//}
	}
	ll in = 1;
	ll ma = n;
	ll res = (s == 1) ? n : -1;
	while (ma >= pp)
	{
		ll tm = ma;
		in++;
		ma = (n / in);
		ll lo = ma + 1;
		bool find = false;
		ll mid;
		ll count = 0;
		while (lo <= tm && count <= 50)
		{
			mid = (tm + lo) / 2LL;
			ll va = f(mid, n);
			if (va > s) {
				lo = mid;
			}
			else if (va < s) {
				tm = mid;
			}
			else {
				find = true;
				break;
			}
			count++;

		}
		if (find) {
			res = mid;
		}
	}
	if (res == -1) {
		cout << -1 << endl;
	}else
		cout << res << endl;
}

