template<typename T, typename F>
void divisors_foreach(T n, F f)
{
    T i = 1;
    for(; i*i < n; ++i) {
        if(n % i == 0) {
            f(i);
            f(n/i);
        }
    }

    if(i*i == n) {
        f(i);
    }
}

template<typename T>
vector<T> divisors(T n)
{
    vector<T> res;

    divisors_foreach(n, [&res](T d) {
        res.emplace_back(d);
    });

    return res;
}

