{
	std::int64_t s, n;
	std::cin >> n >> s;
	if (n < s)
	{
		lib::write_line(-1);
		return;
	}
	std::function<std::int64_t(std::int64_t, std::int64_t)> f = [&](std::int64_t b, std::int64_t m)
	{
		return m >= b ? (m % b) + f(b, m / b) : m;
	};
	for (std::int64_t b = 2; b*b <= n; ++b)
	{
		if (f(b, n) == s)
		{
			lib::write_line(b);
			return;
		}
	}
	std::set<std::int64_t> yaku;
	for (std::int64_t p = 1; p*p <= n - s; ++p)
	{
		if (p*p == n - s)
		{
			yaku.emplace(p);
		}
		else if ((n - s) % p == 0)
		{
			yaku.emplace(p);
			yaku.emplace((n - s) / p);
		}
	}
	for (auto const& p : yaku)
	{
		auto b = p + 1;
		if (b*b <= n)
		{
			continue;
		}
		auto x = (n - s) / (b - 1);
		auto y = s + (s - n) / (b - 1);
		if (0 <= x && x < b && 0 <= y && y < b)
		{
