LL f(LL b, LL n) {
    if (n < b) return n;
    return f(b, n/b) + n%b;
}

LL solve(LL L, LL R) {
    LL s1 = f(L, n);
    if (s1 == s) return L;
    if (L == R) return -1;
    LL s2 = f(L+1, n);
    LL d = s1 - s2;
    if (s <= s1 && (s1 - s) % d == 0 && (s1 - s) / d <= R - L)
        return L + (s1 - s) / d; 
    return -1;
}

