  // ここで見つからなかった地点で、bはsqrt(N)より大きい
  // b が結構大きいので、Nはb進数で2桁になるはず
  // よって、N = pb + q, 1<=p<b, 0<=q<b　と表せる
  // pの範囲について、N = pb + q >= pb > p^2 となるため
  // p < sqrt(N)
  // pを全探索できる。pを決めると、p + q = S から
  // b = (N - q) / p = (N - S + p) / p = (N - S) / p + 1
  // と決まる。あとは、f(b, N) = Sかどうか確認すれば良い

  ll ans = -1;
  for(ll p = 1; p * p < N; p++) {
    if ((N - S) % p != 0) continue;
    ll b = (N - S) / p + 1;
    if (b <= 1) continue;
    if (f(b, N) == S) {
