			if (y<0) continue;
			ll lhs=n-y;
			if (lhs%x==0) {
				ll b=lhs/x;
				//if (x==1) printf("ddx:%lld lhs:%lld b:%lld\n",x,lhs,b);
				if (b>=lim&&x<b&&y<b) {
					//printf("x:%lld lhs:%lld b:%lld\n",x,lhs,b);
					chkmin(ans,b);
				}
			}
		}
		if (n==s) chkmin(ans,n+1);
		if (ans>=INF) return -1;
		return ans;
	}
}
int main() {
	ios_base::sync_with_stdio(false);
	ll n,s; cin>>n>>s;
	cout<<solve(n,s)<<endl;
}

