typedef long long int lli;
typedef pair<lli, int> pli;
long long int n, s;
const int SIZE = 400005;
bool isPrime[SIZE];
vector<pli> v;
lli INF = 12345987654321;
lli ans = INF, tmp=1;

void check(int p){
	if(p == v.size()){
		lli b = tmp+1, t=n, sum=0;
		while(t){
			sum += t % b;
			t /= b;
		}
		if(sum == s && b < ans)
			ans = b;
		return;
	}
	lli save = tmp;
	for(int i=0; i<=v[p].second; ++i){
		check(p+1);
		tmp *= v[p].first;
	}
	tmp = save;
}

int main(){
	scanf("%lld%lld", &n, &s);	
	long long int t = n - s;
	for(int i=2; i<SIZE; ++i)
		isPrime[i] = true;
	for(lli i=2; i<SIZE; ++i){
		if(isPrime[i]){
			for(lli j=i*i; j<SIZE; j+=i)
				isPrime[j] = false;
			int cnt=0;
			while(t % i == 0){
				++cnt;
				t /= i;
			}
			if(cnt)
				v.push_back({i, cnt});
		}
	}
	if(t > 1)
		v.push_back({t, 1});
	check(0);
	if(ans == INF)
		ans = -1;
	printf("%lld\n", ans);
}

