typedef long long LL;
LL f(LL b, LL n)
{
	if(n<b) return n;
	else return f(b,n/b)+(n%b);
}
LL solve()
{
	LL n, s; cin >> n >> s;

	LL b;
	for(b = 2; b*b <= n; b++)
		if(f(b,n)==s)
			return b;

	//else, b = first value such that b*b > n
	// b > n/b > floor(n/b), therefore b > q

	for(LL q = b; q > 0; q--)
		if(s-q >= 0 && (n-(s-q))%q==0 && (n-(s-q))/q > 1 && f((n-(s-q))/q,n)==s)
			return (n-(s-q))/q;

	if(n==s) return n+1;
	return -1;
}
