            if(dt<0) dt += i;
            ans += dt;
            tmp /= i;
        }
        if(ans==S) {
            cout << i << endl;
            return 0;
        }
    }
    const auto &res = prime_factorize(N-S);
    for (auto p : res) {
        if(p.first+1>sqrt(N)) {
