long long f(long long b, long long n) {
	if (n < b) return n;
	return f(b, n / b) + n % b;
}

vector<long long> divisors(long long n) {
	vector<long long> res;
	for (long long i = 1; i * i <= n; i++) {
		if (n % i == 0) {
			res.push_back(i);
			if (i != n / i) res.push_back(n / i);
		}
	}
	sort(res.begin(), res.end());
	return res;
}

int main() {
	long long n, s;
	cin >> n >> s;

	for (int i = 2; i < 1e6; i++) {
		if (f(i, n) == s) {
			cout << i << endl;
			return 0;
		}
	}

	if (n == s) {
		cout << s + 1 << endl;
		return 0;
	}

	if (n - s < 0) {
		cout << -1 << endl;
		return 0;
	}

	long long mini = LLONG_MAX;

	{
		long long k = 1;
		long long l = s - 1;
		long long b = n - s + 1;

		if (k * b + l == n && k + l == s && b >= 1e6 && l >= 0) {
			mini = b;
		}
	}

	for (long long d : divisors(n - s)) {
		long long k = d + 1;
		long long b = (n - s) / d;

		long long l = s - k;

		if (k * b + l == n && k + l == s) {
			if (k > 0 && l >= 0 && b >= 1e6) {
				mini = min(mini, b);
			}
		}
	}

	if (mini == LLONG_MAX) {
		cout << -1 << endl;
	} else {
		cout << mini << endl;
	}
}

