ll calc(ll b, ll n) {
	if (n < b) 	return n;
	else return n%b + calc(b, n / b);
}

int main() {
	ll n, s; cin >> n >> s;
	if (n == s) {
		cout << n + 1 << endl;
		return 0;
	}

	// b <= √n) の場合、全探索可能
	ll root = sqrt(n);
	for (ll b = 2; b <= root; ++b) {
		ll tmp = calc(b, n);
		if (tmp == s) {
			cout << b << endl;
			return 0;
		}
	}

	// b >= √n の場合
	//   n = p*b + q (q < b)
	//   s = p + q
	// b >= √nなので、
	// n >= p * √n + q -> p <= √n
	// p == 0の場合 -> n==sなので検査済み
	ll ans = -1;
	for (ll p = 1; p <= root; ++p) {
		ll q = s - p;
		ll b = (n-s)/p + 1;
		if (b <= root || q > b) continue;
		ll tmp = calc(b, n);
		if (tmp == s) {
			ans = b;
		}
	}

	cout << ans << endl;
	return 0;
}

#include <iostream>
using namespace std;
using ll = long long;

ll f(ll b, ll n) {
  if (n < b) {
    return n;
  }
  return f(b, n / b) + (n % b);
}

ll solve(ll n, ll s) {
  ll b = 2;
  while (n / b >= b) {
    if (f(b, n) == s) {
      return b;
    }
    ++b;
  }
  for (ll k = n / b; k >= 1; k--) {
    ll rem = s - k;
    if (rem < 0) {
      continue;
    }
    ll sb = max(b, n / (k + 1) + 1);
    ll sm = n % sb;
    if (rem > sm || (sm - rem) % k != 0) {
      continue;
    }
    return sb + (sm - rem) / k;
  }
  if (s == n) {
    return n + 1;
  }
  return -1;
}

int main() {
  ll n, s;
  cin >> n >> s;
  cout << solve(n, s) << endl;
  return 0;
}

