ll f(ll b, ll n) {
  if (n < b) return n;
  return f(b, n/b) + n % b;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll n,s;
  cin>>n>>s;
  if (s > n) {
    cout << -1 << endl;
    return 0;
  } else if (s == n) {
    cout << n+1 << endl;
    return 0;
  }
  FOR(i,2,400000) {
    if (f(i,n) == s) {
      cout<<i<<endl;
      return 0;
    }
  }
  ll d = n - s;
  set<ll> candi;
  for (ll i = 1; i*i <= d; ++i) {
    if (d % i == 0) {
      candi.insert(i+1);
      candi.insert(d/i+1);
    }
  }
  for (auto&& b : candi) {
    if (b < 400000) continue;
    if (f(b, n) == s) {
      cout<<b<<endl;
      return 0;
    }
  }
  cout<<-1<<endl;
  return 0;
}

