long long GetSum(long long b, long long n) {
    long long result = 0;
    while (n > 0) {
        result += n % b;
        n /= b;
    }
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, s;
    cin >> n >> s;

    long long bResult = -1;

    auto updateResult = [&bResult, n, s] (long long b) {
        if (b >= 2 && GetSum(b, n) == s && (b < bResult || bResult == -1)) {
            bResult = b;
        }
    };

    updateResult(n + 1);

    if (n > s) {
        const long long m = n - s;
        for (long long d = 1; d * d <= m; ++d) {
            if (m % d == 0) {
                long long d1 = d;
                long long d2 = m / d1;

                updateResult(d1 + 1);
                updateResult(d2 + 1);
            }
        }
    }

    for (long long b = 2; b * b <= n; ++b) {
        updateResult(b);
    }

    cout << bResult << endl;

    return 0;
}

