int main() {
	i64 n, s; scanf("%lld%lld", &n, &s);

	if(s == 1) {
		printf("%lld\n", n);
		return 0;
	}
	if(s == n) {
		printf("%lld\n", n + 1);
		return 0;
	}
	if(n < s) {
		printf("-1\n");
		return 0;
	}

	const i64 sqrtN = [n] {
		i64 ok = 1, ng = 1e6;
		while(ng - ok > 1) {
			i64 mid = (ok + ng) >> 1;

			if(mid * mid <= n) ok = mid;
			else ng = mid;
		}
		return ok;
	}();

	auto f = [](auto&& f, i64 b, i64 n) {
		if(n < b) return n;
		return f(f, b, n / b) + n % b;
	};

	i64 ans = 1LL << 60;
	for(i64 b = 2; b < sqrtN + 10; b++) {
		if(f(f, b, n) != s) continue;
		ans = std::min(ans, b);
		return 0;
	}

	for(i64 A = sqrtN; A > 0; A--) {
		const i64 b = n / A;
		const i64 B = (n - A * b);

		if(A * b + B != n) continue;
		if(A >= b or B >= b) continue;
		if((A + B - s) % A or A + B - s < 0) continue;
		i64 k = (A + B - s) / A;

		if(B - k * A < 0) continue;

		ans = std::min(ans, b);
	}
	if(ans != 1LL << 60) printf("%lld\n", ans);
	else printf("-1\n");
	return 0;
}

