llong n, s;

llong f(llong b, llong tn = n) {
    if (tn < b) return tn;
    return f(b, tn / b) + (tn % b);
}

int main(void) {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    cin >> n >> s;
    if (s > n)  {
        cout << -1;
        return 0;
    }
    if (s == 1) {
        cout << n;
        return 0;
    }

    for (int i = 2; i <= 1000000; ++i) {
        if (f(i, n) == s) {
            cout << i;
            return 0;
        }
    }

    llong ans = n;

    for (llong sd = 1; sd * sd <= n - s; ++sd) {
        if ((n - s) % sd) continue;
        for (llong d: {sd, (n - s) / sd}) {
            llong x = (n - s) / d - 1;
            if (x >= 2 and f(x, n) == s) ans = min(ans, x);
        }
    }
    if (ans == n) cout << -1;
    else cout << ans;

    return 0;
}

