template <class A, class B> class zip_t {
  using res_t = std::pair<typename A::iterator, typename B::iterator>;
  class iter : public std::iterator<std::input_iterator_tag,
                                    res_t,          // value_type
                                    std::ptrdiff_t, // difference_type
                                    res_t*,         // pointer
                                    res_t> {        // reference
    typename A::iterator a; typename B::iterator b;
  public:
    iter(typename A::iterator a, typename B::iterator b) : a(a), b(b) {}
    res_t operator*() { return res_t(*a, *b); }
    bool operator==(iter x) { return a == x.a; }
    bool operator!=(iter x) { return !(*this == x); }
    iter& operator++() { ++a; ++b; return *this; }
    iter operator++(int) { iter ret = *this; ++(*this); return ret; }
  };
  iter i, n;
public:
  zip_t(A &a, B &b) : i(a.begin(), b.begin()), n(a.end(), b.end()) {}
  iter &begin() { return i; }
  iter &end() { return n; }
};

