    int K = (int)sqrt(max(n, s)) + 1;
    for (int b = 2; b <= 2 * K + 1; ++b) {
        int sum = 0;
        int N = n;
        while (N > 0) {
            sum += N % b;
            N /= b;
        }
        if (sum == s) {
