    if (digSum == s) {
      cout << b << "\n";
      exit(0);
    }
  }
  // b > sqrt(n)
  auto ok = [](long long p, long long q, long long b) {
    return p >= 0 && p < b && q >= 0 && q < b;
  };
  long long ans = LONG_LONG_MAX;
  for (long long x = 1; x * x <= n - s; x++) {
    if ((n - s) % x == 0) {
      long long y = (n - s) / x;
      long long b = x + 1;
      long long p = (n - s) / x, q = s - p;
      if (ok(p, q, b)) ans = min(ans, b);
      b = y + 1;
      p = (n - s) / y;
      q = s - p;
      if (ok(p, q, b)) ans = min(ans, b);
    }
  }
  cout << ((ans == LONG_LONG_MAX) ? -1 : ans) << "\n"; 
