bool isS(LL x,LL p) {


	LL pow = 1;
	while (pow*p <= x) {
		pow *= p;
	}

	LL sum = 0;
	while (x > 0) {
		sum += x / pow;
		x = x % pow;

		pow /= p;
	}


	return S == sum;
}

