	for (LL i = 1; i*i < N && i <= S; i++) {
		LL m = S - i;

		if (N - m >= 0 && (N - m) % i == 0) {
			LL b = (N - m) / i;

			if (b > i && b > m) {
				ans = min(ans, (N - m) / i);
