        ll r = n/(i-1);
        ll mid = r;
        //cerr << target <<" : " << l << " , "<< r<<endl;
        while(r-l>1)
        {
            ll mid = (l+r)/2;
            if(n%mid<=target) r = mid;
            else l = mid;
            //cerr << mid << " : "<<n%mid << endl;
        }
        if(n%mid==target)return mid;
        if(n%r==target) return r;
    }
    if(s==1)return n;
    if(n==s)return n+1;
    return -1;
}

