typedef long long LL;
LL n, s;

LL f(LL b, LL n) {
    if (n < b) return n;
    return f(b, n/b) + n%b;
}
LL solve(LL L, LL R) {
    if (L == 1) return -1;
    LL s1 = f(L, n);
    if (L == R) {
        if (s1 != s) return -1;
        return L;
    }

    LL s2 = f(L+1, n);
    LL d = s1 - s2;
    if (s < s1 && (s1 - s) % d == 0 && (s1 - s) / d <= R - L)
        return L + (s1 - s) / d; 
    return -1;
}
int main() {
    cin >> n >> s;
    LL nex;
    for (LL i = 1; i <= n; i = nex + 1) {
        nex = n / (n / i);
        LL ans = solve(i, nex);
        if (ans != -1) {
            return !printf("%lld\n", ans);
        }
    }
    printf("-1\n");
}

