	else if ((n + 1) / 2 < s) {
		OUT(-1)BR;
	}
	else {
		ll ans = INFLL;
		FORLL(b, 2, std::sqrt(n) + 1) {
			if (f(b, n) == s) ans = std::min(ans, b);
		}
		FORLL(p, 1, std::sqrt(n)) {
			ll q = n%p;
			if (p + q == s) ans = std::min(ans, (n - q) / p);
		}
		OUT(ans)BR;
	}
	return 0;
}

