    if(n == s) return n;
    if(n < s) return -1;
    ull sqn = sqrt(n);
    for (ull b=2;b<sqn;b++){
        if(calculateF(b, n) == s) return b;
    }
    for (int p=sqn;p>0;p--){
        if((n-s)%p == 0 && (n-s)/p + 1 > p && (n-s)/p + 1 > s - p) return (n-s)/p + 1;
    }
    return -1;
}

