LL n,s;

LL func(LL b){
    LL res=0;
    LL m=n;
    while(m>0){
        res+=m%b;
        m/=b;
    }
    return res;
}

int main(){

    cin>>n>>s;

    LL ans=-1;
    if(s==n)ans=n+1;
    else if(s>n)ans=-1;
    else{
        LL digit=2;
        for(LL i=2;i*i<=n;i++){
            if(func(i)==s){
                ans=i;break;
            }
            digit=i+1;
        }
        if(ans<0){
            while(digit>1){
                LL left=n/digit;
                LL right=n/(digit-1);
                LL k=n/right;
                LL d=n%right;
                if((s-d)%k==0&&(s-d)/k>0&&(s-d)/k<=(right-left)){
                    ans=right+1-(s-d)/k;
                    break;
                }
                digit--;
            }
        }
    }
    cout<<ans<<endl;
    return 0;
}

