			printf("%lld", i);
			return 0;
		}
	}
	for(ll i=sqrt(n)-1;i>=1;i--){
		ll mid = i;
		ll cc = n / mid;
		ll oo = n / (mid + 1) + 1;
		ll xx = n / cc + (n%cc);
