int digit_sum(int base, int x){
    int res=0;
    while(x>0){
        res+=x%base;
        x/=base;
    }
    return res;
}

signed main(void){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n,s; cin>>n>>s;

    if(n==s){
        cout<<n+1<<endl;
        return 0;
    }

    int pl=2;
    while(pl*pl<=n){
        if(digit_sum(pl, n)==s){
            cout<<pl<<endl;
            return 0;
        }
        pl++;
    }

    int num=n/pl;
    int ans=INF;
    for(int i=1; i<=num; i++){
        int st=n/i,en=n/(i+1)+1,cr=digit_sum(st,n);
        if((s-cr)%i==0 and (s-cr)/i>=0 and (s-cr)/i<=st-en){
            chmin(ans,st-(s-cr)/i);
        }
    }

    if(ans==INF)cout<<-1<<endl;
    else cout<<ans<<endl;
    return 0;

}

