bool check(ll b)
{
	ll ret=0,t=n;
	for(;t;t/=b) ret+=t%b;
	return (ret==s);
}

ll solve()
{
	if(s==n) return n+1;
	if(s>n) return -1;

	for(ll i=2;i*i<=n;i++)
		if(check(i)) return i;
	for(ll i=1;i*i<=n;i++)
		if((n-s)%i==0&&check((n-s)/i+1)) return ((n-s)/i+1);
	return -1;
}

