ll f(ll b, ll n) { return (n < b ? n : f(b, n / b) + n % b); }
int main() {
    ll n, s;
    cin >> n >> s;
    for (ll i = 2; i * i <= n; i++) {
        if (f(i, n) == s) { cout << i << endl; return (0); }
    }
    for (ll i = ceil(sqrt(n)); i > 0; i--) {
        ll rem = s - i;
        if (rem < 0) continue;
        ll l = max({i, rem, 1ll}), r = n + 1;
        while (l + 1 < r) {
            ll m = (l + r) / 2;
            if (m * i + rem >= n) r = m;
            else l = m;
        }
        if (r * i + rem == n) {
            cout << r << endl;
            return (0);
        }
    }
    cout << -1 << endl;
    return (0);
}

