		cout << n + 1 << endl;
		return 0;
	}
	ll i;
	for (i = 2; i * i <= n; i++)
	{
		ll x = n;
		ll sum = 0;
		while (x > i)
		{
			sum += x % i;
			x /= i;
		}
		sum += x;
		if (sum == s)
		{
			cout << i << endl;
			return 0;
		}
	}
	ll y = n - s;
	for (ll j = 1; j * j <= y; j++)
		if (y % j == 0)
			vec.push_back(j), vec.push_back(y / j);
	sort(vec.begin(), vec.end(), cmp);
