vector<ll> divisor_enumerate(ll N){
    vector<ll> front,back;
    for(ll i=1;i*i<N+1;i++){
        if(N%i==0){
            front.push_back(i);
            back.push_back(N/i);
        }
    }
    while(!back.empty()){
        if(back.back()==front.back()) back.pop_back();
        else{
            front.push_back(back.back());
            back.pop_back();
        }
    }
    return front;
}

bool cheack(ll n,ll s,ll b){
    while(n!=0){
        s-=n%b;
        n=n/b;
    }
    return(s==0);
}

int main(){
    ll n,s;
    cin>>n>>s;
    if(n==s){
        cout<<n+1<<endl;
        return 0;
    }
    vector<ll> vec;
    vec=divisor_enumerate(max(n-s,s-n));
    while(!vec.empty()){
        if(cheack(n,s,vec.front()+1)){
            cout<<vec.front()+1<<endl;
            return 0;
        }
        vec.erase(vec.begin());
    };
    cout<<-1<<endl;
    return 0;
}

