  if (n < s) return -1;
  if (n == s) return n+1;
  ll sqrtN = sqrt(n);
  for (ll b = 2; b <= sqrtN; b++) {
    if (chk(b, n, s)) return b;
  }
  vector<ll> vDiv = getDivisors(n-s);
  sort(vDiv.begin(), vDiv.end());
  int k = vDiv.size();
  for (int j = k/2; j < k; j++) {
    ll b = vDiv[j] + 1;
    ll x = (n - s) / (b - 1);
    if (x < b && 0 <= s - x && s - x < b) return b;
  }
  return -1;
}

