        }
        return 0;
    }

    LL nex;
    for (LL i = 2; i <= n; i = nex + 1) {
        nex = n / (n / i);
        LL ans = solve(i, nex);
        if (ans != -1) {
            return !printf("%lld\n", ans);
        }
    }
    printf("-1\n");
}

