using namespace std;
long long sod(long long n, long long b){
	if(b <= 1) return 0;
	long long ans = 0;
	while(n){
		ans += n % b;
		n /= b;
	}
	return ans;
}
int main(){
	long long n, s; cin >> n >> s;
	const int magic = 1'000'000;
	auto check = [&](long long b){
		if(sod(n, b) == s){
			cout << b << endl;
			exit(0);
		}
	};
	for(int i = 2; i <= magic; i++){
		check(i);
	}
	/**
x * b + y = n
x + y = s
x * (b - 1) = n - s
	  **/
	if(n < s) return cout << -1 << endl, 0;
	if(n == s) return cout << n + 1 << endl, 0;
	for(int i = 1; i <= magic; i++){
		check(i + 1);
		check((n - s) / i + 1);
	}
	cout << -1 << endl;
	return 0;
}

