			return 0;
		}
	}
	vector<long long> ans;
	for (int i = 1; i <= 1000000; i++) {
		long long rest = s - i;
		long long b = (n - rest) / i;
		if ((n - rest) % i) continue;
		if (rest < b && b >= 2 && calc(n, b) == s) ans.push_back(b);
	}
	sort(ans.begin(), ans.end());
	if (ans.size() == 0) cout << "-1" << endl;
