LL solve() {
	if(n < s) { return -1; }

	incII(i, 1, 320000) {
		if((n - s) % i == 0) {
			LL j = (n - s) / i;
			vec.PB(i + 1);
			if(i >= j) { break; }
			vec.PB(j + 1);
		}
	}
	vec.PB(n + 1);
	sort(ALL(vec));

	LL ans = -1;
	inc(i, vec.size()) {
		if(f(vec[i])) { ans = vec[i]; break; }
	}

	return ans;
}

