ll chk(ll x, ll b) {
  ll sum = 0;
  while (x) {
    sum += x % b;
    x /= b;
  }
  return sum;
}

int main() {
  cin.tie(0);
  cin.sync_with_stdio(0);

  ll n, s;
  cin >> n >> s;
  ll ans = (s == 1 ? n : -1);
  for (ll b = 2; b * b <= n; ++b) {
    ll sum = chk(n, b);
    if (sum == s) {
      ans = b;
      break;
    }
  }
  if (ans == -1) {
    for (ll b = 1; b * b <= n; ++b) {
      if (n % b) continue;
      if (b - 1 >= 2 && chk(n, b - 1) == s)
        ans = ans == -1 ? b - 1 : min(ans, b - 1);
      auto bb = n / b;
      if (bb != b) {
        if (bb - 1 >= 2 && chk(n, bb - 1) == s)
          ans = ans == -1 ? bb - 1 : min(ans, bb - 1);
      }
    }
  }
  cout << ans;
}

