    int64_t sqrt_n = sqrt(double(n));
    int64_t min_b = -1;
    for (int64_t b = 2; b <= sqrt_n + 1; ++b) {
        if (check(n, s, b)) {
            if (min_b == -1 || min_b > b) min_b = b;
        }
    }
    if (n <= s) {
        cout << min_b;
        return 0;
    }
    int64_t a = n - s;
    int64_t sqrt_a = sqrt(double(a));
    for (int64_t i = 1; i <= sqrt_a + 1; ++i) {
        if (a % i != 0) continue;
        {
            int64_t b = i + 1;
            if (check(n, s, b)) {
