long long f(long long b, long long n)
{
	if (b > n) return n;

	return f(b, n / b) + n % b;
}

void CheckForB(long long n, long long s)
{
	long long max_sroot = 316228;

	if (n < s)
	{
		std::cout << -1 << std::endl;
		return;
	}

	if (n == s && n < 100000000000)
	{
		std::cout << n + 1 << std::endl;
		return;
	}

	long long b = 1;

	if (s < 2 * max_sroot) // it could be possible that there are 3 or more b-digits
	{
		while (++b < max_sroot)
		{
			if (f(b, n) == s)
			{
				std::cout << b << std::endl;
				return;
			}
		}

	}

	// now we left with at most 2 digits
	// and the first is at most max_sroot
	long long firstDigit = std::min(s, max_sroot), secondDigit = s - firstDigit;

	while ((++secondDigit, --firstDigit) > 0)
	{
		b = (n - secondDigit) / firstDigit;
		if ((b > std::max(max_sroot, secondDigit)) && ((n - secondDigit) % firstDigit == 0))
		{
			std::cout << b << std::endl;
			return;
		}
	}

	std::cout << -1 << std::endl;
}

int main(int, char**)
{
		long long n, s;

		std::cin >> n >> s;

		CheckForB(n, s);

	return 0;
}

