}

template<typename F> // [l,r] inclusive
LL binary_search_first_good(LL l, LL r, F good) {
    LL res = -1;
    while (r >= l) {
        LL mid = (l + r) >> 1;
        // EVARS(mid, f(mid, N), S);
        if (good(mid)) {
            res = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return res;
}



