bool is_prime(int p){
	if(p<=1)
		return false;
	for(int n=2; n<=pow(p,0.5);++n)
		if(p%n==0)
			return false;
	return true;
}
//n以下の最大の素因数を求める
int max_prime_divisor(int n){
	for(int x=n; x>1; --x)
		if(is_prime(x) && n%x==0)
			return x;
	return -1;
}
vi factorize(int n){
	vi factors;
	while(n>1){
		int p = max_prime_divisor(n);
		factors.emplace_back(p);
		n /= p;
	}
	sort(factors.begin(),factors.end());
	putv(factors);
	return factors;
}




//b進数での各桁の合計
ll f(ll b, ll n){
	if(n<b)
		return n;
	return f(b,n/b) + n%b;
}
int main(){
	ll n,s;
	cin >> n >> s;
	if(s==n){
		cout << n+1 << endl;
		return 0;
	}
	int sq = pow(n,0.5);
	for(int b=2; b<=sq; ++b)
		if(f(b,n)==s){
			cout << b << endl;
			return 0;
		}
	for(int p=1; p<=sq; ++p){
		if((n-s)%p != 0)
			continue;
		ll b = (n-s)/p+1;
		if(f(b,n)==s){
			cout << b << endl;
			return 0;
		}
	}
	cout << -1 << endl;
	return 0;
}

