void relax(ll a) {
  ll b = s - a;
  ll B = (n - s) / a;
  if (a < B && b < B && 0 <= b && 2 <= B && a * B + b == n) {
    ans = min(ans, B);
  }
}

void twoDigits() {
  if (n - s < 0) return;
  ll v = n - s;
  for (ll mul = 1; mul * mul <= v; mul++) {
     if (v % mul == 0) {
       relax(mul);
       relax(v / mul);
     }
  }
}

