ll f(ll b, ll n){
	if(n<b)
		return n;
	return f(b,n/b) + n%b;
}
int main(){
	ll n,s;
	cin >> n >> s;
	if(s==n){
		cout << n+1 << endl;
		return 0;
	}
	int sq = pow(n,0.5);
	for(int b=2; b<=sq; ++b)
		if(f(b,n)==s){
			cout << b << endl;
			return 0;
		}
	for(int p=sq; p>=1; --p){
		if((n-s)%p != 0)
			continue;
		ll b = (n-s)/p+1;
		if(f(b,n)==s){
			cout << b << endl;
			return 0;
		}
	}
	cout << -1 << endl;
	return 0;
}

