struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   long f(long b, long n) {
      long res = 0;
      while( n != 0 ) {
         res += n % b;
         n /= b;
      }
      return res;
   }
   void solve() {
      long n, s; scan(n, s);
      long inf = (1LL << 53);
      long res = inf;
      for(long b = 2; b <= 1000000; ++b) {
         if( f(b, n) == s ) {
            res = std::min(res, b);
            break;
         }
      }
      // x * b + y = n
      // x + y = s
      for(long x = 1000000; x >= 1; --x) {
         long b = n / x;
         long y = n - (b * x);
         if( b >= 2 and y < b and x + y == s ) {
            res = std::min(res, b);
         }
      }
      if( res == inf ) res = -1;
      printf("%ld\n", res);
   }
};

int main() {
  loop std::unique_ptr<Solver>(new Solver())->solve();
}

