    while (n > 0) {
        result += n % b;
        n /= b;
    }
    return result;
}

int main() {
    long long n, s, result = LLONG_MAX;
    cin >> n >> s;
    if (n == s) {
        result = n + 1;
    } else {
        for (long long b = 2; b * b <= n; b++) {
            if (digitsum(b, n) == s) {
                result = b;
                break;
            }
        }
        for (long long i = 1; i * i <= n - s; i++) {
            if ((n - s) % i == 0) {
                if (digitsum((n - s) / i + 1, n) == s) {
                    result = min(result, (n - s) / i + 1);
                }
                if (digitsum(i + 1, n) == s) {
                    result = min(result, i + 1);
                }
            }
        }
    }
    if (result == LLONG_MAX) {
        result = -1;
    }
    cout << result;
    return 0;
}

