using namespace std;

typedef long long ll;

ll f(ll b, ll n) {
    ll res = 0;
    while (n >= b) {
        res += n % b;
        n /= b;
    }
    return res + n;
}

ll solve(ll n, ll s) {
    if (n == s) return n + 1;
    for (ll b = 2; b * b <= n; b++) {
        if (f(b, n) == s) return b;
    }
    for (ll p = 1; p * p < n; p++) {
        ll b = (n - s) / p + 1;
        if (f(b, n) == s) return b;
    }
    return -1;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll n, s;
    cin >> n >> s;
    cout << solve(n, s) << "\n";
    return 0;
}

