ll f(ll n, ll s) {

	if(n==s) return n+1;
	if(n<s) return -1;

	for (ll i=2;i<=sqrt(n);i++) {
		if (check(n,i)==s) return i;
	}

	n-=s;

	for (ll i=sqrt(n+s)+1;i;i--) {
		if (check(n+s,n/i+1)==s) return n/i+1;
	}

	return -1; 
}

