LL N, S;

bool isS(LL x,LL p) {


	LL pow = 1;
	while (pow*p <= x) {
		pow *= p;
	}

	LL sum = 0;
	while (x > 0) {
		sum += x / pow;
		x = x % pow;

		pow /= p;
	}


	return S == sum;
}

int main() {
	cin >> N >> S;

	if (N < S) {
		cout << "-1" << endl;
		return 0;
	}

	if (N == S) {
		cout << N + 1 << endl;
		return 0;
	}

	LL ans = INF2;
	for (LL i = 2; i*i <=N; i++) {
		if (isS(N, i)) {
			ans = min(ans, i);
		}
	}

	if (ans != INF2) {
		cout << ans << endl;
		return 0;
	}

	LL D = N - S;
	for (LL p = 1; p*p <= N; p++) {

		if (p == S) {
			if (isS(N, p + 1)) {
				ans = min(ans, p);
			}
		}

		if (D%p== 0) {


			LL b = (N - S) / p + 1;

			LL q = (N - p * b);

			if (p + q == S && q<b) {
				ans = min(ans, b);
			}

		}
	}

	if (ans == INF2) {
		cout << "-1" << endl;
		return 0;
	}

	cout << ans << endl;
	return 0;
}

