bool check_this_b(ll b) {
	ll sum = 0;
	ll nn = n;
	while (nn > 0) {
		sum += nn % b;
		nn /= b;
	}
	return sum == s;
}

void solve(int test) {
	scan(n, s);
	ll diff = n - s;
	if(diff < 0) {
		print(-1);
		return;
	}
	ll ans = 1e18;
	for (ll i = 1; i*i <= diff; ++i) {
		if (diff % i == 0) {
			if (check_this_b(i + 1)) {
				ans = min(ans, i + 1);
			}
			if (check_this_b(diff / i + 1)) {
				ans = min(ans, diff / i + 1);
			}
		}
	}
	if (check_this_b(diff + 1)) {
		ans = min(ans, diff + 1);
	}
	print(ans == 1e18 ? -1 : ans);
}

