    ll ans = longinf;

    if (N == S){
        cout << N + 1 << endl;;
        return 0;
    }

    ll p;
    for (ll b = 2; b * b <= N; b++){
        if(func(b, N) == S){
                cout << b << endl;
                return 0;
        }
        p = b;
    }

    for(ll p = 1; p * p < N; p++){
        if(p > S) break;
        if((N - S + p) % p==0){
            ll b = (N - S + p) / p;
            if(b > S - p){
                chmin(ans ,b);
            }
        }
    }

    cout << (ans == longinf ? -1 : ans) << endl;

    return 0;
}

