//最大公約数GCD,最小公倍数LCM
// LCMを使うときはGCDをセットで
//検証済み
long long GCD(long long a, long long b) {
	if(a < b) swap(a, b);
	long long d = a % b;
	if(d == 0) {
		return b;
	}
	return GCD(b, d);
}
long long LCM(long long a, long long b) { return (a / GCD(a, b)) * b; }

//素数判定
//素数ならばtrue、素数以外の整数にはfalse
//負数は全てfalse
//検証済み
bool prime(long long N) {
	if(N == 1) {
		return false;
	}
	if(N < 0) return false;
	long long p = sqrt(N);
	for(long long i = 2; i <= p; i++) {
		if(N % i == 0) {
			return false;
		}
	}
	return true;
}

