  if (n < b) return n;
  return n % b + f(b, n / b);
}

void solve(istream& in, ostream& out) {
  auto n = next<i64>(in);
  auto s = next<i64>(in);
  FORA(b, 2, 1000001) {
    if (f(b, n) == s) {
      out << b << "\n";
