  auto x = n - s;
  i64 res = (i64)1e18;
    if (s == n) {
    res = s + 1;
  }
  for (i64 d = 1; d * d <= x; ++d) {
    if (x % d == 0) {

      auto b = x / d + 1;
      if (f(b, n) == s) {
        res = min(res, b);
      }

      b = d + 1;
      if (f(b, n) == s) {
        res = min(res, b);
      }
    }
  }
  if (res >= 1e18) {
    out << -1 << "\n";
  } else {
    out << res << "\n";
  }
  // n = pb + q
  // p + q = s
  // n - s = p(b - 1)
}

