int judge(LL tmp,LL n,LL s)
{
	LL sum=0;
	while(n)
	{
		sum+=n%tmp;
		if(sum>s)return 0;
		n/=tmp;
	}
	if(sum==s)return 1;
	return 0;
}
int  main()
{
	io;
	LL n,s;
	while(cin>>n>>s)
	{
		if(n==s)
		{
			cout<<n+1<<endl;
			continue;
		}
		else if(s>n)
		{
			cout<<-1<<endl;
			continue;
		}
		int f=0;
		LL up=sqrt(n);
		for(LL i=2;i<=up;i++)
		{
			if(judge(i,n,s))
			{
				f=i;
				break;
			}
		}
		if(f)
		{
			cout<<f<<endl;
			continue;
		}
		else
		{
			LL up=sqrt(n-s);
			for(LL i=3;i<=up;i++)
			{

				if((n-s)%i!=0)continue;
				LL tmp=i+1;
				if(judge(tmp,n,s)&&((n-s)/i)==(n/tmp))
				{

					f=tmp;
					break;
