}

ll solve2(ll n, ll s)
{
    S ll border[2000005];
    srep (i, 1, 2000005) border[i] = n / i;

    rrep (digit2, 2000005) {
        if (!digit2) break;
        ll left = border[digit2+1] + 1LL;
        ll right = border[digit2];
        if (!right) continue;
        ll now = (left + right) / 2LL;
        for ( ; left <= right; now = (left + right) / 2LL) {
            ll digit1 = n % now;
            ll sum = digit2 + digit1;
            if (digit2 <= 10) debug_printf("---- sum=%lld digit2=%lld digit1=%lld\n", sum, digit2, digit1);
            if (sum == s) {
                return now;
            }
            if (sum < s) {
                right = now - 1LL;
            }
            if (sum > s) {
                left = now + 1LL;
            }
        }
    }

    return 0LL;
}

