{
    ios_base::sync_with_stdio(false);

    long long N, S;
    // ifstream cin("code.in");
    cin >> N >> S;
    long long sol = solve(N, S);
    if (sol < 0) {
        cout << "-1\n";
        return 0;
    }
    long long x = N % sol;
    long long y = N / sol;
    assert(x + y == S);
    cout << sol << '\n';
    return 0;
}

