const int M=1e6;

int sum(int n,int b)
{
    int res=0;
    while (n){
        res+=n%b;
        n/=b;
    }
    return res;
}

int get_big(int n,int s)
{
    int res=inf;
    for (int val=1;val<=min({n,s,M});val++){
        int rest=s-val;
        if ((n-rest)%val==0){
            int b=(n-rest)/val;
            if (n/b==val){
                if (b>=2){
                    res=min(res,b);
                }
            }
        }
    }
    /// if val==0
    if (n==s){
        res=min(res,2ll);
    }
    return (res==inf?-1:res);
}

