void solve(long long n, long long s){
	ll res = -1;
	if (n == s) res = n+1;
	for (ll b = 2; b*b <= n; b++) {
		ll p = n, r = 0, now = 0;
		while (p != 0) {
			r = p%b;
			p /= b;
			now += r;
		}
		if (now == s && res == -1) res = b;
	}
	for (ll p = 1; p*p <= n; p++) {
		ll b = (n-s+p)/p;
		// if ((n-s+p)%p == 0) cout << p << " " << b << endl;
		if ((n-s+p)%p == 0 && b > 0 && n%b+p == s && res == -1) res = b;
	}
	cout << res << endl;
}

