using ll = long long;

const ll INF = 2e15;

ll func(ll b, ll n) {
	if (b == 1) {
		return -1;
	}
	ll res = 0;
	while (n) {
		res += n % b;
		n /= b;
	}
	return res;
}

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);

	ll N, S; cin >> N >> S;
	ll V = ll(sqrt(N));

	ll ans = INF;

	auto check = [&](ll b) -> void {
		if (func(b, N) == S) {
			ans = min(ans, b);
		}
	};

	for (ll b = 2; b <= V; b++) {
		check(b);
	}

	check(N + 1);

	ll D = N-S;
	if (D > 0) {
		for (ll x = 1; x <= V; x++) {
			if (D % x) continue;
			check(x + 1);
			check(D / x + 1);
		}
	}

	if (ans == INF) ans = -1;
	cout << ans << '\n';

	return 0;
}

