using ll = long long;
ll N,S; 


ll cal(ll N, ll b)
{
	ll ans = 0;
	while(N >= b){
		ans += N%b;
		N/=b;
	}
	return ans + N;
}

void solve()
{
	long long ans = -1;
	if(S==1) ans = N;
	else{
    	if(S < N){
    		for(int b=2;b<=sqrt(N);++b){
    			if(S==cal(N, b)){
    				ans = b;
    				break;
    			}
    		}
    		if(ans==-1){
    			ll T = N-S;
    			ll can = 1e12;
    			for(ll x=2;x*x<=T;++x)if(T%x==0){
    				if(S==cal(N, x)){
    					can = min(can,x);
    				}
    				if(S==cal(N, T/x)){
    					can = min(can, T/x);
    				}
    			}
    			if(can < 1e12) ans = can;
    		}
    	}
	}
	cout << ans << endl;
}

int main()
{
	cin >> N >> S;
	solve();
	return 0;
}

