long long n , s;
int main(){
    cin >> n >> s;
    for(int base = 2 ; base < 1e6 ; ++base){
        long long num = n;
        long long sum = 0;
        while(num){
            sum += num % base;
            num /= base;
        }
        if(sum == s){
            printf("%d\n" , base);
            return 0;
        }
    }
    long long ans = 1e15 + 15;
    if(n == s){
        ans = s + 1;
    }
    for(int a = 1 ; a < 1e6 && a <= s ; ++a){
        long long b = s - a;
        long long base = (n - b) / a;
        if(base < 2){
            continue;
        }
        if(a * base + b != n){
            continue;
        }
        if(b >= base){
            continue;
        }
        ans = min(ans , base);
    }
    if(ans >= 1e15){
        ans = -1;
    }
    printf("%lld\n" , ans);
}

