#include <cstdio>
typedef long long LL;
LL F(LL N, LL b)
{
	if(N < b) return N;
	else return N%b + F(N/b, b);
}
bool check(LL N, LL S, LL b)
{
	if(b <= 1) return 0;
	return F(N, b) == S;
}
LL solve(LL N, LL S)
{
	LL i, b;
	for(i=2; i*i<=N; ++i)
		if(check(N, S, i))
			return i;
	for(; i>0; --i)
	{
		b = (N-S)/i + 1;
		if(check(N, S, b))
			return b;
	}
	return -1;
}
int main()
{
	LL N, S;
	scanf("%lld%lld", &N, &S);
	printf("%lld\n", solve(N, S));
}

