#define MAX 100000000000LL
#define MAXSQRT 340000LL

ll convertToBase(ll N, ll b) {
    ll ans = 0;
    while (N > 0 && ans <= MAX) {
        ans += N % b;
        N /= b;
    }
    return ans;
}

int main(int,char**) {
    ios_base::sync_with_stdio(false);

    rl(N); rl(S);
    if (S > N) {
        cout << -1 << endl;
    } else if (S == N) {
        cout << N + 1 << endl;
    } else {
        for (int i = 2; i < MAXSQRT; i++) {
            if (convertToBase(N, i) == S) {
                cout << i << endl;
                return 0;
            }
        }

        ll ans = MAX;

        for (int q = MAXSQRT; q >= 1; q--) {
            ll rem = S - q;
            if (0 <= rem && rem <= N) {
                if ((N-rem)%q == 0) {
                    ll F = (N-rem)/q;
                    if (F>1 && convertToBase(N,F) == S) {
                        ans = min(ans, F);
                    }
                }
            }
        }

        if (ans != MAX) cout << ans << endl;
        else cout << -1 << endl;

    }


}

