vector <ll> vec;
ll n, s;
bool cmp(ll x, ll y)
{
	return x > y;
}
bool check(ll x)
{
	ll a0, a1;
	a1 = n / x;
	a0 = n % x;
	if (a1 < x && x >= 2 && a0 + a1 == s)
		return true;
	return false;
}
int main()
{
	cin >> n >> s;
	if (n < s)
	{
		cout << -1 << endl;
		return 0;
	}
	if (n == s)
	{
		cout << n + 1 << endl;
		return 0;
	}
	ll i;
	for (i = 2; i * i <= n; i++)
	{
		ll x = n;
		ll sum = 0;
		while (x > i)
		{
			sum += x % i;
			x /= i;
		}
		sum += x;
		if (sum == s)
		{
			cout << i << endl;
			return 0;
		}
	}
	ll y = n - s;
	for (ll j = 1; j * j <= y; j++)
		if (y % j == 0)
			vec.push_back(j), vec.push_back(y / j);
	sort(vec.begin(), vec.end(), cmp);
	for (ll j = 0; j < vec.size(); j++)
	{ 
