			out << i << std::endl;
			return 0;
		}
	}
	ans = n + 1;
	for (LL i = 1; i <= sqrt(n); ++i)
	{
		LL res = (n - s) / i + 1;
		if (res > 1 && f(res) == true)
		{
			ans = std::min(ans, res);
		}
	}

	if (ans == n + 1)
	{
		out << -1 << std::endl;
	}
	else
	{
		out << ans << std::endl;
	}
	return 0;
}

