        for (ll b = 2; b * b < n; b++)
        {
            if (digit_sum(n, b) == s)
            {
                ans = min(ans, b);
            }
        }

        for (ll p = 1; p * p < n; p++)
        {
            const ll b = (n - s) / p + 1;
