ll func(ll n, ll base) {
    ll ans = 0;
    while (n) {
        if (n < base) {
            ans += n;
            break;
        } else {
            ans += (n % base);
            n /= base;
        }
    }
    return ans;
}

int main(void)
{
    cin.sync_with_stdio(false);
    ll N;
    cin >> N;
    ll S;
    cin >> S;

    FOR(base, 2, sqrt(N)+5LL) {
        ll tmp = func(N, base);
        if (tmp == S) {
            cout << base << endl;
            return 0;
        }
    }
    if (S == N) {
        cout << S + 1 << endl;
    }

    for (ll a = sqrt(N) + 1.1; a > 0; --a) {
        auto e = N / a;
        auto s = N / (a + 1) + 1;
        // cout << "a, [s, e] = " << a << "," << s << "," << e << endl;
        if (s == e) {
            ll tmp = func(N, s);
            if (tmp == S) {
                cout << s << endl;
                return 0;
            }
        } else {
            ll tmp1 = func(N, s);
            ll tmp2 = func(N, s+1);
            ll unit = abs(tmp1 - tmp2);
            if (abs(S - tmp1) % unit == 0) {
                ll idx = s + (tmp1 - S) / unit;
                if (idx <= e) {
                    cout << idx << endl;
                    return 0;
                }
            }
        }
    }
    cout << -1 << endl;


    return 0;
}

