ll solve(ll n, ll s) {
    if (s == n) return n + 1;
    if (s  > n) return -1;
    // search lower half
    int sqrt_n = min<ll>(n, sqrt(n) + 3);
    REP3 (b, 2, sqrt_n) if (f(b, n) == s) return b;
    // search upper half
    REP3R (a, 1, sqrt_n) {
        ll b = (n - s) / a + 1;
        if (f(b, n) == s) return b;
    }
    return -1;
}

