    return f(b, n / b) + n % b;
}
int main()
{
    cin >> N;
    cin >> S;
    if (S == N)
    {
        cout << N + 1 << endl;
        return 0;
    }
    bool ok = false;
    ll b = 2;
    ll result = LL_INF;
    while (true)
    {

        if (f(b, N) == S)
        {
            ok = true;
            result = min(result, b);
            break;
        }
        b++;
        if (b * b > N)
        {
            break;
        }
    }

    ll sn = sqrt(N) + 10;
    while (true)
    {
        if (sn == 0)
        {
            break;
        }
        ll b = (N - S) / sn + 1;
        if (b <= 1)
        {
            sn--;
            continue;
        }
        if (f(b, N) == S)
        {
            ok = true;
            result = min(result, b);
            break;
        }
        sn--;
        if (sn == 0)
        {
            break;
        }
    }

    if (not ok)
    {
        cout << -1 << endl;
        return 0;
    }
    cout << result << endl;

    return 0;
}

