#define REP(i, n) for (int i = 0; (i) < int(n); ++ (i))
#define REP3(i, m, n) for (int i = (m); (i) < int(n); ++ (i))
using ll = long long;
using namespace std;

template <typename UnaryPredicate>
ll binsearch(ll l, ll r, UnaryPredicate p) {
    assert (l <= r);
    -- l;
    while (r - l > 1) {
        ll m = l + (r - l) / 2;  // avoid overflow
        (p(m) ? r : l) = m;
    }
    return r;
}

ll solve(ll n, ll s) {
    // prepare
    auto f = [&](ll b) {
        ll x = n;
        ll acc = 0;
        for (; x; x /= b) acc += x % b;
        return acc;
    };
    // search lower half
    int sqrt_n = min(n, 1000000ll);
    REP3 (b, 2, sqrt_n) if (f(b) == s) return b;
    if (sqrt_n == n) return -1;
    // search upper half
    ll l = sqrt_n + 1;
    while (f(l - 1) >= f(l)) ++ l;
    ll r = l + 1;
    while (f(r - 1) >= f(r)) ++ r;
    REP3 (b, sqrt_n, r) if (f(b) == s) return b;
    while (l < n) {
        ll dist = r - l;
        ll t = f(l + dist);
        ll nr = binsearch(r + dist + 1, r + 1.5 * dist, [&](ll b) {
            return f(b) >= t;
        });
        ll b = binsearch(r, nr, [&](ll b) {
            return f(b) <= s;
        });
        if (f(b) == s) return b;
        l = r;
        r = nr;
    }
    return -1;
}

int main() {
    ll n, s; scanf("%lld%lld", &n, &s);
    ll result = solve(n, s);
    printf("%lld\n", result);
    return 0;
}

