ll bns(ll lhs, ll rhs) {
    if (lhs == rhs) return lhs;
    ll mid = (lhs+rhs+1) / 2;
    if (f(mid, n) < s) return bns(lhs, mid-1);
    else return bns(mid, rhs);
}

