long long cal(long long n,long long i){
  long long ans=0;
  while(n>0){
    if(n<i){
      ans+=n;
      break;
    }
    ans+=n%i;
    n/=i;
  }
  return ans;
}

int main(){
  long long n,s;
  cin>>n>>s;
  if(n==s){
    cout<<n+1<<endl;
    return 0;
  }
  if(s==1){
    cout<<n<<endl;
    return 0;
  }

  for(int i=2;i*i<=n;i++){
    if(cal(n,i)==s){
      cout<<i<<endl;
      return 0;
    }
  }

  long long ans=1e18;
  for(int i=1;i*i<=n;i++){
    if(n-s>=0&&(n-s)%i==0){
      long long b=((n-s)/i)+1;
      if(cal(n,b)==s){
        ans=min(ans,b);
      }
    }
  }
  if(ans!=1e18)cout<<ans<<endl;
  else cout<<-1<<endl;
}

