    if(b>n) return n;
    return f(b, n/b)+n%b;
}
vector <pair <ll, int> > v;
void fact(ll x){
    ll i=2;
    while(i*i<=x){
        if(x%i==0) v.pb(mp(i, 0));
        while(x%i==0){
            x/=i;
            v.back().second++;
        }
        i++;
    }
    if(x>1) v.pb(mp(x, 1));
}
ll ans=1LL<<50;
void check(ll x){
    if(f(x+1, n)==s) ans=min(ans, x+1);
}
void backtrack(ll x, int u, int d){
    if(u==v.size()) check(x);
    else{
        backtrack(x, u+1, 0);
        if(d<v[u].second) backtrack(x*v[u].first, u, d+1);
    }
}
