    while(i*i<=n){
        if(f(i, n)==s){
            write(i);
            return 0;
        }
        i++;
    }
    /** if now there is an i then:
        n=x*i+y
        x+y=s
        => x*i+s-x=n
        =>x*(i-1)=n-s.
        =>i-1|n-s.
        with n=s, x=0 or i=1(fail). to have x=0, i>n
    */
    if(n<s){
        write(-1);
        return 0;
    }
    if(n==s){
        write(n+1);
        return 0;
    }
    fact(n-s);
    backtrack(1LL, 0, 0);
    if(ans==1LL<<50) write(-1);
    else write(ans);
}

