            continue;
        }
        if (f(b, N) == S)
        {
            ok = true;
            result = min(result, b);
            break;
        }
        sn--;
        if (sn < 0)
        {
            break;
        }
    }

    if (not ok)
    {
        cout << -1 << endl;
        return 0;
    }
    cout << result << endl;

    return 0;
}

