    int ans = inf;
    for (int d = 1; d * d <= n - s; d++) {
        if ((n - s) % d == 0) {
            int b = d + 1;
            if (f(b, n) == s) {
                ans = min(ans, b);
            }
            b = (n - s) / d + 1;
            if (f(b, n) == s) {
                ans = min(ans, b);
            }
        }
    }

    cout << (ans == inf ? -1 : ans) << endl;
}

