vector<int> to_s(long long n, int base) {
	vector<int> s;
	do { s.push_back(n % base) ; n /= base; } while (n);
	reverse(s.begin(), s.end());
	return s;
}


int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	long long ans = -1;
	long long n, s;
