		return 0;
	}

	for (long long b = 2; b*b <= n; b++) {
		vector<int> str(to_s(n,b));
		long long sum = 0;
		for (int c : str)sum += c;
		if (sum==s) {
			ans = b;
			break;
		}
	}
	if (ans == -1) {
		long long sq = ceil(sqrt(n)) + 1e-10;
		for (long long p = sq-1; p > 0 ;p--) {
			long long q = s - p;
			if ((n - q) % p || q<0)continue;
			long long b = (n - q) / p;
			if (q >= b || p >= b)continue;
			if(b*p+q==n){
				ans = b;
				break;
			}
		}
	}

	cout << ans << endl;

	return 0;
}

