        if (check(n, s, i)) ans = min(ans, i);
    }
    for (long long i = 1; i * i <= (n - s); i++) {
        if ((n - s) % i == 0) {
            long long b = (n - s) / i + 1;
            if (check(n, s, b)) ans = min(ans, b);
        }
    }
    if (ans == 1000000000000) printf("-1\n");
    else printf("%lld\n", ans);
    return 0;
}

