	}

	LL D = N - S;
	for (LL p = 2; p*p <= N; p++) {

		if (D%p== 0) {
			LL b = (N - S) / p + 1;

			LL q = (N - p * b);

			if (p + q == S) {
				ans = min(ans, b);
			}

		}
	}

	if (ans == INF2) {
