using namespace std;

typedef long long ll;

vector<ll> yakusu;

void calc_yakusu(ll A) {

	if (A == 1) {
		yakusu.push_back(1);
		return;
	}
	ll waru = 1;
	while (waru * waru <= A) {
		if (A % waru == 0) {
			yakusu.push_back(waru);
			if(waru * waru != A)
				yakusu.push_back(A / waru);
		}
		waru++;
	}

}

int main() {
	ll n, s;
	cin >> n >> s;
	if (s == 1) {
		cout << n << endl;
		return 0;
	}
	if (s > n) {
		cout << -1 << endl;
		return 0;
	}
	for (ll shinsu = 2; shinsu * shinsu <= n; shinsu++) {
		ll cpyn = n;
		ll tmp = 0;
		while (cpyn > 0)tmp += (cpyn % shinsu), cpyn /= shinsu;
		if (tmp == s) {
			cout << shinsu << endl;
			return 0;
		}
	}

	//n == p * shinsu + q, p + q == s
	//->q == s - p
	//n == p * shinsu + s - p
	//n - s == p * (shinsu - 1) (shinsu > sqrt(n), p < shinsu)
	calc_yakusu(n - s);
	sort(yakusu.begin(), yakusu.end());

	for (int i = 0; i < yakusu.size(); i++) {
		ll cur = yakusu[i];
		ll counter = (n - s) / yakusu[i];
		if (cur + 1 > (ll)sqrt(n) && cur + 1 > counter && cur + 1 > s - counter) {
			cout << cur + 1 << endl;
			return 0;
		}
	}
	cout << -1 << endl;
	return 0;
}

