半分全列挙です。
まずは全部A引いておけば、合計0を探すのでよいです。
前半と後半、それぞれでありえる合計値を列挙し、前半を全探索して、後半を equal_range です。

間に合わないじゃないですか！！
値の範囲が狭いので重複度付き集合で対応です。
負の値もあるので、下駄を履かせます。
*/

int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int n; std::cin >> n;
  int l = n / 2;
  int A; std::cin>>A;
  std::vector<int> a(n); std::cin>>a;
  for (int & x : a) x -= A;
  debug(a);

  int geta = 0;
  int max = 0;
  for (int x : a) {
    if (x < 0) geta += -x;
    else max += x;
  }
  debug(geta,max);

  auto make_sums = [&] (std::vector<int> const& a) {
    int n = a.size();
    int N = 1 << n;
    std::vector<int> now(n,0);
    std::vector<lint> ans(geta+max+1,0);
    lint sum = 0;
    rep(bs,0,N) {
      if (0 < bs) {
        int i = __builtin_ctz(bs);
        now.at(i) ^= 1;
        sum += (now.at(i) ? +1 : -1) * a.at(i);
      }
      ans.at(geta+sum)++;
    }
    return ans;
  };
  auto former = make_sums(std::vector<int>(a.begin(), a.begin() + l));
  auto latter = make_sums(std::vector<int>(a.begin() + l, a.end()));
  debug(former,latter);

  lint ans = 0;
  int d = std::min(geta,max);
  rep(i,-d,d+1) {
