int n, s;
bool check(int xb)
{
	if(xb < 2ll) return false;
	int res = 0ll, tmp = n;
	while(tmp >= xb)	{
		res += tmp % xb;
		tmp /= xb;
	}
	res += tmp;
	return (res == s);
}
