#define REP(i, n) for(int i = 0; i < (int)(n); ++i)
typedef long long ll;

ll calc(ll b, ll n) {
  if (n < b) return n;
  else return calc(b, n/b) + n%b;
}

int main(void) {
  ll n;
  ll s;
  scanf("%lld%lld", &n, &s);
  for(ll b = 2; b*b <= n; ++b) {
    ll v = calc(b, n);
    if(v == s) {
      printf("%lld\n", b);
      return 0;
    }
  }

  ll res = n*2;
  for(ll d = 1; d*d <= n; ++d) {
    ll bg = n / d;
    ll ed = n / (d+1);
    ll m = n % bg + d;
    if (s-m >= 0 && (s-m)%d == 0) {
      ll x = bg - (s-m) / d;
      if(ed < x && x <= bg && x < res) {
