int64_t f(int64_t b, int64_t n) {
    if(n < b) {
        return n;
    } else {
        return f(b, n/b) + n%b;
    }
}

int main(void) {
    int64_t n, s;
    cin >> n >> s;

    int64_t ans = numeric_limits<int64_t>::max();
    for(int64_t b=2; b*b<=n; b++) {
        if(f(b, n) == s) {
            ans = min(ans, b);
            // cout << b << endl;
            // return 0;
        }
    }

    if(n == s) {
        ans = min(ans, n+1);
        // cout << n+1 << endl;
        // return 0;
    }

    for(int64_t i=1; i*i<=n; i++) {
        int64_t j = s - i;
        if((n-j) % i == 0) {
            int64_t b = (n-j) / i;
            if(b < 2) continue;
            if(i >= b || j >= b || j < 0) continue;
            // cerr << i << ' ' << j << endl;
            ans = min(ans, b);
            // cout << (n-j) / i << endl;
