{
    ll ans = 0;
    while (i > 0)
    {
        ans += i % b;
        i /= b;
    }
    return ans;
}

int main()
{
    ll n, s;
    cin >> n >> s;

    ll lim = sqrt(n);

    ll ans = n + 1;

    for (ll b = 2; b < lim; b++)
    {
        if (digit_sum(n, b) == s)
        {
            ans = min(ans, b);
        }
    }

    if (lim * lim == s) lim--;

    for (ll p = 1; p < lim; p++)
    {
        const ll b = n / p;
        const ll q = n - b * p;
        if (p + q == s) 
