int pn = 0;
int primes[16000000];
int eulnums[16000000];

void eulerprime(int n) {
    fill(eulnums, eulnums + n + 1, 0);
    for (int i = 2; i <= n; i++) {
        if (eulnums[i] == 0) {
            eulnums[i] = i;
            primes[pn] = i;
            pn++;
        }

        for (int j = 0; i * primes[j] <= n; j++) {
            eulnums[i * primes[j]] = primes[j];
            if (i % primes[j] == 0) {
                break;
            }
        }
    }
}

int primepow[16000000];
vector<ll> ansnum;
ll diff;
ll N, S;

ll digsum(ll b, ll n) {
    if (n < b) {
        return n;
    } else {
        return digsum(b, n / b) + n % b;
    }
}

void solve(ll now, ll n) {
    if (n == -1) {
        //cout << "a" << endl;
        solve(now, 0);
        solve(now * diff, 0);
    } else {
        if (n < pn - 1) {
            ll next = n + 1;
            for (int i = n + 1; i < pn - 1; i++) {
                if (primepow[i] != 0) {
                    break;
                } else {
                    next++;
                }
            }
            ll tmp = now;
            for (int i = 0; i <= primepow[n]; i++) {
                //cout << n << endl;
                solve(tmp, next);
                tmp *= primes[n];
            }
        } else {
            ll tmp = now;
            for (int i = 0; i <= primepow[n]; i++) {
                if (tmp != 1 && digsum(tmp + 1, N) == S) {
                    ansnum.push_back(tmp + 1);
                }
                tmp *= primes[n];
                //cout << tmp << endl;
            }
        }
    }
}

int main() {
