    cin >> S;
    if (N < S) {
        cout << -1 << endl;
        return 0;
    } else if (N == S) {
        cout << N + 1 << endl;
        return 0;
    }
    diff = N - S;
    eulerprime(1e6);
    //cout << pn << endl;
    fill(primepow, primepow + pn + 10, 0);
    for (int i = 0; i < pn; i++) {
        while (diff % primes[i] == 0) {
            primepow[i]++;
            diff /= primes[i];
        }
    }
