        return N + 1;
    }
    while (true)
    {
        if (b * b > N)
        {
            break;
        }
        b++;
        if (f(b, N) == S)
        {
            return b;
        }
    }
    for (ll p = 1; p * p <= N; p++)
    {
        ll b = 1 + (N - S) / p;
        if (f(b, N) == S)
        {
            return b;
        }
    }
    return -1;
}
int main()
{
    cin >> N;
    cin >> S;
    ll res = solve();
    cout << res << endl;

    return 0;
}

