std::int64_t f(std::int64_t b, std::int64_t n)
{
	return n < b ? n : (n%b) + f(b, n / b);
}

void Main()
{
	std::int64_t n, s;
	std::cin >> n >> s;
	std::int64_t b = 2;
	for (; b*b < n; ++b)
	{
		if (f(b, n) == s)
		{
			std::cout << b << std::endl;
			return;
		}
	}
	for (auto y = (n - s) / (b - 1); y >= 1; --y)
	{
		auto x = s - y;
		if (x < 0)
		{
			continue;
		}
		if ((n - x) % y == 0)
		{
			auto b = (n - x) / y;
			if (x < b&&y < b)
			{
				std::cout << (n - x) / y << std::endl;
				return;
			}
		}
	}
	if (n != s)
	{
		std::cout << -1 << std::endl;
	}
	else
	{
		std::cout << s + 1 << std::endl;
	}
}

