long long int f(int b, int nn){
    //cout << b << " " << nn;
    if(nn < b){
        return nn;
    }else{
        long long int ret = f(b, nn / b) + nn % b;
        return ret;
    }
}

int main(){
    cin >> n >> s;
    if(s > (n + 1) / 2){
        cout << -1 << endl;
    }else{
        for(int i = 2; i <= sqrt(n); i++){
            long long int ff = f(i, n);
            if(ff == s){
                cout << i << endl;
                return 0;
            }
        }
        for(int i = min((long long int)sqrt(n), s); i > 0; --i){
            long long int A = (n - s + i) / i;
            long long int ff = f(A, n);
            if(ff = s){
                cout << A << endl;
                return 0;
            }
        }
        cout << n - s + 1 << endl;
    }
    return 0;
}

