void check(int b, int n, int s)
{
    if (b <= 1)
        return;

    int cnt = 0;
    while (n)
    {
        cnt += n % b;
        n /= b;
    }

    if (cnt == s)
        ans = min(ans, b);
}


void smain()
{
    int n, s;
    cin >> n >> s;

    check(n, n, s);
    check(n + 1, n, s);
    check(n - 1, n, s);

    for (int i = 2; i < B; ++i)
        check(i, n, s);

    if (n > s)
    {
        int v = n - s;
        for (int d = 1; d * d <= v; ++d)
        {
            if (v % d == 0)
            {
                check(d + 1, n, s);
                check(n / d + 1, n, s);
            }
        }
    }

    if (ans == oo)
        cout << "-1\n";
    else
        cout << ans;
}

