LL n,s;


bool chk(LL b){
	LL res = 0;
	LL x = n;
	while(x){
		res += x%b;
		x /= b;
	}
	return (s==res);
}

int main(){

	cin>>n>>s;
	if(s==1){
		cout<<n<<endl;
		return 0;
	}

	LL ans = 1e18;
	for(LL b=2;b*b<=n;b++){
		if(chk(b)){
			ans = b;
			break;
		}
	}

	/*
	bx + y = n
	x + y = s
	(b-1)*x = n-s
	*/

	if(ans==1e18 && n-s<=0){
		cout<<"-1"<<endl;
		return 0;
	}

	LL b,y;
	for(LL x=1;x*x<=n-s;x++){
