int main() {
	i64 n, s;
	std::cin >> n >> s;

	const i64 sqrt = std::max<i64>(2, std::sqrt(n));
	i64 ans = INF;

	for (i64 b = 2; b <= sqrt; b++) {
		if (digits_sum(n, b) == s) chmin(ans, b);
	}

	for (i64 i = sqrt; i > 1; i--) {
		i64 ng = std::max<i64>(2, n / i);
		i64 ok = std::max<i64>(2, n / (i - 1));
		while (std::abs(ok - ng) > 1) {
			const i64 b = (ok + ng) >> 1;
			if (digits_sum(n, b) > s) ng = b;
			else ok = b;
		}
		if (digits_sum(n, ok) == s) chmin(ans, ok);
	}

	if (ans == INF) ans = -1;
	std::cout << ans << '\n';

	return 0;
}

