bool check(long long b, long long n, long long s) {
    long long res = 0;
    for(; n; n /= b){
		res += n % b;
	}
    return res == s;
}

void solve() {
    long long n, s;
    cin >> n >> s;

    for (long long b = 2; b * b <= n; b++) {
        if (check(b, n, s)) {
            cout << b;
            return;
        }
    }

    if (n < s) {
        cout << -1;
        return;
    }
    else if (n == s) {
        cout << n + 1;
        return;
    }
    long long ans = INF;
    long long nv = n - s;
    for (long long factor1 = 1; factor1 * factor1 <= nv; factor1++) {
        if (nv % factor1 != 0)
            continue;
        long long factor2 = nv / factor1;
        if (check(factor1 + 1, n, s))
            ans = min(ans, factor1 + 1);
        if (check(factor2 + 1, n, s))
            ans = min(ans, factor2 + 1);
    }
    if (ans == INF)
        cout << -1;
    else
        cout << ans;
}

