ll factor[100], facCnt;
void getFactors(ll x) {
  facCnt = 0;
  for (ll i = 1; i * i <= x; i++) {
    if (x % i == 0) {
      factor[facCnt++] = i;
      if (x / i != i) { factor[facCnt++] = x / i; }
    }
  }
  sort(factor, factor + facCnt);
}

int main() {
  while (~scanf("%lld%lld", &n, &s)) {
    if (s == 1) { printf("%lld\n", n); continue; }
