    ll ans = -1;
    for (ll b = 2; b * b <= n && ans == -1; b++) {
      if (f(b, n) == s) { ans = b; }
    }
    getFactors(n - s);
    for (int i = 0; i < facCnt && ans == -1; i++) {
      if (f(factor[i] + 1, n) == s) { ans = factor[i] + 1; }
    }
    printf("%lld\n", ans);
  }
}

