#include <bits/stdc++.h>
#define REP(i, n) for (int i = 0; (i) < int(n); ++ (i))
#define REP3(i, m, n) for (int i = (m); (i) < int(n); ++ (i))
using ll = long long;
using namespace std;

template <typename UnaryPredicate>
ll binsearch(ll l, ll r, UnaryPredicate p) {
    assert (l <= r);
    -- l;
    while (r - l > 1) {
        ll m = l + (r - l) / 2;  // avoid overflow
        (p(m) ? r : l) = m;
    }
    return r;
}

void solve(ll n, ll s) {
    // prepare
    auto f = [&](ll b) {
        ll x = n;
        ll acc = 0;
        for (; x; x /= b) acc += x % b;
        if (acc == s) throw b;
        return acc;
    };
    // search lower half
    int sqrt_n = min(n, 1000000ll);
    REP3 (b, 2, sqrt_n) f(b);
    if (sqrt_n == n) return;
    // search upper half
    ll l = sqrt_n + 1;
    while (f(l - 1) >= f(l)) ++ l;
    ll r = l + 1;
    while (f(r - 1) >= f(r)) ++ r;
    while (l < n) {
        ll dist = r - l;
        ll t = f(l + dist);
        ll nr = binsearch(r + dist + 1, r + 1.5 * dist, [&](ll b) {
            return f(b) >= t;
        });
        binsearch(r, nr, [&](ll b) {
            return f(b) <= s;
        });
        l = r;
        r = nr;
    }
}

int main() {
    ll n, s; scanf("%lld%lld", &n, &s);
    ll result = -1;
    try {
        solve(n, s);
    } catch (ll b) {
        result = b;
    }
    printf("%lld\n", result);
    return 0;
}

