using namespace std;

typedef long long ll;

ll f(ll b, ll n) {
    ll res = 0;
    while (n >= b) {
        res += n % b;
        n /= b;
    }
    return res + n;
}

ll solve(ll n, ll s) {
    if (n < s) return -1;
    if (n == s) return n + 1;
    for (ll b = 2; b * b <= n; b++) {
        if (f(b, n) == s) return b;
    }
    for (ll p = (ll)sqrt(n - 1); p > 0; p--) {
        if ((n - s) % p) continue;
        ll b = (n - s) / p + 1;
        if (f(b, n) == s) return b;
    }
    return -1;
}

int main() {
