vector<ll> Drops() {
  vector<ll> ret;
  ret.push_back(n);
  FOR(i, 2, 50000) {
    ll nn = n / i;
    if (nn < 1000) break;
    int korak = 0;
    while (nn > 4 && f(nn - 1) > f(nn) && korak++ < 10) --nn;
    --nn;
    while (f(nn + 1) < f(nn) && korak++ < 10) ++nn;
    if (nn == ret.back()) continue;
    ret.push_back(nn);
  }
  return ret;
}

