    cin.tie(0); cout.tie(0);
    int ans = inf;
    cin >> n >> s;
    if (n == s && n > 2) Ptest(n - 1);
    if (n < s) Ptest(-1);
    if (n == s + 1 && s > 2) Ptest(-1);
    if (n == s + 1 && s == 1) Ptest(-1);
    if (s == 1) ans = min(ans, n);
    if (s == 2) ans = min(ans, n - 1);
    ForE(i, 2, sqrt(n)){
        if (cal(i, n) == s) Ptest(i);
    }
    if (cal(n - s, n) == s){
        ans = min(ans, n - s);
    }
    ForE(i, 2, sqrt(n - s)){
        if ((n - s) % i == 0){
            if (i > sqrt(n) && cal(i, n) == s){
                ans = min(ans, i);
            }
            if ((n - s) / i > sqrt(n) && cal((n - s) / i, n) == s){
                ans = min(ans, (n - s) / i);
            }
        }
    }
    cout << (ans == inf ? -1 : ans);
}

