        if ((N-S)%p) continue;
        ll b = (N-S)/p - 1LL;
        if (b <= 1LL) continue;
        if (check(b)) {
            ans = min(ans, b);
        }
    }
    cout << (ans==INFL?-1:ans) << endl;
