bool check(long long b, long long n, long long s){
    if(b < 2) return -1;

    long long sum = 0;
    while(n != 0){
        sum += n % b;
        n /= b;
    }
    return sum == s;
}

int main(){
    long long n, s;
    cin >> n >> s;
    if(s == 1){
        cout << n << endl;
        return 0;
    }

    range(i,2,sqrt(n) + 1){
        if(check(i,n,s)){
            cout << i << endl;
            return 0;
        }
    }

    long long ans = LLONG_MAX;
    range(i,2,sqrt(n) + 1){
        if(check((n - s) / i + 1, n, s)){
            ans = min(ans, (n - s) / i + 1);
        }
    }
    cout << (ans == LLONG_MAX ? -1 : ans) << endl;
}

