typedef long long ll;
ll calc(ll b,ll n){
  ll res = 0;
  while(n>=b){
    res+=n%b;
    n=n/b;
  }
  return res+n;
}
int main(){
  ll n,s,i,j,k,ans=-1;
  cin>>n>>s;

  if(n>s){
    k=sqrt(n);
    for(i=2;i<k+100;i++){
      if(calc(i,n)==s){
	ans=i;
	break;
      }
    }
    if(!~ans){
      j=n-s+1;
      for(i=2;i*i<=j;i++){
	if(j%i==0){
	  if(calc(j/i,n)==s) ans=j/i;
	}
      }
    }

    if(!~ans){
      j=n-s+1;
      if(calc(j,n)==s) ans=j;
    }
  }
  if(n==s) ans=n+1;
  cout << ans << endl;
  return 0;
