long long gg (long long b, long long n)
{
	if (n < b) return n;
	else return gg (b, n / b) + n % b;
}

void work ()
{
	if (n < s)
	{
		sum = -1;
		return ;
	}
	if (n == s)
	{
		sum = n + 1;
		return ;
	}
	tmp = sqrt (n);
	ans = 0x3f3f3f3f3f3f3f3f;
	for (int i = 2; i <= tmp + 1; ++ i)
		if ( gg (i, n) == s )
		{
			sum = i;
			return ;
		}
  n -= s;
  for (int i = 1; i <= tmp; ++ i)
  	if( !(n % i) && n / i >= 1 && s - i >= 0 && s - i <= n / i && i < n / i )
  		ans = min (ans, n / i);
  if ( ans == 0x3f3f3f3f3f3f3f3f) sum = -1;
  else sum = ans;
}

