        ll j = s - i;
        ll b = (n - j) / i;

        if (b >= 2 && dig(b, n) == s && i >= 0 && j >= 0) {
            ans = min(ans, b);
        }
    }

    cout << ans << endl;

    return 0;
}

ll dig(ll b, ll n) {
    if (n >= b) {
        return dig(b, n / b) + n % b;
    }
    else {
        return n;
    }
}

