#include<bits/stdc++.h>
using namespace std;
#define ll long long
ll n,s;
bool check(ll base)
{
    ll tmp=n;
    ll ans=0;
    while(tmp)
    {
        ans+=tmp%base;
        tmp/=base;
    }
    return ans==s;
}
bool check(ll i,ll sum)
{
    ll a1=s-i;//x0
    ll a2=sum/i+1;//b
    if(a1>=0&&a1<a2&&i<a2)return 1;
    return 0;
}
int main()
{
    scanf("%lld%lld",&n,&s);
    /*第一种情况
    x0+x1*b^1+x2*b^2+...=n
    x0+x1+x2+...=s
    这个时候b^2<=n
    所以b<=根号n
    这个时候暴力枚举即可
    */
    ll Sn=(ll)(sqrt(n))+1;
    ll base;
    for(base=2;base<=Sn;base++)
    {
        if(check(base))
        {
            printf("%lld\n",base);
            return 0;
        }
    }
    /*
    第二种情况
    */
    if(n<=s)
    {
        if(n==s)
        {
            printf("%lld\n",n+1);
        }else
        {
            printf("-1\n");
        }
        return 0;
    }
    /*
    第三种情况暴力枚举
    x0+x1*b^1=n;
    x0+x1=s;
    这个时候联立二式子
    得到x1*(b-1)=n-s
    我们枚举x1，然后判断是否成立，包括题目条件以及进制常识
    */
    ll sum=n-s;
    ll up=sum/Sn+1;
    for(ll i=up;i>=1;i--)
    {
        if(!(sum%i)&&(check(i,sum)))
        {
            printf("%lld\n",sum/i+1);
            return 0;
        }
    }
    printf("-1\n");
    return 0;
}

