ll f(ll n, ll b) {
  ll res = 0;
  while (n > 0) {
    res += n % b;
    n /= b;
  }
  return res;
}

ll solve(ll n, ll s, ll p) {
  ll b = p;
  for (;b <= n; b *= p) {
    ll t = f(n, b);
    if (t == s) return b;
    if (t > s) break;
  }
  return -1;
}

ll solve2(ll n, ll s, ll hi, ll lo) {
  while (hi - lo > 1) {
    ll mid = (lo + hi) / 2;
    if (f(n, mid) <= s) {
      hi = mid;
    } else {
      lo = mid;
    }
  }
  if (hi > 1 && f(n, hi) == s)
    return hi;
  else
    return -1;
}

int main2() {
  ll n, s; cin >> n >> s;

  ll ans = -1;
  ll b = 0;
  for (b = 2; b * b <= n; b++) {
    ll here = solve(n, s, b);
    if (here != -1) {
      if (ans == -1 || ans > here) ans = here;
    }
  }
  if (n >= 2) {
    ll here = -1;
    if (f(n, n) == s) here = n;
    if (here != -1) {
      if (ans == -1 || ans > here) ans = here;
    }
  }
  for (ll i = 2; i <= b; i++) {
    ll here = solve2(n, s, max(1LL, n/(i-1)), max(1LL, n/i));
    if (here != -1) {
      if (ans == -1 || ans > here) ans = here;
    }
  }
  cout << ans << endl;
  return 0;
}

