long long CheckForB(long long n, long long s)
{
	long long max_sroot = 316228;

	if (n < s)
	{
		return -1;
	}

	if (n == s)
	{
		return n + 1;
	}

	long long b = 1;

	if (s < 2 * max_sroot) // it could be possible that there are 3 or more b-digits
	{
		while (++b < max_sroot)
		{
			if (f(b, n) == s)
			{
				return b;
			}
		}

	}

	// now we left with at most 2 digits
	// and the first is at most max_sroot
	long long firstDigit = std::min(s, max_sroot) + 1, secondDigit = s - firstDigit;

	while ((++secondDigit, --firstDigit) > 0)
	{
		b = (n - secondDigit) / firstDigit;
		if (b > 1 && f(b, n) == s)
		{
			return b;
		}
	}

	return -1;
}

int main(int, char**)
{
		long long n, s;

		std::cin >> n >> s;

		std::cout << CheckForB(n, s) << std::endl;

	return 0;
}

