unsigned long long int solve() {
    unsigned long long int sqn = floor(sqrt(n));
    unsigned long long int p = 1;
    b = 2;

    if(s>n) return -1;
    if(s==n) return n+1;

    while (b <= sqn) {
        if (f(b, n) == s) return b;
        b++;
    }
    b = (n - s) / p + 1;
    while (p <= sqn) {
        if (f(b, n) == s) return b;
        p++;
