template <class T>
std::vector<T> getDivisors(T n) {
    std::vector<T> ret;
    for (T i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            ret.push_back(i);
            if (i * i != n) ret.push_back(n / i);
        }
    }
    std::sort(ret.begin(), ret.end());
    return ret;
}

i64 f(i64 b, i64 n) {
    i64 ret = 0;
    while (n) {
        ret += n % b;
        n /= b;
    }
    return ret;
}

int main() {
    i64 n, s;
    std::cin >> n >> s;

    for (i64 i = 2; i * i <= n; i++) {
        if (f(i, n) == s) {
            std::cout << i << std::endl;
            return 0;
        }
    }

    auto ds = getDivisors(n - s);
    for (auto d : ds) {
        auto b = d + 1,
            d1 = (n - s) / d,
            d2 = s - d1;

        if (b > n / b && d1 < b && d2 < b && d2 >= 0) {
            std::cout << b << std::endl;
            return 0;
        }
    }

    if (n == s) {
        std::cout << n + 1 << std::endl;
    } else {
        std::cout << -1 << std::endl;
    }

    return 0;
}

