ll Digsum(ll a,ll b){
    ll ans=0;
    while(a){
        ans+=a%b;
        a/=b;
    }
    return ans;
}
signed main(){
    LL(n,s);
    if(n<s)return out(-1);
    if(n==s)return out(n+1);
    ll b=n/2+1;
    if(s>1+(n-b))return out(-1);
    ll rt=sqrt(n);
    rep(i,2,n/rt+1)if(Digsum(n,i)==s)return out(i);
    rrep(i,1,rt){
        ll b=n/(i+1)+1,c=n/i;
        if(Digsum(n,b)>=s&&s>=Digsum(n,c)&&(s-Digsum(n,c))%i==0)return out(c-(s-Digsum(n,c))/i);
    }
    if(s==1)return out(n);
    out(-1);
}

