using ll = long long;

const ll INF = static_cast<ll>(1e9) + 7ll;
const ll LINF = INF * INF;
const int MAXN = static_cast<int>(4e2) + 17;

ll n, s;

bool read() {
    if (!(cin >> n >> s))
        return false;

    return true;
}

ll f(ll b, ll n) {
    ll sum = 0;
    for (; n > 0; sum += n % b, n /= b) { }
    return sum;
}

void solve() {
    for (ll b = 2; b * b <= n; ++b)
        if (f(b, n) == s) {
            cout << b << endl;
            return ;
        }

    if (n - s > 0) {
        ll t = n - s;

        for (ll d = 1; d * d <= t; ++d)
            if (t % d == 0) {
                if (f(d + 1, n) == s) {
                    cout << d + 1 << endl;
                    return ;
                }

                if (f(t / d + 1, n) == s) {
                    cout << t / d + 1 << endl;
                    return ;
                }
            }
    }

    cout << -1 << endl;
}

int main() {
    cin.tie(nullptr);
    std::ios_base::sync_with_stdio(false);

    while (read())
        solve();

    return 0;
}

