LL divsum(LL n, LL i){
    if(n < i){
        return n;
    }else{
        return n%i + divsum(n/i,i);
    }
}

LL bin_search(LL a, LL b, LL n,LL s){
    LL ok = a;
    LL ng = b+1;
    while(abs(ok-ng) > 1){
        LL middle = (ok+ng)/2;
        LL x = divsum(n,middle);
        if(x == s){
            return middle;
        }else if(x < s){
            ng = middle;
        }else{
            ok = middle;
        }
    }
    return -1;
}

