		if(sum == s)
		ans = min(ans,i);
	}

	ll val = n-s;

	for(ll i=1;i*i<=val;i++)
	if(val%i == 0)
	{
		ll x = i, y = val/i;

		if(x <= s and (s-x) < y+1)
		{
			assert((y+1)*x + (s-x) == n);

			// cout<<x<<" "<<s-x<<" "<<y+1<<endl;

			ans = min(ans,y+1);
		}
	}

	if(ans == LLONG_MAX)
	ans = -1;

	lpri(ans);

	return 0;
}

