	ll ans = 1e18;
	for (ll i = 1; i*i <= diff; ++i) {
		if (diff % i == 0) {
			if (check_this_b(i + 1)) {
				ans = min(ans, i + 1);
			}
			if (check_this_b(diff / i + 1)) {
				ans = min(ans, diff / i + 1);
			}
		}
	}
	if (check_this_b(diff + 1)) {
		ans = min(ans, diff + 1);
	}
	print(ans == 1e18 ? -1 : ans);
}

