void CheckForB(long long n, long long s)
{
	int max_sroot = 316228;

	if (n < s)
	{
		std::cout << -1 << std::endl;
		return;
	}

	long long b = 1;

	if (s < 2 * max_sroot) // it could be possible that there are 3 or more b-digits
	{
		while (++b < max_sroot)
		{
			if (f(b, n) == s)
			{
				std::cout << b << std::endl;
				return;
			}
		}

	}

	// now we left with at most 2 digits
	// and the first is at most max_sroot
	long long firstDigit = max_sroot, nDiff = n - s + firstDigit;

	while ((++nDiff, --firstDigit) > 0)
	{
		b = nDiff / firstDigit;
		if (b * firstDigit == nDiff)
		{
			std::cout << b << std::endl;
			return;
		}
	}

	// let check
	if (firstDigit >= max_sroot)
	{
		std::cout << -1 << std::endl;
	}
}

