		return 0;
	}
	int res = n;
	for(int i = 2; i * i <= n; ++i) {
		if(f(i, n) == s) {
			res = min(res, i);
		}
	}
	for(int i = 1; i * i <= n; ++i) {
		int l = n / (i + 1) + 1;
