using namespace std;

LL n,s;


bool chk(LL b){
	LL res = 0;
	LL x = n;
	while(x){
		res += x%b;
		x /= b;
	}
	return (s==res);
}

int main(){

	cin>>n>>s;
	if(s==1){
		cout<<n<<endl;
		return 0;
	}
	if(n==s){
		cout<<n+1<<endl;
		return 0;
	} 

	LL ans = 1e18;
	for(LL b=2;b*b<=n;b++){
		if(chk(b)){
			ans = b;
			break;
		}
	}

	/*
	bx + y = n
	x + y = s
	(b-1)*x = n-s
	*/

	if(ans==1e18 && n-s<=0){
		cout<<"-1"<<endl;
		return 0;
	}

	LL b,y;
	for(LL x=1;x*x<=n-s;x++){
		if((n-s)%x==0){
			b = (n-s)/x + 1;
			y = s - x;
			if(x>=0 && y>=0 && n<b*b && y<b && x<b){
				ans = min(ans, b);
			}

			//
			b = x + 1;
			y = s - (n-s)/(b-1);
			if(x>=0 && y>=0 && n<b*b && y<b && x<b){
				ans = min(ans, b);
			}
		}
	}

	if(ans==1e18) ans = -1;
	cout<<ans<<endl;

	return 0;
}

