const lint INF = 1e15;

lint dsum(lint a, lint b){
    lint res = 0;
    while(a){res += a % b; a /= b;}
    return res;
}

int main(){
    lint n, s; cin >> n >> s;

    if(n == s) {cout << n + 1 << endl; return 0;}
    if(n < s) {cout << -1 << endl; return 0;}

    for(lint i=2;i*i<=n;i++) if(dsum(n, i) == s) {cout << i << endl; return 0;}

    lint ans = INF, v;
    for(lint i=1;i*i<=n-s;i++){
        if((n-s) % i == 0){
            if(v = dsum(n, (n-s)/i+1) == s) ans = min(ans, (n-s)/i+1);
            if(v = dsum(n, i+1) == s) ans = min(ans, i+1);
        }
    }

    if(ans == INF) cout << -1 << endl;
    else cout << ans << endl;
    return 0;
}

