ll digsum(ll x, ll b){
  ll mx = 1LL;
  while (mx * b <= x) mx *= b;

  ll ans = 0LL;
  while (x){
    ans += (x / mx);
    x %= mx;
    mx /= b;
  }

  return ans;
}

void solve(){
  ll n, s;
  cin >> n >> s;

  if (s == 1LL){
    cout << n << '\n';
    return;
  }

  if (n == s){
