  std::ios_base::sync_with_stdio(0);

  std::cout << std::fixed << std::setprecision(6);
  std::cerr << std::fixed << std::setprecision(6);

  long long n, s;

  std::cin >> n >> s;

  std::cerr << "n=" << n << " s=" << s << std::endl;

  if (n == s) {
    std::cout << n + 1 << std::endl;

    return 0;
  }

  for (int i = 2; i < 1111111; i ++) {
    long long S = 0;

    for (long long N = n; N; N /= i)
      S += N % i;

    if (S == s) {
      std::cout << i << std::endl;

      return 0;
    }
  }

  long long bm = INF;

  for (int i = 1; ; i ++) {
    long long l = n / (i + 1), u = n / i;

    if (u < 1000000)
      break;

    long long S = 0;

    for (long long N = n; N; N /= u)
      S += N % u;

    if (S == s) {
      bm = std::min(u, bm);
    }
    else if (s > S) {
      if ((s - S) % i == 0) {
        long long b = u - (s - S) / i;

        if (b > 1) {
          long long S = 0;

          for (long long N = n; N; N /= b)
            S += N % b;

          if (S == s)
            bm = std::min(b, bm);
        }
      }
    }
  }

  if (bm == INF)
    bm = -1;

  std::cout << bm << std::endl;

  return 0;
}

