bool is_ok(ll n, ll s, ll b)
{
    ll sum = 0;

    while (n > 0)
    {
        sum += n % b;
        n /= b;
        // cout << n << ' ' << b << endl;
    }
    return sum == s;
}

ll solve()
{
    ll n, s;
    cin >> n >> s;

    if (s > n)
        return -1;
    else if (s == n)
        return n + 1;

    for (ll b = 2; b * b <= n + 1; b++)
    if (is_ok(n, s, b))
        return b;

    ll b = -1;
    for (ll p = 1; p * p < n + 1; p++)
    {
        ll b2 = (n - s) / p + 1;
        if (b2 == 1) continue; 
        if(is_ok(n, s, b2))
            b = b2;
    }
    return b;
}

int main()
{
    ll ans = solve();
    cout << ans << endl;
    return 0;
}

