long long int digit(long long int n,long long int b){
    long long int ans=0;
    while(1){
        if(n<b){
            ans+=n;break;
        }else{
            ans+=n%b;
            n=n/b;
        }
    }
    return ans;
}

int main() {
    long long int n,s;cin>>n>>s;
    long long int rootn=(int)sqrt(n);
    long long int b=-1;
    for(long long int i=2;i<=rootn;i++){
        if(digit(n,i)==s){
            b=i;
            break;
        }
    }
    long long int t[rootn+2][3];/*rootn+2/*/
    for(int i=0;i<=rootn;i++)for(int j=0;j<=2;j++)t[i][j]=-1;
    if(b==-1){
        for(long long int i=rootn;i>=1;i--){
