#include <bits/stdc++.h>
using namespace std;
using ll = long long;
ll N,S; 


ll cal(ll N, ll b)
{
	ll ans = 0;
	while(N >= b){
		ans += N%b;
		N/=b;
	}
	return ans + N;
}

void solve()
{
	long long ans =  1e16;
	for(ll b=2; b*b<=N;++b){
		if(S==cal(N,b)) ans=min(ans,b);
	}
	for(ll x=1;x*x<=N;++x){
	    ll b=(N-S+x)/x;
	    if(b<2) continue;
	    if(S==cal(N,b)) ans=min(ans,b);
	}
	if(N==S) ans=min(ans, N+1);

	if(ans == 1e16) ans=-1;
	cout << ans << endl;
}

int main()
{
	cin >> N >> S;
	solve();
	return 0;
}

