ll n, s;

ll sum(ll b) {
  ll k = n;
  ll ans = 0;
  while (k > 0) {
    ans += k % b;
    k /= b;
  }
  return ans;
}

void solve() {
  cin >> n >> s;

  for (ll b = 2; b <= sqrt(n); b++) {
    if (sum(b) == s) {
      cout << b;
      return;
    }
  }

  ll ans = -1;
  for (ll p = 1; p <= sqrt(n - s); p++) {
    if ((n - s) % p != 0) continue;
    ll b = (n - s) / p + 1;
    if (b > 1 && sum(b) == s) {
      ans = ans == -1 ? b : min(ans, b);
    }
  }
  if (ans != -1) {
    cout << ans;
    return;
  }

  if (sum(n + 1) == s) {
    cout << n + 1;
    return;
  }

  cout << -1;
}

