using namespace std;

long long digitsum(long long b, long long n) {
    long long result = 0;
    while (n > 0) {
        result += n % b;
        n /= b;
    }
    return result;
}

int main() {
    long long n, s, result = LLONG_MAX;
    cin >> n >> s;
    for (long long b = 2; b * b <= n; b++) {
        if (digitsum(b, n) == s) {
            result = b;
            break;
        }
    }
    for (long long b = 2; b * b <= n - s; b++) {
        if ((n - s) % b == 0) {
            if (digitsum((n - s) / b, n) == s) {
                result = min(result, (n - s) / b);
            }
            if (digitsum(b, n) == s) {
                result = min(result, b);
            }
        }
    }
    if (n - s > 1 && digitsum(n - s, n) == s) {
        result = min(result, n - s);
    }
    if (s == 1) {
        result = min(result, n);
    }
    if (result == LLONG_MAX) {
        cout << -1;
    } else {
        cout << result;
    }
    return 0;
}

