int main(int argc, char* argv[])
{
    ll n, s;
    scanf("%lld%lld", &n, &s);

    if(n<s) {
        printf("-1\n"); return 0;
    }
    if(n==s) {
        printf("%d\n", n+1); return 0;
    }
    ll a=n-s;

    int i;
    vector<ll> v;
    for(i=1; i<sqrt((double)a)+0.1; i++) {
        if(a%i==0) {
            v.push_back(i);
            if(i!=a/i) v.push_back(a/i);
        }
    }
    sort(v.begin(), v.end());

    for(i=0; i<(int)v.size(); i++) {
        ll p = v[i]+1;
        ll curr=n;
        ll cnt=0;
        while(curr) {
            cnt += (curr%p);
            curr /= p;
        }
        if(cnt==s) {
            printf("%lld\n", p); return 0;
        }       
    }
    printf("-1\n");

    return 0;
}

