long f(long b, long n){
    if(n < b) return n;
    else return f(b, n/b) + n%b;
}

int main(){
    long n;
    long k;
    long ans = __LONG_MAX__;
    cin >> n;
    cin >> k;
    long m = n-k;
    if (m < 0){
        cout << -1 << endl;
        return 0;
    }else{
        if(k == f(n, n)) ans = n;
        for(long i = 2; i*i < m; i++){  
            if(m%(i-1) == 0){
                if(k == f(i, n)) ans = min(ans, i);
                if(k == f(m/(i-1)+1, n)) ans = min(ans, m/i);
            }
        }
    }
    if(ans == __LONG_MAX__) cout << -1 << endl;
    else cout << ans << endl;
}

