/*
11 乗ってそういうことだったのですね！！
1桁の場合は n==s ならば n+1 が候補です。
2桁の場合は、2桁目を全探索です。
3桁の場合は、基数を全探索です。
*/

int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  lint n, s; std::cin >> n >> s;
  if (n < s) err();
  if (n==s) {
    std::cout << n+1 << std::endl;
    return 0;
  }

  lint inf = std::numeric_limits<lint>::max();
  lint ans = inf;
  lint m = std::sqrt(n);
  rep(q,1,m+2) {
    lint X = n - s;
    lint x = X / q + 1;
    lint r = s - q;
    if (x <= q || r < 0 || x <= r) continue;
    debug(q,r,x);
    cmn(ans,x);
  }

  auto f = [&] (lint n, lint s) {
    lint ans = 0;
    while (n) {
      ans += n % s;
      n /= s;
    }
    return ans;
  };
  rep(x,2,m+1) {
    if (f(n,x) == s) {
      debug(x);
      cmn(ans,x);
    }
  }

  if (ans == inf) ans = -1;
  std::cout << ans << std::endl;
  return 0;
}

