int power_mod(int x, int y, int p) {
    if (y < 0)return 0;
    int res = 1;

    x = x % p;

    while (y) {
        if (y & 1)
            res = (res * x) % p;
        y = y >> 1;
        x = (x * x) % p;
    }
    return res;
}

int power(int x, int y) {
