ll chk(ll x, ll b) {
  ll sum = 0;
  while (x) {
    sum += x % b;
    x /= b;
  }
  return sum;
}

int main() {
  cin.tie(0);
  cin.sync_with_stdio(0);

  ll n, s;
  cin >> n >> s;
  if (n < s) return cout << -1, 0;
  ll ans = (n == s ? n + 1 : -1);
  for (ll b = 2; b * b <= n; ++b)
    if (chk(n, b) == s) ans = (ans == -1 ? b : min(ans, b));

  for (ll b = 1; b * b <= n; ++b) {
    if (n % b) continue;
    auto bb = (n - s) / b + 1;
    if (bb >= 2 && chk(n, bb) == s) ans = (ans == -1 ? bb : min(ans, bb));
  }
  cout << ans;
}

