        if((n-s) % p != 0) continue;
        long long b = 1 + (n - s) / p;
        long long q = n - p * b;
        if(p + q == s && p < b && q >= 0 && q < b) {
            res = b;
            break;
        }
    }
    if(res != INF) cout << res << endl;
    else cout << -1 << endl;
}

