template<typename T, typename F>
void divisors_foreach(T n, F f)
{
    T i = 1;
    for(; i*i < n; ++i) {
        if(n % i == 0) {
            f(i);
            f(n/i);
        }
    }

    if(i*i == n) {
        f(i);
    }
}

s64 N;
s64 S;

s64 f(s64 b, s64 n)
{
    if(n < b) return n;
    return f(b, n/b) + n%b;
}

void solve()
{
    if(N-S <= 0) {
        PRINTLN(-1);
        return;
    }

    s64 ans = INF;

    divisors_foreach(N-S, [&ans](s64 d) {
        s64 b = d + 1;
        if(f(b,N) == S)
            chmin(ans, b);
    });

    if(ans == INF) ans = -1;
    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/)
