void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N>>S;
	if(S>N) return _P("-1\n");
	if(N==S) return _P("%lld\n",N);
	for(ll b=2;b*b<=N;b++) {
		if(f(b,N)==S) return _P("%lld\n",b);
	}
	set<ll> SS;
	for(ll p=1;p*p<N && p<=S;p++) {
		ll m=S-p;
