using namespace std;
typedef long long ll;

ll N, S;

ll f(ll b, ll n) {
  if(n < b) return n;
  return f(b, n / b) + (n % b);
}

int main(void) {
  cin >> N >> S;

  ll ans = INF;
  REP(b, 2, (ll) (sqrt(N) * 2 + 1)) {
    if(f(b, N) == S) ans = min(ans, b);
  }
  for(ll i = (ll) sqrt(N) * 2; i >= 0; i--) {
    ll p = N / (i + 1), q = (i != 0 ? N / i : INF);
    if(p == 0) continue;
    for(ll k = (N - S + i) / q; k < (N - S + i + p - 1) / p; k++) {
      if(k == 0) continue;
      if((N - S + i) % k == 0) {
        ll b = (N - S + i) / k;
        if(p < b && b <= q && f(b, N) == S) ans = min(ans, b);
      }
    }
  }
  cout << (ans < INF ? ans : -1) << endl;
}

