			long long z = f(y, n);
			if (z > s)continue;
			if ((s - z) % i)continue;

			long long tmp = y - (s - z) / i;
			if (tmp <= n / (i + 1))continue;

			ans = min(ans, tmp);
		}
		for (int i = 2; i<=sqrt(n); i++) {
			long long y = i;
			if (f(y, n) == s)ans = min<long long>(ans, i);
		}

		cout << ans << endl;
	}



	return 0;
}

