ll Solve() {
  if (n < s)
    return -1;
  if (n == s)
    return n + 1;
  ll diff = n - s;
  for (ll i = 1; i * i <= diff; ++i) {
    if (diff % i)
      continue;
    Check(i + 1);
    Check(diff / i + 1);
  }
  return sol == kInf ? -1 : sol;
}

