LL solve(LL n, LL s)
{
    int b = 2;
    for (; 1LL * b * b <= n; ++ b) {
        LL x = n;
        LL ss = 0;
        while (x) {
            ss += x % b;
            x /= b;
        }
        if (ss == s) {
            return b;
        }
    }
    if (n >= s) {
        for (int q = b; q >= 1; -- q) {
            LL xb = (n - s) / q + 1;
            if (xb >= 2 && n / xb + n % xb == s && n / xb / xb == 0) {
                return xb;
            }
        }
    }
    if (n == s) {
        return n + 1;
    }
    return -1;
}

