long long digit_sum(long long n, long long base) {
  assert(base >= 2);
  long long res = 0;
  while (n) {
    res += n % base;
    n /= base;
  }
  return res;
}
signed main() {
  cin.tie(0); ios::sync_with_stdio(false);
  long long n, s; cin >> n >> s;
  for (long long b = 2; b * b <= n; b++) {
    if (digit_sum(n, b) == s) {
      cout << b << '\n';
      return 0;
    }
  }
  for (long long a1 = sqrt(n) + 1; a1 >= 1; a1--) {
    if ((n - s) % a1) {
      long long b = (n - s) / a1 + 1;
      if (sqrt(n) < b and b <= n and a1 < b and 0 <= s - a1 and s - a1 < b) {
        cout << (n - s) / a1 + 1 << '\n';
        return 0;
      }
    }
  }
  cout << (s == n ? n + 1 : -1) << '\n';
  return 0;
}

