  ll z=0,k=2,x=n;
  while(z<n) {
    ll y=x/k+k-1;
    ll c=x%(k-1);
    ll d=(y-c)/(k-1);
    if((s-c)%(k-1)==0) {
      //pr(n-(z-1+(s-c)/(k-1)));
      ll m=n-(z-1+(s-c)/(k-1));
      ll xx=n,sum=0;
      while(xx) {
        sum+=xx%m;
        xx/=m;
      }
      if(sum==s) ans=min(ans,n-(z-1+(s-c)/(k-1)));
    }
    z+=d;
    k++;
    if(k>1000000) break;
  }
  pr(ans);
}

