long long f(long long b, long long n)
{
    if(n < b)
        return n;
    else
        return f(b, n / b) + n % b;
}

int main()
{
    long long n, s;
    cin >> n >> s;
    if(n == s){
        cout << (n + 1) << endl;
        return 0;
    }

    for(long long b=2; b*b<=n; ++b){
        if(f(b, n) == s){
            cout << b << endl;
            return 0;
        }
    }

    // n == x * b + y
    // s == x + y
    long long ans = -1;
    for(long long x=1; x*x<n; ++x){
        if((n - s) % x != 0)
            continue;
        long long b = (n - s) / x + 1;
        long long y = n - x * b;
        if(y < b)
            ans = b;
    }
    cout << ans << endl;

    return 0;
}

