int n, s;

int cal(int x, int y){
    int ans = 0;
    while (y){
        ans += y % x;
        y /= x;
    }
    return ans;
}

signed main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
    int ans = inf;
    cin >> n >> s;
    if (s == 1) Ptest(n);
    if (n == s) Ptest(n - 1);
    if (n < s) Ptest(-1);
    ForE(i, 2, sqrt(n)){
        if (cal(i, n) == s){
            ans = min(ans, i);
        }
    }
    if (cal(n - s, n) == s){
        ans = min(ans, n - s);
    }
    ForE(i, 2, sqrt(n - s)){
        if ((n - s) % i == 0){
            if (cal(i, n) == s){
                ans = min(ans, i);
            }
            if (cal((n - s) / i, n) == s){
                ans = min(ans, (n - s) / i);
            }
        }
    }
    cout << (ans == inf ? -1 : ans);
}

