		return f(b, n / b) + n % b;
}

ll solve(ll n, ll s){

	if (s >= n)
		return -1;

	//if (s == 1)
	//	return n;

	for (ll b = 2; b * b <= n; b++) {
		if (f(b, n) == s) {
			return b;
		}
	}

	set<ll> divisor;
	for (ll d = 1; d * d <= n; d++) {
		if ((n - s) % d == 0) {
			divisor.insert(d);
			divisor.insert((n - s) / d);
		}
	}

	ll minb = INT64_MAX;
	for (auto d : divisor) {
		ll b = d + 1;
		if (b <= sqrt(n))
			continue;
		ll a1 = (n - s) / d;
		if (a1 >= b)
			continue;
		ll a0 = s - a1;
		if (a0 < 0 || a0 >= b)
			continue;
		minb = min(minb, b);
	}

	return (minb == INT64_MAX ? -1 : minb);
}

