    vector<ll> front,back;
    for(ll i=1;i*i<N+1;i++){
        if(N%i==0){
            front.push_back(i);
            back.push_back(N/i);
        }
    }
    while(!back.empty()){
        if(back.back()==front.back()) back.pop_back();
        else{
            front.push_back(back.back());
            back.pop_back();
        }
    }
    return front;
}

