ll f(ll b, ll n) {


    ll answer = 0;
    while(n >= b) {
        answer += n % b;
        n /= b;
    }
    return answer + n;


}


ll SolveOne(ll n) {
    vector<ll> divs;
    for(ll j=2;j*j<=n;j++) {
        if (n % j == 0) {
            ll m = n;
            while(m % j == 0) {
                m /= j;
            }

            if (m == 1)
                return j;
        }
    }

    return n;

}


ll SolveRev(ll n, ll s) {
    // 1, s-1
    // s-1 <= b-1

    // b + s - 1 = n

    // b = n-s+1 >= s
    if (n-s+1 >= s)
        return n-s+1;
    else
        return -1;


}

ll Solve(ll n, ll s) {

    if (n == s)
        return n + 1;

    if (s == 1) {
        return SolveOne(n);
    }


    ll prev = -1;
    int time_since_last_increase = 0;
    ll low = 100000000 + 1;
    for(int j=2;j<=100000000;j++) {
        ll curr = f(j,n);
        if (curr == s) {
            return j;
        }
        prev = curr;
    }
    ll high = 1000000000000000000ll;

    while(low < high) {
        ll mid = (low + high)/2;

        if (f(mid, n) >= s) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }

    if (f(low, n) != s) {
        return SolveRev(n, s);
    }
    else
        return low;
}


