ll digsum(ll x, ll b){
  ll mx = 1LL;
  while (mx * b <= x) mx *= b;

  ll ans = 0LL;
  while (x){
    ans += (x / mx);
    x %= mx;
    mx /= b;
  }

  return ans;
}

void solve(){
  ll n, s;
  cin >> n >> s;

  for (ll i = 2; i < 1e6; i++){
    if (digsum(n, i) == s){
      cout << i << '\n';
      return;
    }
  }

  //kx + b = n
  //k + b = s
  //n - s = kx-k
  //n - s = k(x-1)

  if (n == s) {
    cout << n + 1LL << '\n';
    return;
  }

  ll mn = -1;
  for (ll i = 1; i <= sqrt(n - s); i++){
    if ((n-s) % i == 0LL){
      ll res = (n-s)/i + 1;
      //cerr << res << '\n';
      if (res > s-i && res * i <= n)
        mn = res;
    }
