    cin >> n >> s;

    if (s > n) {
        cout << "-1\n";
        return 0;
    }

    if (s == n) {
        cout << n + 1 << "\n";
        return 0;
    }

    for (ll b = 2; b * b <= n; ++b) {
        ll g = get(n, b);
        if (g == s) {
            cout << b << "\n";
            return 0;
        }
    }

    ll val = n - s;
    ll ans = inf;

    for (ll d = 1; d * d <= val; ++d) {
        if (val % d == 0) {
            ll b = d + 1;
            ll x = val / d;
            if (x <= s && b > max(x, s - x)) {
                ans = min(ans, b);
