            if (d * d != val) {
                b = val / d + 1;
                x = d;
                if (x <= s && b > max(x, s - x)) {
                    ans = min(ans, b);
                }
            }
        }
    }

    cout << (ans == inf ? -1 : ans) << "\n";

}

