        if ((n - s) % a1 == 0) {}
        int b = (n - s) / a1 + 1;
        if (b >= 2) {
            int sum = 0;
            int N = n;
            while (N > 0) {
                sum += N % b;
                N /= b;
            }
            if (sum == s) {
                ans = min(ans, b);
            }
        }
    }

    if (ans == INF) cout << -1 << endl;
    else cout << ans << endl;
}

