    vector<ll> ret;
    ret.emplace_back(n);
    for (ll i = 1; i*i< n; ++i) {
        if(n%i == 0){
            ret.emplace_back(i);
            if(i != 1 && i*i!=n){
                ret.emplace_back(n/i);
            }
        }
    }
    return ret;
}
