using namespace std;
using ll = long long;
const ll infl = 1LL << 60;
const int inf = 1 << 30;

ll f(ll b, ll n) {
    if (b > n) return n;
    else return f(b, n / b) + (n % b);
}

ll ceilDiv(ll a, ll b) {
    return (a + b - 1LL) / b;
}

int main() {
    ll n, s; cin >> n >> s;
    ll all = sqrt(n);

    if (n == 1) {
        if (s == 1) {
            cout << 2 << endl;
        }
        else {
            cout << -1 << endl;
        }
        return 0;
    }

    if (s > n) {
        cout << -1 << endl;
        return 0;
    }

    if (s == n) {
        cout << (n + 1LL) << endl;
        return 0;
    }

    for (ll b = 2LL; b <= all; ++b) {
        ll dsum = f(b, n);
        if (dsum == s) {
            cout << b << endl;
            return 0;
        }
    }

    ll k = 1;
    ll ans = infl;

    while (true) {
        ll low = ceilDiv(n + 1LL, k + 1LL);
        ll upp = ceilDiv(n + 1LL, k);
        ll cur = (upp + low) / 2LL;

        if (low <= all) {
            break;
        }

        while (upp - low > 1LL) {
            ll dsum = f(cur, n);

            if (dsum < s) upp = cur;
            else low = cur;

            cur = (upp + low) / 2LL;
        }

        if (f(low, n) == s) {
            ans = min(ans, low);
        }

        ++k;
    }

    if (ans != infl) {
        cout << ans << endl;
    }
    else {
        cout << -1 << endl;
    }

    return 0;
}

