#define ll long long
using namespace std;

ll n,s;

ll check(ll n, ll b) {
	ll r=0;
	for (;n;n/=b) r+=n%b;
	return r;
}

ll f(ll n, ll s) {

	if(n==s) return n+1;
	if(n<s) return -1;

	for (ll i=2;i<=sqrt(n);i++) {
		if (check(n,i)==s) return i;
	}

	n-=s;

	for (ll i=sqrt(n+s)+1;i;i--) {
		if (n%i==0&&n/i>0&&check(n+s,n/i+1)==s) return n/i+1;
	}

	return -1; 
}

int main() {

	scanf("%lld%lld",&n,&s);
	printf("%lld\n",f(n,s));

	return 0;

}

