using namespace std;

typedef long long ll;

ll digit_sum(ll i, ll b)
{
    ll ans = 0;
    while (i > 0)
    {
        ans += i % b;
        i /= b;
    }
    return ans;
}

const ll INF = 10000000000000000LL;

int main()
{
    ll n, s;
    cin >> n >> s;

    ll ans = INF;

    if (n == s)
    {
        cout << n + 1 << endl;
    }
    else
    {
        for (ll b = 2; b * b < n; b++)
        {
            if (digit_sum(n, b) == s)
            {
                ans = min(ans, b);
            }
        }

        for (ll p = 1; p * p < n; p++)
        {
            const ll b = (n - s) / p + 1;
            if (b > 1 && digit_sum(n, b) == s) 
            {
                ans = min(ans, b);
            }
        }

        if (ans == INF)
        {
            cout << -1 << endl;
        } 
        else
        {
            cout << ans << endl;
        }
    }
}

