        }
    }

    // n == x * b + y
    // s == x + y
    long long ans = -1;
    for(long long x=1; x*x<n; ++x){
        long long b = (n - s) / x + 1;
        if(f(b, n) == s)
            ans = b;
    }
    cout << ans << endl;

