    cin >> N >> S;

    ll val = (ll)sqrt((double)N);
    //実際に割るO(sqrt(N) log sqrt(N))
    for(ll i = 2; i <= val; i++) {
        ll sum = 0;
        ll n = N;
        while(n) sum += n % i, n /= i;
        if(!~ans && sum == S) ans = i;
    }

    for(ll i = val; i > 0; i--) {
        ll minv = N % (N / i), maxv = N % (N / (i + 1) + 1);
        if(!~ans && minv <= S - i && S - i <= maxv) {
            ans = -(S + i - N) / i;
        }
    }
    if(!~ans && N == S) ans = N + 1;
    cout << ans << endl;
    return (0);
}

