using namespace::std;

LL f(LL b,LL N){
	LL temp = N;

	LL sum = 0;
	while(temp){
		sum += (temp%b);
		temp /=b;
	}

	return sum;
}
void solve(){
	LL N,sum;
	cin >> N >> sum;
	if(N==sum){
		cout << N+1 << endl;
		return;
	}
	/*
	2から(√N)進数まで総当り。
	*/
	LL rN = sqrt(1.0*N)+1;
	for(LL b = 2; b <= rN;++b){
		LL temp = f(b,N);
		if( temp == sum ){
			cout << b << endl;
			return;
		}
	}
	/*
	√N進数より大きい進数では2桁しかない
	A1*b+A0 = N
	1<= A1 < b;//b進数の2桁の条件
	0<= A0 < b;
	A1+A0 = sum;//

	*/
	for(LL A1=rN;A1>=1;--A1){
		LL A0 = sum - A1;
		if( A0 < 0 ) continue;
		//int ans = (N-sum+A1)/A1;
		LL b = (N-sum)/A1 + 1;
		if( b < 2 ) continue;

		if( f(b,N) == sum ){
			cout << b << endl;
			return;
		}
	}
	cout << -1 << endl;
}

