ll A,S;
vector<ll>p;
vector<pii>prime;

ll solve_small(ll base){
	ll cur=A,sum=0LL;
	while(cur){
		sum+=cur%base;
		cur/=base;
	}
	return sum;
}

void get_prime(ll x){
	for(ll i=2LL;i*i<=x;i++){
		if(x%i)continue;
		prime.push_back(mk(i,0));
		while(x%i==0){
			prime[prime.size()-1].se++;
			x/=i;
		}
	} 
	if(x>1)prime.push_back(mk(x,1));
} 

void go(ll cur,int pos){
	if(pos==prime.size()){
		p.push_back(cur);
		return;
	}
	go(cur,pos+1);
	rep(i,prime[pos].se){
		cur*=prime[pos].fi;
		go(cur,pos+1);
	}
}

ll solve_big(){
	if(A==S)return A+1;
	ll cur=A-S;
	if(cur<0)return -1;
	get_prime(cur);
	go(1LL,0);
	sort(p.begin(),p.end());
	rep(i,p.size()){
		ll now=p[i]+1;
		if(A/now+A%now==S)return now; 
	} 
	return -1;
}

int main(){
	scanf("%lld%lld",&A,&S);
	ll i=2LL;
	for(i=2LL;i*i<=A;i++){
		if(solve_small(i)==S){
			printf("%lld\n",i);
			return 0;
		}
	}
	printf("%lld\n",solve_big());
	return 0;
}

