        for (long long N = n; N; N /= n)
          S += N % n;

        if (S == s)
          bm = n;
      }
    }
    else {
      long long l = n / i - 1, u = n / (i - 1) - 1;

      if (l < 1000000)
        break;

      while (u - l > 1) {
        long long m = (l + u) / 2;

        S = 0;

        for (long long N = n; N; N /= m)
          S += N % m;

        (S > s ? u : l) = m;
