const long long inf = (long long) 1e18;

long long n, s;

bool ok(long long b) {
  if (b <= 1) return false;
  long long tmp = n;
  long long ret = 0;
  while (tmp) {
    long long d = tmp % b;
    ret += d;
    tmp /= b;
  }
  return ret == s;
}

int main() {
  scanf("%lld %lld", &n, &s);
  for (int i = 1; (long long) i * i <= n; i++) {
    if (ok(i)) {
      printf("%d\n", i);
      return 0;
    }
  }
  long long ans = inf;
  for (int i = 1; (long long) i * i <= n; i++) {
    if (n > s && (n - s) % i == 0) {
      if (ok((n - s) / i + 1)) ans = min(ans, (n - s) / i + 1);
    }
  }
  if (ans == inf) ans = -1;
  printf("%lld\n", ans);
  return 0;
}

