/*
・約数列挙
  > O(√n)
[使用例] vl div = divisor(105);
[備考] 整列されていない
*/

vl divisor(ll n) {
  vl ret;
  for(ll i = 1; i * i <= n; i++) {
    if (n % i == 0) {
      ret.PB(i);
      if (i * i != n) ret.PB(n/i);
    }
  }
  SORT(ret);
  return ret;
}

signed main() {

  SS(ll,N,S);

  if (N == S) return print(N + 1);

  // N-Sはb-1の倍数
  auto dd = divisor(N - S);

  EACH(d, dd) {
    // d+1進数を考える
    ll cnt = 0;
    ll num = N;
    while (num) {
      cnt += num % (d + 1);
      num /= d + 1;
    }
    if (cnt == S) return print(d + 1);
  }
  print(-1);

}

