int f(LL b,LL N){
	LL temp = N;

	int sum = 0;
	while(temp){
		sum += (temp%b);
		temp /=b;
	}

	return sum;
}
void solve(){
	LL N,sum;
	cin >> N >> sum;
	if(sum==1){
		cout << N << endl;
		return;
	}
	/*
	2から(√N)進数まで総当り。
	*/
	int rN = sqrt(1.0*N);
	for(int b = 2; b <= rN;++b){
		int temp = f(b,N);
		if( temp == sum ){
			cout << b << endl;
			return;
		}
	}
	/*
	√N進数より大きい進数では2桁しかない
	A1*b+A0 = N
	1<= A1 < b;//b進数の2桁の条件
	0<= A0 < b;
	A1+A0 = sum;//

	*/
	for(int A1=rN;A1>=1;--A1){
		int A0 = sum - A1;
		if( A0 < 0 ) continue;
		int ans = (N-sum+A1)/A1;
		if( f(ans,N) == sum ){
			cout << ans << endl;
			return;
		}
	}
	cout << -1 << endl;
}

