void CheckForB(long long n, long long s)
{
	long long max_sroot = 316228;

	if (n < s)
	{
		std::cout << -1 << std::endl;
		return;
	}

	long long b = 1;

	if (s < 2 * max_sroot) // it could be possible that there are 3 or more b-digits
	{
		while (++b < max_sroot)
		{
			if (f(b, n) == s)
			{
				std::cout << b << std::endl;
				return;
			}
		}

	}

	// now we left with at most 2 digits
	// and the first is at most max_sroot
	long long firstDigit = std::min(s, max_sroot), nDiff = n - s + firstDigit;

	while ((++nDiff, --firstDigit) > 0)
	{
		b = nDiff / firstDigit;
		if (b * firstDigit == nDiff)
		{
			std::cout << b << std::endl;
			return;
		}
	}

	std::cout << -1 << std::endl;
}

int main(int, char**)
{
		long long n, s;

		std::cin >> n >> s;

		CheckForB(n, s);

	return 0;
}

