        for (LL p=1;p*p<=n-s;p++) {
            if ((n-s)%p==0) {
                LL b=(n-s)/p+1;
                if (f(b,n)) {
                    flag=true;
                    ans=min(ans,b);
                }
            }
        }
        if (!flag) puts("-1");
        else printf("%lld\n", ans);
    }
    return 0;
}

