inline li fl(li n, li b) {
	return n / b;
}

inline li calc(li b, li n) {
	if (b <= 1)return 0;
	if (n < b)return n;
	return n % b  + calc(b, fl(n, b));
}

inline li solve_(li n, li s) {
	repp(b, 2, n) {
		if (calc(b, n) == s)return b;
	}
	return -1;
}


inline li solve(li n, li s) {
	repp(b, 2, sqrt(n) + 1) {
		if (calc(b, n) == s)return b;
	}

	// 2桁の場合
	// n(10) = pb+q(b)
	// b = (n-q)/p = (n-s+p)/p=1+(n-s)/p
	repp(p, 1, sqrt(n) + 1) {
		li b = 1 + (n - s) / p;
		if (calc(b, n) == s)return b;
	}
	return -1;
}

