    ll f(ll b, ll n){
        if(n < b) return n;
        return f(b, n/b) + n % b;
    }

    solver(istream& I, ostream& O) :is(I), os(O) {}
    void run(){
        ll n, s;
        is >> n >> s;
        if(!is) return;
        if(n == s) {
            os << n + 1 << endl;
            return;
        }

        for (int b = 2; b < sqrt(n)+2; ++b) {
            if(f(b, n) == s){
                os << b << endl;
                return;
            }
        } // end b
        ll ns = n + s;
        for (int p = sqrt(n); p >= 1; --p) {
