using ll = long long;
ll f(ll b, ll n)
{
    if(n < b) return n;
    else
    {
        return f(b, n/b) + n % b;
    }
}
int main()
{
    ll N, s;
    cin >> N >> s;
    if(N == s)
    {
        cout << N + 1 << endl;
        return 0;
    }

    for(ll i = 2; i * i <= N; i++)
    {
        if(f(i, N) == s)
        {
            cout << i << endl;
            return 0;
        }
    }
    for(ll i = sqrt(N) + 1; i >= 1; i--)
    {
        ll b = (N - s) / i + 1;
        if(b >= sqrt(N) && f(b, N) == s)
        {
          cout << b << endl;
          return 0;
        }
    }
    cout << -1 << endl;
}

