{
	if (b == 1) return -1;
	i64 ret = 0;
	while (n) {
//		printf("%lld %lld\n", b, n);
		ret += n % b;
		n /= b;
	}
	return ret;
}

int main()
{
	scanf("%lld%lld", &N, &S);

	i64 ret = 1LL << 60LL;

	for (i64 b = 2; b <= 4e5; ++b) {
		if (sum(b, N) == S) {
			ret = min(ret, b);
		}
	}
