	for (i64 i = 1; i <= 4e5; ++i) {
		if ((N - S) % i == 0) {
			{
				i64 b = i + 1;
				if (sum(b, N) == S) {
					ret = min(ret, b);
				}
			}
			{
				i64 b = (N - S) / i + 1;
				if (sum(b, N) == S) {
					ret = min(ret, b);
				}
			}
