using namespace std;
ll n,s;
bool check(ll x){
	if(n/x>=x)return 0;
	if(x<2)return 0;
	ll k=n/x;ll r=n%x;
	if(s==k+r)return 1;
	return 0;
}
ll js(ll x,ll b){
	ll ans=0;
	while(x){
		ans+=x%b;
		x/=b;
	}
	return ans;
}
int main()
{
	//freopen("H:\\c++1\\in.txt","r",stdin);
	//freopen("H:\\c++1\\out.txt","w",stdout);
	cin>>n>>s;
	ll b=1e18;
	if(n==s)b=n+1;
	if(n>s){
		ll temp=n-s;
		for(ll t=1;t<=sqrt(temp);t++){
			if(temp%t==0){
				ll x=t+1,y=temp/t+1;
				if(check(x))b=min(b,x);
				if(check(y))b=min(b,y);
			}
		}
	}
	for(ll t=2;t<=1000000;t++){
		ll cnt=js(n,t);
		if(cnt==s){
			b=min(b,t);
			break;
		}
	}
	if(b==1e18)printf("-1\n");
	else printf("%lld\n",b);
	return 0;
}

