#include <bits/stdc++.h>
using namespace std;
typedef long long LL;

LL f(LL b, LL n){
    if(n < b) return n;
    return f(b, n / b) + n % b;
}

int main(){
    LL n, s;
    scanf("%lld%lld", &n, &s);
    if(s == 1){
        printf("%lld\n", n);
        return 0;
    }
    if(n == s){
        printf("%lld\n", n + 1);
        return 0;
    }
    int ans = -1;
    for(int i = 2; i <= (int)1e6; i++){
        if(f(i, n) == s){
            ans = i;
            break;
        }
    }
    if(ans != -1){
        printf("%d\n", ans);
        return 0;
    }
    if(n > (int)1e6){
        LL l = (int)1e6 + 1, r = n - 1, mid;
        while(l < r){
            mid = (l + r) >> 1;
            if(f(mid, n) <= s)
                r = mid;
            else
                l = mid + 1;
        }
        if(f(r, n) == s) ans = r;
    }
    printf("%d\n", ans);
    return 0;
}
