ll S, N;

ll Func(ll b, ll n) {
    if(n < b) { return n; }
    else { return Func(b, n/b) + (n % b); }
}

int main()
{
    cin >> N >> S;
    //for(ll i = 2; i <= N; ++i) {
    //    printf("b: %lld s: %lld\n", i, Func(i, N));
    //}
    ll maxVal = (N % 2 == 0) ? (N / 2) : (N / 2 + 1);
    if(S > maxVal) {
        printf("-1\n");
        return 0;
    }
    ll ans = maxVal + (maxVal - S);
    if(N % 2 == 0) { ans++; }

    ll b = N / 2;
    ll inc = 2;
    while(b > 1) {
        ll cand = Func(b, N);
        if(inc < b) {
        if((S - cand) % inc == 0) {
            ll x = (S - cand) / inc;
            if(cand + inc * x  > b - x) {
                ans = min(ans, b - x);
                b -= x;
                inc++;
                continue;
            }
        }
        inc++;
        b -= ((b - cand) / inc);
        while(Func(b, N) > Func(b+1, N)) { b--; }
        } else {
            if(cand == S) { ans = min(ans, b); }
            b--;
        }
    }

    printf("%lld\n", ans);

    return 0;
}

