    printf("-1\n");
    return 0;
  }
  if(S==N){
    printf("%ld\n",N+1);
  }
  int64_t i=1;
  for(;i*i<=(N-S);i++){
    if((N-S)%i==0) check(N,S,i+1);
  }
  for(;i>0;i--){
    if((N-S)%i==0) check(N,S,(N-S)/i+1);
  }
  printf("-1\n");
  return 0;
}

