    ll n, s;
    cin >> n >> s;

    ll sqr = (ll)sqrt((double)n);
    ll ret = inf;
    for (ll i = 2; i <= sqr; i++) {
        ll t = n, ans = 0LL;
        while (t > 0) {
            ans += t % i;
            t /= i;
        }
        if (ans == s) {
            ret = min(ret, i);
            break;
        }
    }

    if (ret == inf) {
        for (ll p = 1; p <= sqr; p++) {
            ll q = s - p; // p + q = s
            if ((n - s) % p == 0) {
                ll b = (n - s) / p + 1LL; // n = bp + q
                if (b > p && b > q) {
                    ret = min(ret, b);
                    break;
                }
            }
        }
    }

    if (ret == inf) {
        cout << -1 << endl;
    } else {
        cout << ret << endl;
    }

    return 0;
}

