    if (b <= 1 || n <= 0) return LINF;
    else if (n < b) return n;
    else return f(b, n / b) + n % b;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll n, s;
    cin >> n >> s;
    ll sqrt_n = (ll) sqrt(n) + 1;
    ll best = LINF;
    auto update = [&](ll upd) {
        if (upd >= 2) best = min(best, upd);
    };
    if (n < s) {
        cout << -1 << endl;
        return 0;
    } else if (n == s) {
        cout << n << endl;
        return 0;
    }
    for (ll b = 2; b <= sqrt_n; ++b) {
        if (f(b, n) == s) update(b);
    }

    ll n_s = n - s;
    for (ll p = 1; p < sqrt(n_s); ++p) {
        if (n_s % p == 0) {
            ll b = n_s / p + 1;
            if (f(b, n) == s) update(b);
        }
    }
    cout << (best == LINF ? -1 : best) << endl;
    return 0;
}

