template <typename T> vector<T> divisors(T n) {
  vector<T> ret;
  for (T i = 1; i * i <= n; i++) {
    if (n % i == 0) {
      ret.push_back(i);
      if (i * i != n) ret.push_back(n / i);
    }
  }
  sort(ret.begin(), ret.end());
  return ret;
}

bool check(ll b) {
  ll s = 0;
  ll n = N;
  while (n) {
    s += n % b;
    n /= b;
  }
  return s == S;
}

void Main() {
  scanf("%lld%lld", &N, &S);

  if (S == N) {
    _p("%lld\n", N+1);
    return;
  }

  int sqn = sqrt(N);

  // sqrt(N) までは全通り試す
  rep(b, 2, sqn+1) {
    if (check(b)) {
      _p("%d\n", b);
      return;
    }
  }

  ll ans = 1e18;

  auto ds = divisors(N-S);
  forr(p, ds) {
    ll b = (N-S)/p + 1;
    if (check(b)) {
      ans = min(ans, b);
    }
  }

  if (ans == 1e18) puts("-1");
  else _p("%lld\n", ans);
