typedef long long LL;

LL f(LL b, LL n){
    if(n < b) return n;
    return f(b, n / b) + n % b;
}

int main(){
    LL n, s;
    scanf("%lld%lld", &n, &s);
    if(s == 1){
        printf("%lld\n", n);
        return 0;
    }
    if(n == s){
        printf("%lld\n", n + 1);
        return 0;
    }
    if(s > n){
        puts("-1");
        return 0;
    }
    LL ans = -1;
    LL tmp = sqrt(n) + 1;
    if(s <= tmp){
        for(LL b = 2; b <= tmp; b++){
            if(f(b, n) == s){
                ans = b;
                break;
            }
        }
    }else{
        LL d = n - s;
        for(LL b = 2; b * b <= d; b++){
            if(d % b == 0){
                LL p = d / b + 1;
                LL q = s - p;
                if(p * b + q == n){
                    ans = b;
                    break;
                }
            }
        }
    }
    printf("%lld\n", ans);
    return 0;
}
