int64 f(int64 b, int64 n) {
  int64 ret = 0;
  while (n) {
    ret += n % b;
    n /= b;
  }
  return ret;
}

int64 Solve(int64 n, int64 s) {
  if (n < s)
    return -1;
  if (n == s)
    return n + 1;

  int64 sq = sqrt(n);
  for (int64 b = 2; b <= sq; ++b) {
    if (f(b, n) == s)
      return b;
  }

  int64 r = n + 1;
  for (int64 p = 1; p <= sq; ++p) {
    int64 b = n / p;
    int64 q = n % b;
    if (s == p + q && b < r)
      r = b;
  }

  if (r <= n)
    return r;
  return -1;
}

int main() {
  int64 n, s;
  cin >> n >> s;
  cout << Solve(n, s) << "\n";
  return 0;
}

