inline long long f(const long long & b, long long n) {
	long long ans = 0;
	for (; n > 0; n /= b)
		ans += n % b;
	return ans;
}

long long answer(const long long & n, const long long & s) {
	if (n == s)
		return n + 1;
	else if (n > s) {
		vector<long long> vtr;
		long long x = n - s;
		for (int i = 1; i <= x / i; i++) {
			if (x % i == 0) {
				vtr.push_back(i);
				if (i != x / i)
					vtr.push_back(x / i);
			}
		}
		sort(vtr.begin(), vtr.end());
		for (const auto & b : vtr) {
			if (f(b + 1, n) == s)
				return b + 1;
		}
		return -1;
	} else
		return -1;
}

