		while (x >= i)
		{
			sum += x % i;
			x /= i;
		}
		sum += x;
		if (sum == s)
		{
			cout << i << endl;
			return 0;
		}
	}
	ll y = n - s;
	for (ll j = 1; j * j <= y; j++)
		if (y % j == 0)
			vec.push_back(j), vec.push_back(y / j);
	sort(vec.begin(), vec.end(), cmp);
	for (ll j = 0; j < vec.size(); j++)
	{
		ll b = y / vec[j] + 1;
		if (check(b))
		{
			cout << b << endl;
			return 0;
		}
	}
	cout << -1 << endl;
	return 0;
}

