long long f(long long b, long long n){
  long long ret = 0;
  while(n){
    ret += n % b;
    n /= b;
  }
  return ret;
}

int main(){
  long long n, s;
  scanf("%lld%lld", &n, &s);

  long long ans = -1;
  if(n == s) ans = n + 1;
  for(long long b = 2; b * b <= n; ++b){
    if(f(b, n) == s){
      ans = b;
      break;
    }
  }

  for(long long a1 = 1; a1 <= s && a1 * a1 <= n; ++a1){
    long long a0 = s - a1;

    if((n - a0) % a1) continue;

    long long b = (n - a0) / a1;
    if(a0 >= b || a1 >= b) continue;

    if(ans >= 0) ans = min((n - a0) / a1, ans);
    else ans = (n - a0) / a1;
  }

  printf("%lld\n", ans);

  return 0;
}

