int f(int b,int n,int sum) {
	int a=n;
	if(a<b) {
		sum+=a;
		return sum;
	} else {
		a=floor(b/a);
        sum+=f(b,a,sum)+b%a;
        return sum;
	}
}
int main () {
	int b,n,s;
	int sum=0;
	scanf("%d %d",&n,&s);
	for(b=0;b<=s;b++){
		if(s==f(b,n,sum)){
			printf("%d",b);
			return 0;
		} 
	}
	printf("-1");
	return 0;
}

