        ret[pos++] = tp;
        int[] ptn = new int[tp];
        for(int i = (tp - 3) / 2;i < tp << 5;i += tp)
            ptn[i >> 5] |= 1 << (i & 31);
        for(int i = 0;i < tp;i++){
            for(int j = i;j < sup;j += tp)
                isp[j] |= ptn[i];
        }
    }

