      if((q > 0) && (n > q) && (((n - q) % p) == 0)) {
        long b = (n - q) / p;
        if((b > p) && (b > q)) {
          long t = n;
          long c = 0;
          while(t > 0) {
            c += (t % b);
            t /= b;
          }
          if(c == s) ans = Math.min(ans, b);
        }
      }
    }
    if(s == 1) ans = Math.min(ans, n);
    if(n == s) ans = Math.min(ans, n + 1);
    if(ans == (long)Math.pow(10, 12)) ans = -1;
    System.out.println(ans);
  }
}

