import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	long f(long b, long n) {
		if (n < b) return n;
		else return f(b, n / b) + n % b;
	}

	void solve() {
		long n = nl(), s = nl(), res = Long.MAX_VALUE;
		if (n < s) {
			out.println(-1);
			return;
		}
		if (n == s) {
			out.println(n + 1);
			return;
		}
		for (long b = 2; b * b <= n; ++b) {
			if (f(b, n) == s) {
				res = b;
				break;
			}
		}
		for (long p = 1; p * p <= n; ++p) {
			// n = p * b + q
			// s = p + q
			// b = (n - s) * p + 1
			long b = (n - s) * p + 1;
			long q = n - (p * b);
			if (n == p * b + q && s == p + q && b > q) {
				if (res > b) {
					res = b;
				}
			}
		}
		out.println(res == Long.MAX_VALUE ? -1 : res);
	}

	public static void main(String[] args) throws Exception {
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		new Main().solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G - S + "ms");
	}

	static boolean eof() {
		if (lenbuf == -1) return true;
		int lptr = ptrbuf;
		while (lptr < lenbuf)
			if (!isSpaceChar(inbuf[lptr++])) return false;

		try {
			is.mark(1000);
			while (true) {
				int b = is.read();
				if (b == -1) {
					is.reset();
					return true;
				} else if (!isSpaceChar(b)) {
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte() {
		if (lenbuf == -1) throw new InputMismatchException();
		if (ptrbuf >= lenbuf) {
			ptrbuf = 0;
			try {
				lenbuf = is.read(inbuf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (lenbuf <= 0) return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) {
		return !(c >= 33 && c <= 126);
	}

	private static int skip() {
		int b;
		while ((b = readByte()) != -1 && isSpaceChar(b))
			;
		return b;
	}

	static double nd() {
		return Double.parseDouble(ns());
	}

	static char nc() {
		return (char) skip();
	}

	private static String ns() {
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while (!(isSpaceChar(b))) { // when nextLine, (isSpaceChar(b) && b != ' ')
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n) {
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while (p < n && !(isSpaceChar(b))) {
			buf[p++] = (char) b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	static char[][] nm(int n, int m) {
		char[][] map = new char[n][];
		for (int i = 0; i < n; i++)
			map[i] = ns(m);
		return map;
	}

	static int[] na(int n) {
		int[] a = new int[n];
		for (int i = 0; i < n; i++)
			a[i] = ni();
		return a;
	}

	private static int ni() {
		int num = 0, b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	static long nl() {
		long num = 0;
		int b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	static void tr(Object... o) {
		if (INPUT.length() != 0) System.out.println(Arrays.deepToString(o));
	}

	static void debug(Object... o) {
		System.out.println(Arrays.deepToString(o));
	}
}

import java.util.*;

public class Main {
  public static void main(String[] args) throws Exception {
    Scanner scanner = new Scanner(System.in);
    long n = scanner.nextLong();
    long s = scanner.nextLong();
    if(n < s) {
      System.out.println(-1);
    } else if(n == s) {
      System.out.println(n+1);
    } else if(s == 1) {
      if(n > Math.pow(10, 11)) System.out.println(-1);
      else if(n == 1) System.out.println(2);
      else System.out.println(n);
    } else {
      boolean ok = false;
      double sqrtN = Math.sqrt(n);
      for(long i=2;i<sqrtN;i++) {
        if(f(i, n) == s) {
          System.out.println(i);
          ok = true;
          break;
        }
      }
      if(!ok) {
        for(long p=1;p<=sqrtN;p++) {
          if((n-s)%p != 0) continue;
          long b = (n-2)/p+1;
          if(f(b, n) == s) {
            System.out.println(b);
            ok = true;
            break;
          }
        }
      }
      if(!ok) System.out.println(-1);
    }

    scanner.close();
  }

  private static long f(long b, long n) {
    long ret = (n<b)? n : (f(b, (long)Math.floor(n/b))+n%b);
    return ret;
  }
}

