/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author amotoma3
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            long n = in.nextLong();
            long s = in.nextLong();

            if (n < s) {
                out.println(-1);
                return;
            }

            if (n == s) {
                out.println(n + 1);
                return;
            }

            long i = 2;
            while (i * i <= n) {
                long tmp = n;
                long sum = 0;
                while (tmp > 0) {
                    sum += tmp % i;
                    tmp /= i;
                }
                if (sum == s) {
                    out.println(i);
                    return;
                }
                i++;
            }
            while (i * i >= n) i--;
            while (i > 0) {
                long b = (n - s) / i + 1;
                if (n / b + n % b == s) {
                    out.println(b);
                    return;
                }
                i--;
            }

            out.println(-1);
        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(nextString());
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }
}

import java.util.*;
import java.lang.*;
import java.io.*;


public class Main {
    public static long givenFunc(long b, long n){
        if(b<=1) return -1;
        if (n<b) return n;
        else return givenFunc(b,n/b)+n%b;
    }
    public static long solve(long N, long S){
        //when b is small enough, we can check it with the definition of func
        for(long b=2;b*b<=N;b++){
        	if(givenFunc(b,N)==S) return b;
        }
        //if b>sqrt(N), N=pb+q and S=p+q where p<sqrt(n)
        for(long p=(int)Math.sqrt(N)+1;p>=1;p--){
        	long b = 1+(N-S)/p;
        	if(givenFunc(b,N)==S) return b;
        }
        return N==S ? N+1 : -1;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long S = sc.nextLong();
        System.out.println(solve(N,S));
    }
}

