// import java.awt.Point;

public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    static int mod = 1_000_000_007;
    // int mod = 998244353;
    long inf = Long.MAX_VALUE/2;


    void solve(){
        long n = nl();
        long s = nl();
        long mid = (long)Math.sqrt(n);
        long ans = inf;
        for(long i = 1; i <= mid; i++){
            long ret = calc_coef_sum(n, i);
            if(ret==s){
                ans = Math.min(ans, i);
            }
        }
        for(long i = 1; i <= mid; i++){
            long tmp = n-s;
            if(tmp<=0) continue;
            if((tmp%i)!=0) continue;
            long l = i + 1;
            long r = tmp/i + 1;
            long ret1 = calc_coef_sum(n, l);
            long ret2 = calc_coef_sum(n, r);
            if(ret1==s) ans = Math.min(ans, l);
            if(ret2==s) ans = Math.min(ans, r);
        }
        if(n==s){
            ans = Math.min(ans, n+1);
        }
        out.println(ans==inf ? -1 : ans);
    }

    long calc_coef_sum(long n, long b){
        long ret = 0;
        if(b<=1||b>=n) return -1;
        while(n>0){
            ret += n%b;
            n/=b;
        }
        return ret;
    }


    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.util.*;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		long n = sc.nextLong();
		long s = sc.nextLong();
		System.out.println(solve(n, s));
		sc.close();
	}

	static long solve(long n, long s) {
		if(n<s)
			return -1;
		if(n==s)
			return n+1;

		long ns = n-s;
		for(long i=2; i*i<=n || ns/(i-1)+i>=s; i++)
			if(f(n, i)==s)
				return i;
		long max=1;
		while(ns/max+max>=s)
			max++;
		for(; max>=1; max--)
			if(f(n, ns/max+1)==s)
				return ns/max+1;

		return -1;
	}

	static long f(long n, long b) {
		long ans = 0;
		while(n>0) {
			ans += n%b;
			n/=b;
		}
		return ans;
	}
}

