		public void solve(int testNumber, MyInput in, PrintWriter out) {

			long n = in.nextLong(), s = in.nextLong();

			if (s == 1) {
				out.println(n);
				return;
			}

			// 2 <= b <= sqrt(n)
			for (int b = 2; b * b <= n; b++) {
				long ss = f(b, n);
				if (ss == s) {
					out.println(b);
					return;
				}
			}

			// sqrt(n) <= b < n
			for (int p = 1; p * p < n; p++) {
