		out.close();
	}

	static int INF = 1 << 30;
	static long LINF = 1L << 55;
	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {

		public void solve(int testNumber, MyInput in, PrintWriter out) {

			long n = in.nextLong(), s = in.nextLong();

			// b = n
			if (s == n) {
				out.println(n+1);
				return;
			}

			if (n < s) {
				out.println(-1);
				return;
			}

			// 2 <= b <= sqrt(n)
			for (long b = 2; b * b <= n; b++) {
				long ss = f(b, n);
				if (ss == s) {
					out.println(b);
					return;
				}
			}

			// sqrt(n) <= b < n
			long ans = LINF;
			for (long p = 1; p * p <= n; p++) {
				if ((n - s) % p == 0) {
					long b = (n - s) / p + 1;
					long ss = f(b, n);
					if (ss == s) {
						ans = Math.min(ans, b);
					}
				}
			}

			out.println(ans == LINF ? -1 : ans);

		}

		long f(long b, long n) {
			long ret = 0;

			while (n > 0) {
				ret += n % b;
				n /= b;
			}

			return ret;
		}
	}

