	long f(long b, long n) {
		if (n < b) return n;
		return f(b, (long)Math.floor(n / b)) + n % b;
	}
	public void solve() {
		long n = in.nextLong(), s = in.nextLong();
		if (n == s) {
			System.out.println(n+1);
			return;
		} else if (n < s) {
			System.out.println(-1);
			return;
		}
		long res = Long.MAX_VALUE;
		for (long b = 2; b <= 401000; b++) {
			if (f(b, n) == s) 
				res = Math.min(res, b);
		}
		for (long p = 2; p <= 401000; p++) {
			long b = (n - s) / p + 1;
			if (b <= 1) continue;
			if (f(b, n) == s) 
				res = Math.min(b, res);
		}
		System.out.println(res != Long.MAX_VALUE ? res : -1);
		out.close();
	}

