		long n = nl(), s = nl(), res = Long.MAX_VALUE;
		if (n < s) {
			out.println(-1);
			return;
		}
		if (n == s) {
			out.println(n + 1);
			return;
		}
		for (long b = 2; b * b <= n; ++b) {
			if (f(b, n) == s) {
				res = b;
				break;
			}
		}
		for (long p = 1; p * p <= n; ++p) {
			// n = p * b + q
			// s = p + q
			// b = (n - s) * p + 1
			long b = (n - s) * p + 1;
			if (f(b, n) == s && res > b) {
				res = b;
			}
		}
		out.println(res == Long.MAX_VALUE ? -1 : res);
	}

