public class Solver
{
    const int LIMIT = 1000000;

    public void Solve()
    {
        long n = ReadLong();
        long m = ReadLong();

        if (n < m)
        {
            Write(-1);
            return;
        }
        else if (n == m)
        {
            Write(n + 1);
            return;
        }

        for (int i = 2; i <= LIMIT; i++)
        {
            long s = 0;
            long x = n;
            while (x > 0)
            {
                s += x % i;
                x /= i;
            }
            if (s == m)
            {
                Write(i);
                return;
            }
        }

        long ans = long.MaxValue;
        for (int i = 1; i <= m && 1L * i * LIMIT <= n; i++)
        {
            if ((n + i - m) % i == 0)
                ans = Math.Min(ans, (n + i - m) / i);
        }
        Write(ans < long.MaxValue ? ans : -1);
    }

