		List<int> list = new List<int>();
		for (int i = 2; i <= Math.Sqrt(n) + 0.5; i++)
		{
			long f = 0;
			long m = n;
			while (m > 0)
			{
				f += m % i;
				m /= i;
			}
			if (f == s)
			{
				Console.WriteLine(i);
				return;
			}
		}
		for (int i = 1; i <= Math.Sqrt(n - s) + 0.5; i++)
		{
			if ((n - s) % i == 0) list.Add(i);
		}
		for (int i = 1; i < list.Count; i++)
		{
			if (list[i] < Math.Sqrt(n)) continue;
			long b = list[i] + 1;
			long f = 0;
			long m = n;
			while (m > 0)
			{
				f += m % b;
				m /= b;
			}
			if (f == s)
			{
				Console.WriteLine(b);
				return;
			}
		}
		for (int i = list.Count - 1; i >= 0; i--)
		{
			long b = (n - s) / list[i] + 1;
			long f = 0;
			long m = n;
			while (m > 0)
			{
				f += m % b;
				m /= b;
			}
			if (f == s)
			{
				Console.WriteLine(b);
				return;
			}
		}
