		public class Calc {
			public void Solve() {
				long N = NextLong(), s = NextLong();
				if (N == s) {
					(s + 1).WL();
					return;
				}

				Func<long, long, long> f = null;
				f = (b, x) =>
				{
					if (x < b) return x;
					return f(b, x / b) + (x % b);
				};

				for (long i = 2; i * i <= N; i++) {
					if (f(i, N) != s) continue;
					i.WL();
					return;
				}

				for (long i = 1; i * i <= N; i++) {
					if ((N - s) % i != 0) continue;
					long b = (N - s) / i + 1;
					if (b <= 1 || f(b, N) != s) continue;
					b.WL();
					return;
				}

				"-1".WL();

				return;
			}
		}

	}
