public class Program
{
    private long N, S;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextLong();
        S = sc.NextLong();

        // NをB進表記 桁和がSになるB
        // 1桁
        if (N == S)
        {
            Console.WriteLine(N + 1);
            return;
        }

        // 3桁以上
        long b = 2;
        for (; b * b <= N; b++)
        {
            if (F(b, N) == S)
            {
                Console.WriteLine(b);
                return;
            }
        }

        // 2桁
        // aB + c = N
        // a + c = S
        // a(B-1) = N-S
        long ans = long.MaxValue;
        {
            long T = N - S;
            for (long a = 1; a * a <= T; a++)
            {
                if (T % a == 0)
                {
                    long c = T / a;
                    if(F(a+1,N) == S) ans = Math.Min(ans, a+1);
                    if (F(c + 1, N) == S) ans = Math.Min(ans, c + 1);
                }
            }
        }
        if (ans == long.MaxValue)
        {
            Console.WriteLine("-1");
            return;
        }
        Console.WriteLine(ans);
    }

    long F(long b, long n)
    {
        if (n < b) return n;
        return F(b, n / b) + (n % b);
    }

    public static void Main(string[] args) => new Program().Solve();
}

