namespace AtCoderProject
{
    public class Program
    {
        public object Calc()
        {
            var N = consoleReader.Long;
            var s = consoleReader.Long;

            var cal = new Cal(N);

            return cal.Calc(s);
        }
        class Cal
        {
            long N;
            public long[] cache;
            public Cal(long N)
            {
                this.N = N;
                if (N == 2)
                {
                    this.cache = new long[] { 0, 0, 1, 2 };
                }
                else
                {
                    this.cache = new long[(int)Math.Sqrt(N) + 1];
                    for (int i = 2; i < cache.Length; i++)
                        cache[i] = F(i, N);
                }
            }
            static long F(int b, long N)
            {
                if (N < b) return N;
                return F(b, N / b) + (N % b);
            }

            public long Calc(long s)
            {
                if (s > N) return -1;
                if (s == N) return N + 1;
                {
                    var c = Array.IndexOf(cache, s);
                    if (c > 0) return c;
                }
                var sqrt = cache.Length - 1;
                for (int i = sqrt - 1; i >= 1; i--)
                {
                    var ip = i + 1;
                    if (s < i || (double)N / ip + i <= s) continue;

                    if (N % i == s % i)
                    {
                        return N / i - s / i + 1;
                    }
                }
                return -1;
            }
        }

