    static void Main()
    {
        n = long.Parse(Console.ReadLine());
        s = long.Parse(Console.ReadLine());

        if (s == n)
        {
            Console.WriteLine(n + 1);
            return;
        }

        if (s == 1)
        {
            Console.WriteLine(n);
            return;
        }

        long u = (long)Math.Pow(n, 0.5);
        for (long b = 2; b <= u; b++)
        {
            long n_ = n;
            long sum = 0;
            while (n_ > 0)
            {
                sum += n_ % b;
                n_ /= b;
            }
            if (sum == s)
            {
                Console.WriteLine(b);
                return;
            }
        }

        if (n < s)
        {
            Console.WriteLine(-1);
            return;
        }

        for (long k = (long)((n - s) / (Math.Pow(n, 0.5) - 1)) + 1; k > 0; k--)
        {
            if ((n - s) % k != 0) continue;
            long p = 1 + (n - s) / k;
            if (k >= p || s - k >= p) continue;
            Console.WriteLine(p);
            return;
        }

        Console.WriteLine(-1);
    }
