		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		long N, S;
		void Read()
		{
			sc.Read(out N);
			sc.Read(out S);
		}
		void SolveOne()
		{
			for (var b = 2L; b * b <= N; b++) if (F(b, N) == S) { pr.WriteLine(b); return; }
			var div = new SortedSet<long>();
			var d = N - S;
			if (d > 0)
			{
				for (var i = 1L; i * i <= d; i++) if (d % i == 0) { div.Add(i); div.Add(d / i); }
				foreach (var x in div)
				{
					var b = x + 1;
					if (F(b, N) == S) { pr.WriteLine(b); return; }
				}
			}
			if (F(N + 1, N) == S) { pr.WriteLine(N + 1); return; }
			pr.WriteLine(-1);
		}
		long F(long b, long n)
		{
			var s = 0L;
			while (n > 0) { s += n % b; n /= b; }
			return s;
		}
	}
