class Program
{
	static void Main()
	{
		long n = long.Parse(Console.ReadLine());
    long s = long.Parse(Console.ReadLine());
		long answer = -1;
    long[] divisions = DivisionCompression(n);
    int divisionsCount = divisions.Length;
    long answerBack = 1;
    long answerNow = 0;

    for(int i = 0; i < divisionsCount; i++)
    {
      answerNow += divisions[i];
      if(i == 0) continue;

      if(divisions[i] == 1)
      {
        if(findSumOfDigits(n,answerNow) == s)
        {
          answer = answerNow;
          break;
        }
      }else
      {
        long div = n/answerNow;
        long rest = n%answerNow;
        long inter = n%(answerBack+1);
        long interCount = answerNow-(answerBack+1);
        inter /= interCount;

        if((s-div) % inter == rest)
        {
          long divMemo = (s-div)/inter;
          if(answerNow-divMemo > answerBack)
          {
            answer = answerNow-divMemo;
            //Console.WriteLine(answerBack+" "+answerNow+" "+divMemo);
            break;
          }
        }
      }

      answerBack = answerNow;
    }

    if(answer == -1)
    {
      if(n == s) answer = n+1;
    }

		Console.WriteLine(answer);
	}

  static long findSumOfDigits(long n, long x) 
  {//引数をnとして、nのx進数で各桁の数の和を求める
    long sum = 0;
    while (n > 0) 
    { // n が 0 になるまで
      sum += n % x;
      n /= x;
    }
    return sum;
  }

  static long[] DivisionCompression(long num)
  {//x=1~numまでを[n/x]の値で座標圧縮。配列の個数を2√numまで圧縮できる。
  //返り値の配列は圧縮前の個数。
  //例えばnum=10なら、[1,1,1,2,5]を返す。
    int dividesCount = (int)Math.Sqrt(num);
    long[] divides = new long[dividesCount+1];//前半の(x/i)の値
    long[] answers;
    for(int i = 0; i < dividesCount; i++)
    {
      divides[i] = num/(i+1);
    }

    if(divides[dividesCount-1] == dividesCount)
    {
      answers = new long[2*dividesCount-1];
      for(int i = 0; i < dividesCount; i++) answers[i] = 1;

      for(int i = 0; i < dividesCount-1; i++)
      {
        answers[dividesCount+i] = divides[dividesCount-2-i]-divides[dividesCount-1-i];
      }
    }else
    {
      answers = new long[2*dividesCount];
      for(int i = 0; i < dividesCount; i++) answers[i] = 1;

      divides[dividesCount] = dividesCount;
      for(int i = 0; i < dividesCount; i++)
      {
        answers[dividesCount+i] = divides[dividesCount-1-i]-divides[dividesCount-i];
      }
    }

    return answers;
  }

}

