            for (int i = (int)Math.Sqrt(N - S); i >= 1; i--) if (((N - S) % i) == 0) divisorNS.Add((N - S) / i);
            foreach (long b in divisorNS) if (digitSum(b + 1, N) == S) return b + 1;
            return -1;
        }
    }
