public class Program
{
    public void Solve()
    {
        long N = Reader.Long(), X = Reader.Long();
        if (N == X) { Console.WriteLine(N + 1); return; }
        long ans = long.MaxValue;
        long sqrt = (long)Math.Sqrt(N);

        Func<long, long> F = b =>
        {
            long sum = 0;
            for (long t = N; t > 0; t /= b)
                sum += t % b;
            return sum;
        };
        for (int i = 0; i <= sqrt; i++)
        {
            if (i >= 2 && F(i) == X) ans = Math.Min(ans, i);

            // N = a*b + i
            long a = X - i;
            if (a > 0 && N % a == 0 && N / a >= 2) ans = Math.Min(ans, N / a);
        }

        Console.WriteLine(ans == long.MaxValue ? -1 : ans);
    }
}


