        public void Run()
        {
            N = Input.ReadLong();
            S = Input.ReadLong();

            if (N == S)
            {
                Console.WriteLine(N+1);
            }
            else if (N < S)
            {
                Console.WriteLine(-1);
            }
            else
            {
                for (int i = 2; i < 1000000; i++)
                {
                    if (Success(i))
                    {
                        Console.WriteLine(i);
                        return;
                    }
                }

                for (int m = 1000000; m >= 1; m--)
                {
                    if (SuccessMod(m) != -1)
                    {
                        Console.WriteLine(SuccessMod(m));
                        return;
                    }
                }

                Console.WriteLine(-1);
            }
        }

        public bool Success(int b)
        {
            long s = 0;
            long n = N;
            while (n > 0)
            {
                s += n % b;
                n /= b;
            }
            return s == S;
        }

        public long SuccessMod(int m)
        {
            if (S - m < 0) return -1;
            long x = N - (S - m);
            if (x < 0) return -1;
            if (x % m != 0) return -1;
            long b = x / m;
            if (b <= S - m) return -1;
            return b;
        }
    }

