import "fmt"

func digit_sum(x, b int64) int64 {
    if b <= 1 {
        return 0
    }
    ret := int64(0)
    for x > 0 {
        ret += x % b
        x /= b
    }
    return ret
}

func solve(n, s int64) int64 {
    if s > n {
        return -1
    }
    if s == n {
        return n + 1
    }
    for b := int64(2); b * b <= n; b++ {
        if digit_sum(n, b) == s {
            return b
        }
    }
    for p := int64(1); p * p < n; p++ {
        b := (n - s) / p + 1
        if digit_sum(n, b) == s {
            return b
        }
    }
    return -1
}

func main() {
    var n, s int64
    fmt.Scan(&n, &s)
    fmt.Println(solve(n, s))
}

package main

import (
	"bufio"
