}

func f(b, n int) int {
  cnt := 0
  for n > 0 {
    cnt += n % b
    n /= b
  }
  return cnt
}

func main() {
  n := NextInt()
  s := NextInt()
  sqrt := int(math.Sqrt(float64(n)))
  F := make([]int, sqrt + 1)
  ans := -1
  for b := 2; b < sqrt + 1; b++ {
    if F[b] < 0 { continue }
    fbn := f(b, n)
    if fbn == s {
