    b := n + 1
    for b1 := 1; b1 < sqrt; b1++ {
      b0 := s - b1
      if n < b0 { continue }
      if b0 < 0 { break }
      if (n - b0) % b1 > 0 { continue }
      _b := (n - b0) / b1
      if _b <= b0 { continue }
      if _b < b { b = _b }
    }
    if b < n + 1 { ans = b }
    if s == 1 { ans = n }
    if n == s { ans = n + 1 }
  }
  Write(ans)
  Output()
}

