func main() {
  var n,s,m int64
  fmt.Scan(&n)
  fmt.Scan(&s)
  if s == n {
    fmt.Println(n+1)
    os.Exit(0)
  }
  m = int64(math.Sqrt(float64(n)))
  for b:=int64(2);b<=m;b++ {
    if f(b,n) == s {
      fmt.Println(b)
      os.Exit(0)
    }
  }
  for p:=m;p>0;p-- {
    if (n-s)%p != 0 { continue }
    b := (n-s)/p+1
    if b < 2 { continue }
    if f(b,n) == s {
      fmt.Println(b)
      os.Exit(0)
    }
  }
  fmt.Println(-1)
}
func f(b int64,n int64) int64 {
  if n < b { return n }
  return f(b,n/b)+n%b
}

