var errNoBase = errors.New("no such base exists")

func digitSum(n, b int64) int64 {
	var ret int64
	for n > 0 {
		ret += n % b
		n /= b
	}
	return ret
}

func solve(n, s int64) (int64, error) {
	if s > n {
		return 0, errNoBase
	} else if s == n {
		return n + 1, nil
	}

	d := n - s
	var ans int64
	for i := int64(1); i*i <= d; i++ {
		if d%i != 0 {
			continue
		}

		if digitSum(n, i+1) == s {
			return i + 1, nil
		}
		if di := d / i; digitSum(n, di+1) == s {
			ans = di + 1
		}
	}

	if ans != 0 {
		return ans, nil
	}
	return 0, errNoBase
}

func main() {
	var n, s int64
	fmt.Scan(&n, &s)

	res, err := solve(n, s)
	if err == nil {
		fmt.Println(res)
	} else {
		fmt.Println("-1")
	}
}

