    long s = scan!long;

    long infty = n * s + 99;
    long ans = infty;
    for(long b = 2; b * b <= n; b ++) if(digsum(n, b) == s) ans.lowerTo(b);

    long[] ds = (n - s).divisors;
    foreach(d; ds) if(digsum(n, d + 1) == s) ans.lowerTo(d + 1);

    if(n == s) ans.lowerTo(n + 1);

    ans.writeln;
}

long digsum(long n, long b){
    long ans;
    log("n:", n, "b:", b);
    while(n > 0){
        log(n % b);
        ans += n % b;
        n /= b;
    }
    log("sum:", ans);
    return ans;
}

/// 約数の集合
/// 1とその数自身も含む、正の約数の集合。
/// 例 divisors(48) = [1, 2, 3, 4, 6, 8, 12, 16, 24, 48]
/// O(√N)
long[] divisors(long a){
	long[] res, res2;
	for(long d = 1; d * d <= a; d ++){
		if(a % d == 0) res ~= d, res2 ~=  a / d;
	}
	foreach_reverse(d; res2) if(res[$ - 1] < d) res ~= d;
	return res;
}

