BigInt f(BigInt b, BigInt n) {
    if(n < b) {
        return n;
    }
    return f(b, n/b) + (n%b);
}

void main(){
    BigInt n = readLong();
    BigInt s = readLong();
    if(s > n) {
        writeln(-1);
        return;
    }
    if(s == n) {
        writeln(n+1);
        return;
    }
    for(BigInt i = 2; i * i <= n; ++i) {
        if(f(i, n) == s) {
            writeln(i);
            return;
        }
    }
    BigInt ans = -1;
    for(BigInt i = 1; i*i < n; ++i) {
        BigInt k0 = s-i;
        if(k0 < 0) {
            continue;
        }
        if((n-k0)%i == 0) {
            auto b = (n-k0)/i;
            if(b*b <= n) {
                continue;
            }
            if(k0 >= b) {
                continue;
            }
            if(i >= b) {
                continue;
            }
            ans = b;
        }
    }
    writeln(ans);
}

