long f(long b, long n)
{
    long r;
    while (n) {
        r += n%b;
        n /= b;
    }
    return r;
}

void main()
{
    auto n = readln.chomp.to!long;
    auto s = readln.chomp.to!long;

    if (n == s) {
        writeln(n + 1);
    } else if (s == 1) {
        writeln(n);
    } else {
        long i = 1;
        for (;;) {
            if ((++i)^^2 > n) break;
            if (f(i, n) == s) {
                writeln(i);
                return;
            }
        }
        i = 1;
        for (;;) {
            if ((++i)^^2 > n) break;
            auto j = s - i;
            if (j < 0) break;
            auto b = (n-j)/i;
            if (b < 0) continue;
            if (f(b, n) == s) {
                writeln(b);
                return;
            }
        }
        writeln("-1");
    }
}

