def f(b, n):
    s = 0
    while n > 0:
        s += n % b
        n //= b
    return s

def solve(n, s):
    m = int(np.sqrt(n)) + 1
    for b in range(2, m):
        if f(b, n) == s:
            return b
    for p in range(1, m):
        q = s - p
        if (n - q) % p != 0:
            continue
        b = (n - q) // p
        if (b > 1) and (f(b, n) == s):
            return b
    return -1

