  res = []
  while x > 1:
    for p in range(2, int((x+1)**0.5+1)):
      if x % p == 0:
        res.append(p)
        x //= p
        break
    else:
      res.append(x)
      break
  return res

def prod(xs):
  res = 1
  for x in xs:
    res *= x
  return res

