fn f(b: i64, n: i64) -> i64 {
    return if n < b {
        n
    } else {
        f(b, n / b) + n % b
    };
}

fn main() {
    let mut rd = reader::Reader::new();

    let n: i64 = rd.next();
    let s: i64 = rd.next();

    if n < s {
        println!("-1");
        return;
    }

    if n == s {
        println!("{}", n + 1);
        return;
    }

    for i in 2..1000000i64 {
        if f(i, n) == s {
            println!("{}", i);
            return;
        }
    }

    let mut b = (n as f64).sqrt() as i64;
    for l in (1..b + 1).rev() {
        let r = n % b;
        let x = s - l;
//        debug!("b={}, l={}, r={}", b, l, r);
        if r % l <= x && x <= r && ((x - r % l) % l) == 0 {
            println!("{}", b + (r - (s - l)) / l);
            return;
        }
        b += r / l + 1;
    }
    println!("-1");
}

mod reader {
    use std::fmt::Debug;
    use std::str::FromStr;
    use std::collections::VecDeque;
    use std::io::{self, Read};

    fn _read_line() -> String {
        let mut buf = String::new();
        let _ = io::stdin().read_to_string(&mut buf);
        buf
    }

    fn _read_vec_deque_string() -> VecDeque<String> {
        _read_line()
            .split_whitespace()
            .map(|s| s.to_string())
            .collect()
    }

    pub struct Reader {
        buf: VecDeque<String>,
    }

    impl Reader {
        pub fn new() -> Reader {
            Reader { buf: VecDeque::new() }
        }

        fn update_buf(&mut self) {
            if self.buf.is_empty() {
                self.buf = _read_vec_deque_string();
            }
        }

        pub fn next<T>(&mut self) -> T
            where
                T: FromStr,
                T::Err: Debug,
        {
            self.update_buf();
            self.buf.pop_front().unwrap().parse::<T>().unwrap()
        }

        pub fn next_n<T>(&mut self, n: usize) -> Vec<T>
            where
                T: FromStr,
                T::Err: Debug,
        {
            let mut vec: Vec<T> = Vec::with_capacity(n);

            for _ in 0..n {
                vec.push(self.next());
            }
            vec
        }
    }
}

