fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

fn func(b: u64, n: u64) -> u64 {
    if n < b {
        return n;
    }
    func(b, n / b) + n % b
}

fn solve() {
    let n: u64 = read();
    let s: u64 = read();
    if s > n {
        println!("-1");
        return;
    }
    if s == n {
        println!("{}", n + 1);
        return;
    }
    for b in 2..((n as f64).sqrt() as u64 + 1) {
        if func(b, n) == s {
            println!("{}", b);
            return;
        }
    }
    for p in (1..((n as f64).sqrt() as u64 + 1)).rev() {
        if (n - s) % p != 0 {
            continue;
        }
        let b = (n - s) / p + 1;
        if func(b, n) == s {
            println!("{}", b);
            return;
        }
    }
    println!("-1");
}

fn main() {
    std::thread::Builder::new()
        .name("big stack size".into())
        .stack_size(32 * 1024 * 1024) // 32 MBのスタックサイズ
        .spawn(|| {solve()})
        .unwrap()
        .join()
        .unwrap();
}

