fn f(b: u64, n: u64) -> u64 {
    if n == 0 {
        0
    } else {
        n % b + f(b, n / b)
    }
}

fn solve() {
    let n = get!(u64);
    let s = get!(u64);

    if s > n {
        println!("-1");
        return;
    }

    if let Some(ans) = (2..).take_while(|&x| x * x <= n).find(|&x| f(x, n) == s) {
        println!("{}", ans);
    } else {
        if let Some(ans) = (1..)
            .take_while(|&x| x * x <= n)
            .collect::<Vec<_>>()
            .into_iter()
            .rev()
            .filter_map(|p| {
                let b = (n - s) / p + 1;
