fn main() {
    use std::thread;
    if BIG_STACK_SIZE {
        thread::Builder::new()
            .stack_size(32 * 1024 * 1024)
            .name("solve".into())
            .spawn(solve)
            .unwrap()
            .join()
            .unwrap();
    } else {
        solve();
    }
}

fn f(b: u64, n: u64) -> u64 {
    if n == 0 {
        0
    } else {
        n % b + f(b, n / b)
    }
}

fn solve() {
    let n = get!(u64);
    let s = get!(u64);

    if s > n {
        println!("-1");
        return;
    }

    if let Some(ans) = (2..).take_while(|&x| x * x <= n).find(|&x| f(x, n) == s) {
        println!("{}", ans);
    } else {
        if let Some(ans) = (1..)
            .take_while(|&x| x * x <= n)
            .filter_map(|p| {
                let b = (n - s) / p + 1;
                if f(b, n) == s {
                    Some(b)
                } else {
                    None
                }
            })
            .min()
        {
            println!("{}", ans);
        } else {
            println!("-1");
        }
    }
}

