use std::str::FromStr;
use std::io::*;
use utils::*;

pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = AtRead::from(i);
    let n = i.read::<usize>();
    let s = i.read::<usize>();

    let result = if let Some(r) = solve(n, s) {
        r.to_string()
    } else {
        "-1".to_string()
    };
    writeln!(o, "{}", result).unwrap();
}
fn solve(n: usize, s: usize) -> Option<usize> {
    fn f(b: usize, n: usize) -> usize {
        if n < b {
            n
        } else {
            n % b + f(b, n / b)
        }
    }
    let mut result = None;
    if n == s {
        result = Some(n + 1);
    }
    if n < s {
        return None;
    }

    let mut b_last = n + 1;
    for s1 in 1..s + 1 {
        let s0 = s - s1;
        let n1 = n - s0;
        let b = n1 / s1;
        if s1 >= b {
            break;
        }
        b_last = b;
        if n1 % s1 == 0 && s0 < b {
            result = Some(b);
        }
    }
    if s == 1 {
        return result;
    }

    for b in 2..b_last {
        if f(b, n) == s {
            return Some(b);
        }
    }
    result
}

mod utils {
    use super::*;

    pub struct AtRead<R: BufRead> {
        r: R,
        s: String,
    }

    impl<R: BufRead> AtRead<R> {
        pub fn from(r: R) -> Self {
            AtRead {
                r: r,
                s: String::new(),
            }
        }
        pub fn read_line(&mut self) -> &str {
            self.s.clear();
            self.r.read_line(&mut self.s).unwrap();
            self.s.trim()
        }

        pub fn read<T: FromStr>(&mut self) -> T {
            self.read_line().parse().ok().unwrap()
        }
    }
}

