fn f(b: i64, n: i64) -> i64 {
    if n < b {
        n
    } else {
        f(b, n / b) + n % b
    }
}

fn bis<P>(ok: i64, ng: i64, p: P) -> i64
    where P : Fn(i64) -> bool {
    let mid = (ok + ng) / 2;
    if (ok - ng).abs() == 1 {
        ok
    } else if p(mid) {
        bis(mid, ng, p)
    } else {
        bis(ok, mid, p)
    }
}

