fn two_digit(n: u64, s: u64) -> Option<u64> {
    (1..(n.saturating_sub(s) as f64).sqrt() as u64 + 1).rev().find(|&p| {
        (n-s) % p == 0 && {
            let (n, s, p) = (n as i64, s as i64, p as i64);
            let q = (n-s) / p;
            dbg!((p, q));
            n - p*(q+1) == s-p && 0 <= s-p && s-p < q+1
        }
    }).map(|p| (n-s) / p + 1)
}

