        s: u64,
    }

    if s == n {
        println!("{}", s);
        return;
    }

    if s > n {
        println!("-1");
        return;
    }

    let rn = (n as f64).sqrt() as u64;
    for b in 2..rn + 1 {
        let ans = f(b, n);
        if ans == s {
            println!("{}", b);
            return;
        }
    }

    for p in (1..rn + 1).rev() {
        let b = (n - s) / p + 1;
        let ans = f(b, n);
        if ans == s {
            println!("{}", b);
            return;
        }
    }

    println!("-1");
    return;
}

