fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: u64 = sc.read();
    let s: u64 = sc.read();

    for b in 2.. {
        if b * b > n {
            break;
        }
        if f(b, n) == s {
            println!("{}", b);
            return;
        }
    }

    // b*b > n
    // a*b + c = n
    // a + c = s
    // a*(b-1) = n - s
    if n >= s {
        let mut c = vec![];
        let m = n - s;
        for d in 1.. {
            if d * d > m {
                break;
            }
            if m % d == 0 {
                c.push(m / d);
                c.push(d);
            }
        }

        c.sort();
        for c in c.into_iter() {
            let b = c + 1;
            if f(b, n) == s {
                println!("{}", b);
                return;
            }
        }
    }

    if n == s {
        println!("{}", n + 1);
    } else {
        println!("-1");
    }
