fn f(b: i64, n: i64) -> i64 {
    if n < b {
        n
    } else {
        f(b, n / b) + n % b
    }
}

const N: i64 = 1000000;

fn main() {
    let mut rd = reader::Reader::new();

    let n: i64 = rd.next();
    let s: i64 = rd.next();

    if n == s {
        println!("{}", n + 1);
        return;
    }

    for i in 2..N {
        if f(i, n) == s {
            println!("{}", i);
            return;
        }
    }

    let mut ans: i64 = -1;
    for i in 1..N {
        let b = n / i;
        if b < 2 || i * i > n {
            break;
        }
        let r = n % b;
        let nb = n / (i + 1) + 1;

        debug!("i = {}, b = {}, r = {}, nb = {}", i, b, r, nb);
        let lb = f(b, n);
        let ub = f(nb, n);

        debug!("lb = {}, ub = {}", lb, ub);
        if lb <= s && s <= ub && (s - n % b) % i == 0 {
            ans = b - (s - i) / i;
            debug!("cand = {}, f(n, b) = {}", ans, f(ans, n));
        }
    }
    println!("{}", ans);
}

mod reader {
    use std::fmt::Debug;
    use std::str::FromStr;
    use std::collections::VecDeque;
    use std::io::{self, Read};

    fn _read_line() -> String {
        let mut buf = String::new();
        let _ = io::stdin().read_to_string(&mut buf);
        buf
    }

    fn _read_vec_deque_string() -> VecDeque<String> {
        _read_line()
            .split_whitespace()
            .map(|s| s.to_string())
            .collect()
    }

    #[allow(dead_code)]
    pub struct Reader {
        buf: VecDeque<String>,
    }

    #[allow(dead_code)]
    impl Reader {
        pub fn new() -> Reader {
            Reader { buf: VecDeque::new() }
        }

        fn update_buf(&mut self) {
            if self.buf.is_empty() {
                self.buf = _read_vec_deque_string();
            }
        }

        pub fn next<T>(&mut self) -> T
            where
                T: FromStr,
                T::Err: Debug,
        {
            self.update_buf();
            self.buf.pop_front().unwrap().parse::<T>().unwrap()
        }

        pub fn next_n<T>(&mut self, n: usize) -> Vec<T>
            where
                T: FromStr,
                T::Err: Debug,
        {
            let mut vec: Vec<T> = Vec::with_capacity(n);

            for _ in 0..n {
                vec.push(self.next());
            }
            vec
        }
    }
}

