    }
}

fn f(b: u64, n: u64) -> u64 {
    if n == 0 {
        0
    } else {
        n % b + f(b, n / b)
    }
}

fn solve() {
    let n = get!(u64);
    let s = get!(u64);

    let mut l = 2;
    let mut r = max(n, 2);

    while r - l > 100000 {
        let mid = (l + r) / 2;
        if f(mid, n) > s {
            r = mid;
        } else {
            l = mid;
        }
    }

    if let Some(ans) = (l..r + 1).find(|&x| f(x, n) == s) {
        println!("{}", ans);
    } else {
        if s == 1 {
            println!("{}", n);
        } else {
            println!("-1");
        }
    }
}

