fn f(b: usize, mut n: usize) -> usize {
    let mut res = 0;
    while n > 0 {
        res += n % b;
        n /= b;
    }
    res
}

fn main() {
    input!(n: usize, s: usize);

    for b in 2..1000000 {
        if f(b, n) == s {
            println!("{}", b);
            return;
        }
    }

    // s =p+q, n=pb + q
    if n > s {
        for p in 1..1000000 {
            if (n - s) % p != 0 {
                continue;
            }
            let b = (n - s) / p + 1;
            if f(b, n) == s {
                println!("{}", b);
                return;
            }
        }
    }

    if s == 1 {
        println!("{}", n);
    } else if n == s {
        println!("{}", n + 1);
    } else {
        println!("{}", -1);
    }
}

