pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = AtRead::from(i);
    let n = i.read::<usize>();
    let s = i.read::<usize>();

    let result = if let Some(r) = solve(n, s) {
        r.to_string()
    } else {
        "-1".to_string()
    };
    writeln!(o, "{}", result).unwrap();
}
fn solve(n: usize, s: usize) -> Option<usize> {
    fn f(b: usize, n: usize) -> usize {
        if n < b {
            n
        } else {
            n % b + f(b, n / b)
        }
    }
    let mut result = None;
    if n == s {
        result = Some(n + 1);
    }
    if n < s {
        return None;
    }

    let b_end = (n as f64).sqrt() as usize;

    for b in 2..b_end + 1 {
        if f(b, n) == s {
            return Some(b);
        }
    }

    for s1 in 1..s + 1 {
        let s0 = s - s1;
        let n1 = n - s0;
        let b = n1 / s1;
        if s1 >= b {
            break;
        }
        if n1 % s1 == 0 && s0 < b {
            result = Some(b);
        }
    }
    result
}

