fn f(b: u64, n: u64, acc: u64) -> u64 {
    if n < b {
        acc + n
    } else {
        f(b, n/b, acc + n%b)
    }
}

fn solve_for_two_digit(n: u64, s: u64) -> Option<u64> {
    let m = n - s;
    (1..((m as f64).sqrt() as u64 + 1)).filter(|&p| {
        m % p == 0 && {
            let a1 = p;
            let b = m / p + 1;
            let a0_0 = n.checked_sub(b * a1);
            let a0_1 = s.checked_sub(a1);
            match (a0_0, a0_1) {
                (Some(a0_0), Some(a0_1)) => a0_0 == a0_1 && a0_0 < b,
                _ => false
            }
        }
    }).rev().next().map(|p| m / p + 1)
}

fn main() {
    readls!(n = u64, s = u64);
    let ans = if n < s {
        None
    } else if n == s {
        Some(n+1)
    } else {
        let m = (n as f64).sqrt() as u64 + 1;
        (2..m).find(|&b| f(b, n, 0) == s).or_else(|| solve_for_two_digit(n, s))
    };
    println!("{}", ans.map(|n| n.to_string()).unwrap_or("-1".to_string()));
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
