fn f(b: u64, n: u64) -> u64 {
    if n == 0 {
        0
    } else {
        n % b + f(b, n / b)
    }
}

fn solve() {
    let n = get!(u64);
    let s = get!(u64);

    if let Some(ans) = (2..).take_while(|&x| x * x <= n).find(|&x| f(x, n) == s) {
        println!("{}", ans);
    } else {
        if let Some(ans) = (1..)
            .take_while(|&x| x * x <= n && s >= x)
            .filter_map(|p| {
                let q = s - p;
                if n < q {
                    return None;
                }
                if (n - q) % p != 0 {
                    return None;
                }
                let b = (n - q) / p;
                if q < b {
                    Some(b)
                } else {
                    None
                }
            })
            .min()
        {
            println!("{}", ans);
        } else {
            println!("-1");
        }
    }
}

