fn f(b: usize, n: usize) -> usize {
    if n < b {
        return n;
    } else {
        return f(b, n / b) + n % b;
    }
}

fn keta(b: usize, n: usize, depth: usize) -> usize {
    if b <= 1 {
        return n;
    }

    if n < b {
        return depth + 1;
    } else {
        return keta(b, n / b, depth + 1);
    }
}

