    let mut b1 = 0;
    let mut b2 = 0;
    let mut l = 2;
    let mut r = N + 1;
    while r - l > 1 {
        let m = (l + r) / 2;
        let k = keta(m, N, 0);
        if k > S {
            l = m;
        } else {
            r = m;
        }
    }
    b1 = l;
    let mut l = 2;
    let mut r = N + 1;
    while r - l > 1 {
        let m = (l + r) / 2;
        let k = keta(m, N, 0);
        if k.saturating_mul(m - 1) > S {
            l = m;
        } else {
            r = m;
        }
    }
    b2 = l;

    mydbg!(b1, b2);

    for b in b1..b2 + 1 {
        let c = f(b, N);
        //mydbg!(b, c, N);
        if c == S {
            ans = b as i64;
            break;
        }
    }

    echo!(ans);
