fn main() {
  let n = get::val::<usize>();
  let s = get::val::<usize>();

  if s == n {println!("{}", s+1); return}

  let fsqrt = |x| (x as f64).sqrt().floor() as usize;
  let csqrt = |x| (x as f64).sqrt().ceil() as usize;

  for b in 2..fsqrt(n)+1 {
    if f(b,n) == s {println!("{}",b); return}
  }

  for p in 1..csqrt(n) {
    let b = (n - s) / p + 1;
    if fsqrt(n) < b && b <= n && f(b,n) == s {println!("{}",b); return}
  }

  println!("-1")
}

