const INF: i64 = 1_000_000_000_000;

fn main() {
    let n: i64 = read();
    let s: i64 = read();


    let b0 = solveSmall(n, s);
    let b1 = solveLarge(n, s);


    if min(b0, b1) == INF {
        println!("-1");
    } else {
        println!("{}", min(b0, b1));
    }
}

fn solveSmall(n: i64, s: i64) -> i64 {
    for b in 2..n+1 {
        if b * b > n {
            break
        }
        if f(n, b) == s {
            return b;
        }
    }
    INF
}

fn f(n: i64, b: i64) -> i64 {
    let mut nn = n;
    let mut sum = 0;
    while nn >= 1 {
        sum += nn % b;
        nn /= b;
    }
    sum
}

fn solveLarge(n: i64, s: i64) -> i64 {
    if n == s {
        return n + 1;
    }

    let am1 = n - s;
    let mut best = INF;
    for a in 1..(am1+1) {
        if a * a > am1 {
            break
        }
        if am1 % a != 0 {
            continue
        }
        let m = am1 / a + 1;
        if f(n, m) == s {
            best = min(best, m);
        }
    }
    best
}

